window.L5R_CHARACTER = {"slug":"hiruma-kaede","name":"Hiruma Kaede","clan":"Crab","family":"Hiruma","school":"Hida Defender School","role":"Bushi","bucket":"Bushi","campaign":null,"status":null,"accent":"#492886","portrait":"src/portraits/hiruma-kaede.png","concept":null,"summary":null,"tier_count":8,"xp_min":0,"xp_max":279,"twenty_questions":{"template":"core","generated":true,"steps":{"step1":{"answers":{"clan":"Crab","ring":"earth","skill":"fitness","social_status":30},"picks":{}},"step2":{"answers":{"family":"Hiruma","ring":"air","skill1":"skulduggery","skill2":"survival","wealth":3,"social_glory":39},"picks":{}},"step3":{"answers":{"school":"Hida Defender School","roles":"Bushi","ring1":"void","ring2":"fire","skill1":"melee","skill2":"fitness","skill3":"survival","skill4":"command","skill5":"tactics","social_honor":40},"picks":{"techniques":["Striking as Earth","Lord Hida’s Grip (Crab)"],"school_ability":["Way of the Crab"],"equipment":["Lacquered Armor","Traveling Clothes","Club","Katana","Knife","Tetsubō","Wakizashi","Traveling pack"]}},"step4":{"answers":{"stand_out":"Careful observation of physical phenomena.","ring":"earth"},"picks":{}},"step5":{"answers":{"social_giri":"Hiruma Nobuyasu is their lord. They insist that she command her unit, defending the Kaiu Wall."},"picks":{}},"step6":{"answers":{"social_ninjo":"Longs to travel Rokugan, or possibly even beyond."},"picks":{}},"step7":{"answers":{"clan_relations":"She has commanded her clan's respect.","social_add_glory":5},"picks":{}},"step8":{"answers":{"bushido":"Bushido maintains order and strength.","social_add_honor":10,"tenet_paramount":"Courage","tenet_less_significant":"Sincerity"},"picks":{}},"step9":{"answers":{"success":"Held a section of the Kaiu wall against a trio of trolls."},"picks":{"distinction":["Light Sleeper"]}},"step10":{"answers":{"difficulty":"She struggles to stand up for herself."},"picks":{"adversity":["Encompassing Duty"]}},"step11":{"answers":{"calms":"Travel, particularly into the wilderness, fills her with peace."},"picks":{"passion":["Travel"]}},"step12":{"answers":{"worries":"She thinks back on the horrors she has witnessed, the men who have died... and she doesn't feel anything. And she's concerned about what that says about her."},"picks":{"anxiety":["Battle Trauma"]}},"step13":{"answers":{"most_learn":"Hida Nao. She trained under Nao, and the training was fierce, and some failed, but Kaede discovered her power."},"picks":{"advantage":["Paragon of Courage"]}},"step14":{"answers":{"first_sight":"Her armor and clothing do not match, but appear to be of varying age and provenance."},"picks":{"special_features":["Kubi Bukuro"]}},"step15":{"answers":{"stress":"Sullen resentment."},"picks":{}},"step16":{"answers":{"relations":"Has once done a joint patrol with the Unicorn clan, alongside the outrider Shinjo Tomiko.\n\nHas a grudging respect for the Dragon clan's Kitsuki investigators."},"picks":{"item":["Kamayari"]}},"step17":{"answers":{"parents_pov":"Kaede was an obedient and quiet child. They had hoped military service would anchor her, but they worry that she's become too hardened.","skill":"courtesy"},"picks":{}},"step18":{"answers":{"heritage_name":"She was named after her relative, who had broken through ranks of hellish creatures and claimed land far from the Kaiu Wall, and held it for three weeks.","heritage_1":9,"heritage_2":9,"heritage_add_honor":-5,"heritage_add_glory":0,"heritage_add_status":0,"skill":"tactics"},"picks":{}},"step19":{"answers":{"firstname":"Kaede"},"picks":{}},"step20":{"answers":{"death":"She will die at the hands of a stranger she meets on a road, far from Crab lands."},"picks":{}}}},"notes":"","curriculum":[{"rank":1,"kind":"Skill Group","group":null,"label":"Martial Skills","prereq":false},{"rank":1,"kind":"Skill","group":null,"label":"Command","prereq":false},{"rank":1,"kind":"Skill","group":null,"label":"Medicine","prereq":false},{"rank":1,"kind":"Skill","group":null,"label":"Survival","prereq":false},{"rank":1,"kind":"Tech. Grp.","group":"kata","label":"Rank 1 Kata","prereq":false},{"rank":1,"kind":"Technique","group":"kata","label":"Rushing Avalanche Style","prereq":true},{"rank":1,"kind":"Technique","group":"shuji","label":"Honest Assessment","prereq":false},{"rank":2,"kind":"Skill Group","group":null,"label":"Martial Skills","prereq":false},{"rank":2,"kind":"Skill","group":null,"label":"Command","prereq":false},{"rank":2,"kind":"Skill","group":null,"label":"Labor","prereq":false},{"rank":2,"kind":"Skill","group":null,"label":"Theology","prereq":false},{"rank":2,"kind":"Tech. Grp.","group":"kata","label":"Rank 1-2 Kata","prereq":false},{"rank":2,"kind":"Technique","group":"shuji","label":"Touchstone of Courage","prereq":true},{"rank":2,"kind":"Technique","group":"shuji","label":"Slippery Maneuvers","prereq":false},{"rank":3,"kind":"Skill Group","group":null,"label":"Trade Skills","prereq":false},{"rank":3,"kind":"Skill","group":null,"label":"Fitness","prereq":false},{"rank":3,"kind":"Skill","group":null,"label":"Martial Arts [Melee]","prereq":false},{"rank":3,"kind":"Skill","group":null,"label":"Meditation","prereq":false},{"rank":3,"kind":"Tech. Grp.","group":"kata","label":"Rank 1-3 Kata","prereq":false},{"rank":3,"kind":"Technique","group":"kata","label":"Iron in the Mountains Style","prereq":true},{"rank":3,"kind":"Technique","group":"shuji","label":"Rallying Cry","prereq":false},{"rank":4,"kind":"Skill Group","group":null,"label":"Scholar Skills","prereq":false},{"rank":4,"kind":"Skill","group":null,"label":"Fitness","prereq":false},{"rank":4,"kind":"Skill","group":null,"label":"Martial Arts [Melee]","prereq":false},{"rank":4,"kind":"Skill","group":null,"label":"Meditation","prereq":false},{"rank":4,"kind":"Tech. Grp.","group":"kata","label":"Rank 1-4 Kata","prereq":false},{"rank":4,"kind":"Technique","group":"kata","label":"Striking as Void","prereq":true},{"rank":4,"kind":"Technique","group":"shuji","label":"A Samurai’s Fate","prereq":false},{"rank":5,"kind":"Skill Group","group":null,"label":"Martial Skills","prereq":false},{"rank":5,"kind":"Skill","group":null,"label":"Command","prereq":false},{"rank":5,"kind":"Skill","group":null,"label":"Survival","prereq":false},{"rank":5,"kind":"Skill","group":null,"label":"Theology","prereq":false},{"rank":5,"kind":"Tech. Grp.","group":"kata","label":"Rank 1-5 Kata","prereq":false},{"rank":5,"kind":"Technique","group":"shuji","label":"Rouse the Soul","prereq":false},{"rank":5,"kind":"Technique","group":"shuji","label":"The Immovable Hand of Peace","prereq":false}],"title_curricula":{"general":{"title":"General","ability":"Superior Command","status_award":"+25 (to a maximum of 85)","entries":[{"kind":"Skill Group","group":null,"label":"Social Skills","prereq":false},{"kind":"Skill Group","group":null,"label":"Martial Skills","prereq":false},{"kind":"Skill","group":null,"label":"Government","prereq":false},{"kind":"Skill","group":null,"label":"Survival","prereq":false},{"kind":"Tech. Grp.","group":"kata","label":"Rank 1-2 Kata","prereq":true},{"kind":"Tech. Grp.","group":"ritual","label":"Rank 1-3 Rituals","prereq":true},{"kind":"Tech. Grp.","group":"shuji","label":"Rank 1-4 Shuji","prereq":true}]},"gunso":{"title":"Gunsō","ability":"Lead from the Front","status_award":"+5 (to a minimum of 20)","entries":[{"kind":"Skill Group","group":null,"label":"Martial Skills","prereq":false},{"kind":"Skill","group":null,"label":"Command","prereq":false},{"kind":"Skill","group":null,"label":"Government","prereq":false},{"kind":"Tech. Grp.","group":"kata","label":"Rank 1-4 Kata","prereq":false},{"kind":"Technique","group":"shuji","label":"Rallying Cry","prereq":true},{"kind":"Technique","group":"shuji","label":"Stirring the Embers","prereq":true},{"kind":"Technique","group":"shuji","label":"Touchstone of Courage","prereq":true}]}},"tiers":[{"xp":0,"label":null,"rank":1,"school":"Hida Defender School","foundry_id":"s4k9f0SUcWTel4ci","rings":{"air":2,"earth":3,"fire":2,"water":1,"void":2},"skills":{"artisan":{"aesthetics":0,"composition":0,"design":0,"smithing":0},"martial":{"fitness":2,"melee":1,"ranged":0,"unarmed":0,"meditation":0,"tactics":2},"scholar":{"culture":0,"government":0,"medicine":0,"sentiment":0,"theology":0},"social":{"command":1,"courtesy":1,"games":0,"performance":0},"trade":{"commerce":0,"labor":0,"seafaring":0,"skulduggery":1,"survival":2}},"social":{"honor":45,"glory":44,"status":30,"ninjo":"Longs to travel Rokugan, or possibly even beyond.","giri":"Hiruma Nobuyasu is their lord. They insist that she command her unit, defending the Kaiu Wall.","bushido_tenets":{"paramount":"Courage","less_significant":"Sincerity"}},"derived":{"endurance":10,"composure":8,"focus":4,"vigilance":2,"void_points":2},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[],"techniques":[{"name":"Striking as Earth","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"kata","rank":1,"description":"<p><span class=\"fontstyle0\"><em>After striking, the bushi roots themself to the ground, hunkering down to make sure their armor takes the brunt of a hit or raising a weapon in a warding position where it can deflect harm without being damaged.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee, Ranged, or Unarmed] (earth) check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth)(op)+: </span><span class=\"fontstyle3\">Treat your physical resistance as 1 higher per </span><span class=\"fontstyle4\">(op) </span><span class=\"fontstyle3\">spent this way until the beginning of your next turn.</span></p>","source":{"book":"core_rulebook","page":178},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.aKTfAZXbHo77kHOq"},{"name":"Lord Hida’s Grip (Crab)","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>The Kami Hida, patron of the Crab Clan, was a legendary slayer of monsters. He beheaded the massive demon that once menaced the rose-marble palace, and ripped out one skull of the two-headed Kabuto no Oni and crushed the other head with it. However, Hida was no mere brute: he was cunning, killing monsters by exploiting their weaknesses. Warriors of the Crab Clan train in similar techniques. They turn their foes' great weight against them by pinning or strategically damaging specific body parts.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As an Attack action, you may make a </span><span class=\"fontstyle2\">Fitness (void) check </span><span class=\"fontstyle3\">targeting one creature of silhouette 3 or larger at range 0–1. The TN of the check is equal to the silhouette of the target (to a minimum of 1).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, your target suffers the Immobilized condition. If you succeed, you count as granting assistance (see page 26) to all characters who perform Attack actions against your target. This effect persists until the beginning of your next turn.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(void)(op): </span><span class=\"fontstyle3\">Your target must resist with a </span><span class=\"fontstyle2\">Fitness check </span><span class=\"fontstyle3\">or suffer physical damage equal to its silhouette, ignoring its resistance, and the Prone condition. The TN of this check is equal to your school rank.</span></p>","source":{"book":"core_rulebook","page":176},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.ERExWdY04GNvu3p0","skill":"fitness"},{"name":"Way of the Crab","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p><span class=\"fontstyle0\">Ignore the Cumbersome quality of armor you wear.</span></p><p><span class=\"fontstyle0\">Once per round, before making a check to resist a critical strike, you may reduce the severity of that critical strike by the physical resistance of your armor plus your school rank (to a minimum of 0).</span></p>","source":{"book":"core_rulebook","page":57},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.7LHxYqmpqMUETLEq"}],"peculiarities":[{"name":"Light Sleeper","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"water","types":"Physical","description":"<p><span class=\"fontstyle0\"><em>“You see these scars?” she asked. He nodded respectfully at the Hiruma. It looked like someone had run a rake down her face—then repeated the action several times.</em></span></p><p><span class=\"fontstyle0\"><em>“This is what you get when you dare slumber here. Everyone else died that night.” She closed her eyes for a moment, then opened them abruptly, startling him. “You rest your guard, you die.” She looked closely at him. “You learn to stay awake, even when you sleep. Or you join the rest of my old patrol.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Light Sleeper distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You rouse from sleep very easily, a trick considered essential in hostile territory. You are trained to awaken before danger arrives, sleep with your weapons ready, and pretend to be in a deep sleep to lure enemies closer. You can go from a deep sleep to fully alert and fighting in the blink of an eye.</span></p></li><li><p><span class=\"fontstyle0\">- When performing a check that calls on rapidly recovering from sleep (such as a Survival (water) check to detect a threatening sound while dozing or a Fitness (water) check to react even when someone else is standing watch), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"shadowlands","page":96},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.ZtoejR7hmjZ0aE8k"},{"name":"Encompassing Duty","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"earth","types":"Mental","description":"<p><em>“I will lay down my life for my family. Nothing will stand in the way of that.”</em></p><p><em>– Aina, Ashigaru of the Lion</em></p><p></p><p>The following apply to a character with the Encompassing Duty adversity:</p><ul><li><p>- You have a duty to something: your family, a friend, a cause, or some other person or ideal. This duty should manifest into at least one discernible goal, one you can work out with the GM. A goal may be to provide for your family, rescue a friend, or achieve a similar aim. You have a difficult time relaxing or focusing on tasks that do not somehow advance your goal, and this may manifest in several ways, including frustration, anger, worry, or nervousness. </p></li><li><p>- Whenever you make a check related to overcoming something that could hinder you in achieving your duty (such as a Meditation (earth) check to keep a cool head in an ambush or a Courtesy (earth) check to reason with a stubborn shopkeeper), you must choose and reroll two dice containing (su) or (ex) . After resolving the check, if you failed, you gain 1 Void point.</p></li></ul>","source":{"book":"path_of_waves","page":72},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.TP83fjX8gnxELunG"},{"name":"Travel","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"water","types":"Mental, Physical","description":"<p><span class=\"fontstyle0\"><em>The old man sat heavily on the stool outside the constabulary office. He removed his straw hat, wiped his brow with his sleeve, and returned the hat to his head. His eyes, shaded by the wide brim, looked out at Yūka. The young girl smiled.</em></span></p><p><span class=\"fontstyle0\"><em>“Young lady, I have been from one side of Rokugan to the other—from Khanbulak to the Islands of Silk and Spice—and I have seen amazing sights. I will tell you this: in all my travels, I have become convinced of three things.” He counted them off on gnarled fingers. “All crows are black, it always rains when you don’t want it to, and Rokugan’s greatest treasure—a prize without equal—is its people.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Travel passion:</span></p><ul><li><p><span class=\"fontstyle3\">- You are not unsettled by foreign customs, and you can comfortably fit in even in strange environments.</span></p></li><li><p><span class=\"fontstyle3\">- After performing a check to travel to a new location or interact with a novel thing (such as a Survival (water) check to try to identify a new plant, animal, or phenomenon, or a Seafaring (water) check to travel by boat), you remove 3 strife.</span></p></li></ul>","source":{"book":"core_rulebook","page":115},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.7keAIKn0N8wjEsGa"},{"name":"Battle Trauma","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"fire","types":"Mental, Physical","description":"<p><em>The thousand cuts I have borne<br>And the thousand I have delivered<br>Paint my dreams in red<br>Broad brushstrokes to draw pictures<br>I cannot put to paper.<br>Do my ears ring from old age<br>Or is that steel’s song and the warrior’s cry<br>Gone so long ago<br>But never gone?</em></p><p><strong>Effects:</strong> The following apply to a character with the Battle Trauma anxiety:</p><ul><li><p>-  At the start of a duel, skirmish, or mass battle, your hands shake, your body tenses up, or your mind might even lock down. You can act normally, but your unsettled state is obvious to everyone around you, and others may try to exploit it.</p></li><li><p>-  After performing a check related to battle (such as a Martial Arts [Melee] (fire) check to strike down a foe or a Tactics (fire) check to generate initiative), you receive 3 strife. (Your GM can choose not to inflict this strife after the you have taken a few turns and thematically overcome your trauma.) If this is the first time this has occurred this scene, gain 1 Void point.</p></li></ul>","source":{"book":"core_rulebook","page":131},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.jlSq86lbglLrHXp8"},{"name":"Paragon of Courage","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"fire","types":"Mental, Virtue","description":"<p><span class=\"fontstyle0\"><em>“The heroes of myth—even the ones who were not of divine blood—did not live as humans do. It is impossible to embody an ideal without surpassing some part of your own humanity.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Paragon of Courage distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You believe utterly in Courage, and others instinctively discern that your actions are genuine when you act in accordance with it.</span></p></li><li><p><span class=\"fontstyle3\">- When performing a check for which you need to convince others of, or leverage your faith in, Courage (such as a Performance check to recount a tale that impresses its importance upon others or a Martial Arts [Melee] check to take up arms for this cause), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"core_rulebook","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.trppadBbshGjbSP2"}],"titles":[],"bonds":[],"signature_scrolls":[],"gear":[{"name":"Club","quantity":1,"description":"<p><span class=\"fontstyle0\">The humble club is perhaps the oldest weapon in Rokugan—at least among humans. Often little more than a length of stout wood or shaped stone, a club can be fashioned with available materials by nearly anyone. While a club can certainly be used to kill, doing so takes some work on the part of the wielder</span>.</p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.ElFJfEcGvWe6A5yU","damage":5,"deadliness":2,"range":"0-1","grip_2":"Damage +1","skill":"melee","category":"Blunt Weapons","rarity":"1","zeni":"1 bu","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Katana","quantity":1,"description":"<p><span class=\"fontstyle0\">As much a work of art as it is a weapon, the katana is perhaps the most revered weapon in Rokugan. It has an elegant, slightly curved blade between three and four feet long, made of steel that is specially folded during its creation. This unique forging style ensures that the inner part of the blade remains springy and soft while the outside is as hard as tempered steel. Each sword likely has a history and legacy, and it is a constant reminder of the weight that destiny has placed upon its bearer’s shoulders as a samurai of Rokugan</span>.</p>","source":{"book":"core_rulebook","page":232},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.BhKwwnN5UHI5rZpp","damage":4,"deadliness":5,"range":"1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"20 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Knife","quantity":1,"description":"<p><span class=\"fontstyle0\">Knives come in a dizzying array of types and styles, from the familiar crudely constructed knife in a peasant’s kitchen to the deadly combat knives samurai take into battle. Those particularly designed for combat—like the aiguchi—are often equipped with small hand guards to make them more useful in the field.</span></p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.n8xA05Fb9WpXg3oo","damage":2,"deadliness":4,"range":"0","grip_2":"Deadliness +2","skill":"melee","category":"Hand Weapons","rarity":"1","zeni":"1 koku","properties":[{"id":"L5RCorePro000001","name":"Razor-Edged"},{"id":"L5RCorePro000005","name":"Concealable"},{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Tetsubō","quantity":1,"description":"<p><span class=\"fontstyle0\">Long and narrow, a tetsubō can be as tall as a human and normally is constructed of iron or hardwood. Above its grip, a tetsubō is covered in steel, iron, or even jade spikes or studs that add to the weapon’s lethality and crush armor or plated carapace with ease.</span></p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.CW6h0NSzTEhimQXw","damage":7,"deadliness":3,"range":"1-2","grip_1":"N/A","skill":"melee","category":"Blunt Weapons","rarity":"5","zeni":"20 koku","properties":[{"id":"L5RCorePro000006","name":"Cumbersome"},{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Wakizashi","quantity":1,"description":"<p><span class=\"fontstyle0\">Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</span></p>","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Kamayari","quantity":1,"description":"<p><span class=\"fontstyle0\">A </span><span class=\"fontstyle2\">kamayari </span><span class=\"fontstyle0\">is a spear with a hooked protrusion on one or both sides of the blade, similar to a ji. While the hook’s most obvious applications are blocking attacks and dragging foes off horseback, it also has practical noncombat applications. A shinobi might swing from a sturdy tree limb using the hook or might use it to climb a high fence. If the spear shaft has holes in it, the shinobi can use the shaft to measure distances or can slot bars into the holes to use it as a ladder. Finally, the hook is useful for carrying items on long walks.</span></p>","source":{"book":"court_of_stones","page":110},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.PsmRwhHYBz0daKi5","damage":4,"deadliness":3,"range":"2","grip_1":"N/A","skill":"melee","category":"Specialist Weapons","rarity":"7","zeni":"8 koku","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000007","name":"Snaring"}]},{"name":"Lacquered Armor","quantity":1,"description":"<p><span class=\"fontstyle0\">Heavier than ashigaru armor, lacquered armor is worn by samurai who desire a good mix of protection and grandeur, and is just at home at war as at a martial ceremony. These suits are made of thick leather or steel plates stitched or riveted to a leather backing. They protect the torso, head, upper arms, and groin, and the legs above the knee. They can also include a helmet and mask, though these are not considered integral.</span></p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.sPKkavq6O0SoxiPj","armor":{"physical":4,"supernatural":0},"rarity":"6","zeni":"25 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000006","name":"Cumbersome"},{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Traveling Clothes","quantity":1,"description":"<p><span class=\"fontstyle0\">Traveling clothes ordinarily consist of roughspun garments designed to resist wear and tear. They can be anything from robes to a kimono or jacket and leggings and are often accentuated with a hat or cloak</span>.</p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.zcsgspz4VluSMeI0","armor":{"physical":2,"supernatural":0},"rarity":"2","zeni":"2 bu","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000012","name":"Mundane"},{"id":"L5RCorePro000016","name":"Subtle"}]},{"name":"Traveling pack","quantity":1,"description":"<p><span class=\"fontstyle0\">Blanket, bowl, chopsticks, four days of travel rations, flint and tinder, and any three other items of the player’s choice that are rarity 4 or lower.</span></p>","source":{"book":"core_rulebook","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.Rex7fGo6R1KuUhQJ","rarity":"1","zeni":"10 koku","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Kubi Bukuro","quantity":1,"description":"<p>These are simple net bags used to carry the severed head of an enemy, which is considered both a trophy and a good omen. Lion Clan samurai use them to carry their trophies without touching dead flesh, but the Kuni family uses them for collecting samples of Shadowlands creatures for study.</p>","source":{"book":"core_rulebook","page":242},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.6J25vJx1tVirgXf1","rarity":"2","zeni":"2 zeni","properties":[{"id":"L5RCorePro000011","name":"Wargear"}]}]},{"xp":21,"label":"Rank 2","rank":2,"school":"Hida Defender School","foundry_id":"qasH08OepZgjiTfv","rings":{"air":2,"earth":3,"fire":2,"water":1,"void":2},"skills":{"artisan":{"aesthetics":0,"composition":0,"design":0,"smithing":0},"martial":{"fitness":2,"melee":2,"ranged":2,"unarmed":1,"meditation":0,"tactics":2},"scholar":{"culture":0,"government":0,"medicine":0,"sentiment":0,"theology":0},"social":{"command":1,"courtesy":1,"games":0,"performance":0},"trade":{"commerce":0,"labor":0,"seafaring":0,"skulduggery":1,"survival":2}},"social":{"honor":45,"glory":44,"status":30,"ninjo":"Longs to travel Rokugan, or possibly even beyond.","giri":"Hiruma Nobuyasu is their lord. They insist that she command her unit, defending the Kaiu Wall.","bushido_tenets":{"paramount":"Courage","less_significant":"Sincerity"}},"derived":{"endurance":10,"composure":8,"focus":4,"vigilance":2,"void_points":2},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[{"label":"Martial Arts [Ranged] +1 (0 -> 1)","type":"skill","skill":"ranged","ring":"void","at_rank":1,"xp":2,"in_curriculum":true},{"label":"Martial Arts [Melee] +1 (1 -> 2)","type":"skill","skill":"melee","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Martial Arts [Unarmed] +1 (0 -> 1)","type":"skill","skill":"unarmed","ring":"void","at_rank":1,"xp":2,"in_curriculum":true},{"label":"Martial Arts [Ranged] +1 (1 -> 2)","type":"skill","skill":"ranged","ring":"void","at_rank":1,"xp":4,"in_curriculum":true}],"techniques":[{"name":"Striking as Earth","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"kata","rank":1,"description":"<p><span class=\"fontstyle0\"><em>After striking, the bushi roots themself to the ground, hunkering down to make sure their armor takes the brunt of a hit or raising a weapon in a warding position where it can deflect harm without being damaged.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee, Ranged, or Unarmed] (earth) check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth)(op)+: </span><span class=\"fontstyle3\">Treat your physical resistance as 1 higher per </span><span class=\"fontstyle4\">(op) </span><span class=\"fontstyle3\">spent this way until the beginning of your next turn.</span></p>","source":{"book":"core_rulebook","page":178},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.aKTfAZXbHo77kHOq"},{"name":"Lord Hida’s Grip (Crab)","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>The Kami Hida, patron of the Crab Clan, was a legendary slayer of monsters. He beheaded the massive demon that once menaced the rose-marble palace, and ripped out one skull of the two-headed Kabuto no Oni and crushed the other head with it. However, Hida was no mere brute: he was cunning, killing monsters by exploiting their weaknesses. Warriors of the Crab Clan train in similar techniques. They turn their foes' great weight against them by pinning or strategically damaging specific body parts.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As an Attack action, you may make a </span><span class=\"fontstyle2\">Fitness (void) check </span><span class=\"fontstyle3\">targeting one creature of silhouette 3 or larger at range 0–1. The TN of the check is equal to the silhouette of the target (to a minimum of 1).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, your target suffers the Immobilized condition. If you succeed, you count as granting assistance (see page 26) to all characters who perform Attack actions against your target. This effect persists until the beginning of your next turn.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(void)(op): </span><span class=\"fontstyle3\">Your target must resist with a </span><span class=\"fontstyle2\">Fitness check </span><span class=\"fontstyle3\">or suffer physical damage equal to its silhouette, ignoring its resistance, and the Prone condition. The TN of this check is equal to your school rank.</span></p>","source":{"book":"core_rulebook","page":176},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.ERExWdY04GNvu3p0","skill":"fitness"},{"name":"Way of the Crab","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p><span class=\"fontstyle0\">Ignore the Cumbersome quality of armor you wear.</span></p><p><span class=\"fontstyle0\">Once per round, before making a check to resist a critical strike, you may reduce the severity of that critical strike by the physical resistance of your armor plus your school rank (to a minimum of 0).</span></p>","source":{"book":"core_rulebook","page":57},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.7LHxYqmpqMUETLEq"},{"name":"Appreciate the Scenery","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<p><span class=\"fontstyle0\"><em>In many lands, including Rokugan, the beauty of the natural world inspires art, poetry, and other works of note, even (or perhaps especially) when it is stark and dangerous. When on a long and perilous journey into foreign lands where deadly intrigues surely await, finding beauty in the rougher parts of the world can be a much-needed source of solace.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Support action check targeting another character, if you and the character you are targeting are in Dangerous, Entangling, Hallowed, Imbalanced, or Obscuring terrain, you may spend (op) as follows:</span></p><p><span class=\"fontstyle2\">(earth) or</span><span class=\"fontstyle4\"> (water)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">You and your target each remove strife equal to your ranks in Composition.</span></p><p><span class=\"fontstyle2\">(air) or (fire)</span><span class=\"fontstyle4\">(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">You and your target gain the Emboldened condition (see page 133).</span></p><p><span class=\"fontstyle2\">(void)(op): </span><span class=\"fontstyle3\">Your and your target gain the Centered condition (see page 133).</span></p>","source":{"book":"children_of_the_five_winds","page":116},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.gbUpw4ife9RdWbK9"},{"name":"Honest Assessment","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<p><span class=\"fontstyle0\"><em>Honesty is a virtue of Bushidō, but direct honesty is often seen as rudeness among the samurai—instead, one is expected to find a polite way to imply one’s meaning to spare the feelings of the other involved. As a result, directness can be something of a rare and valuable commodity.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may make a </span><span class=\"fontstyle2\">TN 2 Courtesy (earth) check </span><span class=\"fontstyle3\">to appraise the weaknesses of a character.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, choose one of the target’s known disadvantages. The target does not apply that disadvantage to their checks until the end of the scene.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(earth)(op)+: </span><span class=\"fontstyle3\">Choose one additional disadvantage per (op) spent this way.</span></p><p><span class=\"fontstyle5\">(earth)(op)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">Reduce the TN of the target’s next skill check using the ring the disadvantage is attached to by 2.</span></p>","source":{"book":"core_rulebook","page":216},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.t427qRaOh42dfbVM","skill":"courtesy"},{"name":"Rushing Avalanche Style","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>When adopting this style, the bushi strikes with reckless abandon using a heavy armament. Thanks to the sheer weight of their weapon and the ferocity of their strikes, even a glancing blow can cause serious harm, and a telling blow usually ends the battle.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee] check using a blunt weapon, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(op): </span><span class=\"fontstyle3\">If you fail with a shortfall of two or less, your target suffers physical damage equal to your ranks in Fitness.</span></p><p><span class=\"fontstyle2\">(op): </span><span class=\"fontstyle3\">If you succeed and your target is Prone, increase the damage you deal by your ranks in Fitness.</span></p>","source":{"book":"core_rulebook","page":180},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.EZG0aAg9oxEUou5u"}],"peculiarities":[{"name":"Light Sleeper","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"water","types":"Physical","description":"<p><span class=\"fontstyle0\"><em>“You see these scars?” she asked. He nodded respectfully at the Hiruma. It looked like someone had run a rake down her face—then repeated the action several times.</em></span></p><p><span class=\"fontstyle0\"><em>“This is what you get when you dare slumber here. Everyone else died that night.” She closed her eyes for a moment, then opened them abruptly, startling him. “You rest your guard, you die.” She looked closely at him. “You learn to stay awake, even when you sleep. Or you join the rest of my old patrol.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Light Sleeper distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You rouse from sleep very easily, a trick considered essential in hostile territory. You are trained to awaken before danger arrives, sleep with your weapons ready, and pretend to be in a deep sleep to lure enemies closer. You can go from a deep sleep to fully alert and fighting in the blink of an eye.</span></p></li><li><p><span class=\"fontstyle0\">- When performing a check that calls on rapidly recovering from sleep (such as a Survival (water) check to detect a threatening sound while dozing or a Fitness (water) check to react even when someone else is standing watch), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"shadowlands","page":96},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.ZtoejR7hmjZ0aE8k"},{"name":"Encompassing Duty","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"earth","types":"Mental","description":"<p><em>“I will lay down my life for my family. Nothing will stand in the way of that.”</em></p><p><em>– Aina, Ashigaru of the Lion</em></p><p></p><p>The following apply to a character with the Encompassing Duty adversity:</p><ul><li><p>- You have a duty to something: your family, a friend, a cause, or some other person or ideal. This duty should manifest into at least one discernible goal, one you can work out with the GM. A goal may be to provide for your family, rescue a friend, or achieve a similar aim. You have a difficult time relaxing or focusing on tasks that do not somehow advance your goal, and this may manifest in several ways, including frustration, anger, worry, or nervousness. </p></li><li><p>- Whenever you make a check related to overcoming something that could hinder you in achieving your duty (such as a Meditation (earth) check to keep a cool head in an ambush or a Courtesy (earth) check to reason with a stubborn shopkeeper), you must choose and reroll two dice containing (su) or (ex) . After resolving the check, if you failed, you gain 1 Void point.</p></li></ul>","source":{"book":"path_of_waves","page":72},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.TP83fjX8gnxELunG"},{"name":"Travel","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"water","types":"Mental, Physical","description":"<p><span class=\"fontstyle0\"><em>The old man sat heavily on the stool outside the constabulary office. He removed his straw hat, wiped his brow with his sleeve, and returned the hat to his head. His eyes, shaded by the wide brim, looked out at Yūka. The young girl smiled.</em></span></p><p><span class=\"fontstyle0\"><em>“Young lady, I have been from one side of Rokugan to the other—from Khanbulak to the Islands of Silk and Spice—and I have seen amazing sights. I will tell you this: in all my travels, I have become convinced of three things.” He counted them off on gnarled fingers. “All crows are black, it always rains when you don’t want it to, and Rokugan’s greatest treasure—a prize without equal—is its people.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Travel passion:</span></p><ul><li><p><span class=\"fontstyle3\">- You are not unsettled by foreign customs, and you can comfortably fit in even in strange environments.</span></p></li><li><p><span class=\"fontstyle3\">- After performing a check to travel to a new location or interact with a novel thing (such as a Survival (water) check to try to identify a new plant, animal, or phenomenon, or a Seafaring (water) check to travel by boat), you remove 3 strife.</span></p></li></ul>","source":{"book":"core_rulebook","page":115},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.7keAIKn0N8wjEsGa"},{"name":"Battle Trauma","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"fire","types":"Mental, Physical","description":"<p><em>The thousand cuts I have borne<br>And the thousand I have delivered<br>Paint my dreams in red<br>Broad brushstrokes to draw pictures<br>I cannot put to paper.<br>Do my ears ring from old age<br>Or is that steel’s song and the warrior’s cry<br>Gone so long ago<br>But never gone?</em></p><p><strong>Effects:</strong> The following apply to a character with the Battle Trauma anxiety:</p><ul><li><p>-  At the start of a duel, skirmish, or mass battle, your hands shake, your body tenses up, or your mind might even lock down. You can act normally, but your unsettled state is obvious to everyone around you, and others may try to exploit it.</p></li><li><p>-  After performing a check related to battle (such as a Martial Arts [Melee] (fire) check to strike down a foe or a Tactics (fire) check to generate initiative), you receive 3 strife. (Your GM can choose not to inflict this strife after the you have taken a few turns and thematically overcome your trauma.) If this is the first time this has occurred this scene, gain 1 Void point.</p></li></ul>","source":{"book":"core_rulebook","page":131},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.jlSq86lbglLrHXp8"},{"name":"Paragon of Courage","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"fire","types":"Mental, Virtue","description":"<p><span class=\"fontstyle0\"><em>“The heroes of myth—even the ones who were not of divine blood—did not live as humans do. It is impossible to embody an ideal without surpassing some part of your own humanity.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Paragon of Courage distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You believe utterly in Courage, and others instinctively discern that your actions are genuine when you act in accordance with it.</span></p></li><li><p><span class=\"fontstyle3\">- When performing a check for which you need to convince others of, or leverage your faith in, Courage (such as a Performance check to recount a tale that impresses its importance upon others or a Martial Arts [Melee] check to take up arms for this cause), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"core_rulebook","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.trppadBbshGjbSP2"}],"titles":[],"bonds":[],"signature_scrolls":[],"gear":[{"name":"Club","quantity":1,"description":"<p><span class=\"fontstyle0\">The humble club is perhaps the oldest weapon in Rokugan—at least among humans. Often little more than a length of stout wood or shaped stone, a club can be fashioned with available materials by nearly anyone. While a club can certainly be used to kill, doing so takes some work on the part of the wielder</span>.</p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.ElFJfEcGvWe6A5yU","damage":5,"deadliness":2,"range":"0-1","grip_2":"Damage +1","skill":"melee","category":"Blunt Weapons","rarity":"1","zeni":"1 bu","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Katana","quantity":1,"description":"<p><span class=\"fontstyle0\">As much a work of art as it is a weapon, the katana is perhaps the most revered weapon in Rokugan. It has an elegant, slightly curved blade between three and four feet long, made of steel that is specially folded during its creation. This unique forging style ensures that the inner part of the blade remains springy and soft while the outside is as hard as tempered steel. Each sword likely has a history and legacy, and it is a constant reminder of the weight that destiny has placed upon its bearer’s shoulders as a samurai of Rokugan</span>.</p>","source":{"book":"core_rulebook","page":232},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.BhKwwnN5UHI5rZpp","damage":4,"deadliness":5,"range":"1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"20 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Knife","quantity":1,"description":"<p><span class=\"fontstyle0\">Knives come in a dizzying array of types and styles, from the familiar crudely constructed knife in a peasant’s kitchen to the deadly combat knives samurai take into battle. Those particularly designed for combat—like the aiguchi—are often equipped with small hand guards to make them more useful in the field.</span></p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.n8xA05Fb9WpXg3oo","damage":2,"deadliness":4,"range":"0","grip_2":"Deadliness +2","skill":"melee","category":"Hand Weapons","rarity":"1","zeni":"1 koku","properties":[{"id":"L5RCorePro000001","name":"Razor-Edged"},{"id":"L5RCorePro000005","name":"Concealable"},{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Tetsubō","quantity":1,"description":"<p><span class=\"fontstyle0\">Long and narrow, a tetsubō can be as tall as a human and normally is constructed of iron or hardwood. Above its grip, a tetsubō is covered in steel, iron, or even jade spikes or studs that add to the weapon’s lethality and crush armor or plated carapace with ease.</span></p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.CW6h0NSzTEhimQXw","damage":7,"deadliness":3,"range":"1-2","grip_1":"N/A","skill":"melee","category":"Blunt Weapons","rarity":"5","zeni":"20 koku","properties":[{"id":"L5RCorePro000006","name":"Cumbersome"},{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Wakizashi","quantity":1,"description":"<p><span class=\"fontstyle0\">Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</span></p>","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Kamayari","quantity":1,"description":"<p><span class=\"fontstyle0\">A </span><span class=\"fontstyle2\">kamayari </span><span class=\"fontstyle0\">is a spear with a hooked protrusion on one or both sides of the blade, similar to a ji. While the hook’s most obvious applications are blocking attacks and dragging foes off horseback, it also has practical noncombat applications. A shinobi might swing from a sturdy tree limb using the hook or might use it to climb a high fence. If the spear shaft has holes in it, the shinobi can use the shaft to measure distances or can slot bars into the holes to use it as a ladder. Finally, the hook is useful for carrying items on long walks.</span></p>","source":{"book":"court_of_stones","page":110},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.PsmRwhHYBz0daKi5","damage":4,"deadliness":3,"range":"2","grip_1":"N/A","skill":"melee","category":"Specialist Weapons","rarity":"7","zeni":"8 koku","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000007","name":"Snaring"}]},{"name":"Lacquered Armor","quantity":1,"description":"<p><span class=\"fontstyle0\">Heavier than ashigaru armor, lacquered armor is worn by samurai who desire a good mix of protection and grandeur, and is just at home at war as at a martial ceremony. These suits are made of thick leather or steel plates stitched or riveted to a leather backing. They protect the torso, head, upper arms, and groin, and the legs above the knee. They can also include a helmet and mask, though these are not considered integral.</span></p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.sPKkavq6O0SoxiPj","armor":{"physical":4,"supernatural":0},"rarity":"6","zeni":"25 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000006","name":"Cumbersome"},{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Traveling Clothes","quantity":1,"description":"<p><span class=\"fontstyle0\">Traveling clothes ordinarily consist of roughspun garments designed to resist wear and tear. They can be anything from robes to a kimono or jacket and leggings and are often accentuated with a hat or cloak</span>.</p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.zcsgspz4VluSMeI0","armor":{"physical":2,"supernatural":0},"rarity":"2","zeni":"2 bu","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000012","name":"Mundane"},{"id":"L5RCorePro000016","name":"Subtle"}]},{"name":"Traveling pack","quantity":1,"description":"<p><span class=\"fontstyle0\">Blanket, bowl, chopsticks, four days of travel rations, flint and tinder, and any three other items of the player’s choice that are rarity 4 or lower.</span></p>","source":{"book":"core_rulebook","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.Rex7fGo6R1KuUhQJ","rarity":"1","zeni":"10 koku","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Kubi Bukuro","quantity":1,"description":"<p>These are simple net bags used to carry the severed head of an enemy, which is considered both a trophy and a good omen. Lion Clan samurai use them to carry their trophies without touching dead flesh, but the Kuni family uses them for collecting samples of Shadowlands creatures for study.</p>","source":{"book":"core_rulebook","page":242},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.6J25vJx1tVirgXf1","rarity":"2","zeni":"2 zeni","properties":[{"id":"L5RCorePro000011","name":"Wargear"}]}]},{"xp":50,"label":"Rank 3","rank":3,"school":"Hida Defender School","foundry_id":"kyq8x7TCCC3lKy6I","rings":{"air":2,"earth":3,"fire":2,"water":1,"void":3},"skills":{"artisan":{"aesthetics":0,"composition":1,"design":0,"smithing":0},"martial":{"fitness":2,"melee":2,"ranged":2,"unarmed":1,"meditation":0,"tactics":2},"scholar":{"culture":0,"government":0,"medicine":0,"sentiment":0,"theology":0},"social":{"command":3,"courtesy":1,"games":0,"performance":0},"trade":{"commerce":0,"labor":1,"seafaring":0,"skulduggery":1,"survival":2}},"social":{"honor":45,"glory":44,"status":30,"ninjo":"Longs to travel Rokugan, or possibly even beyond.","giri":"Hiruma Nobuyasu is their lord. They insist that she command her unit, defending the Kaiu Wall.","bushido_tenets":{"paramount":"Courage","less_significant":"Sincerity"}},"derived":{"endurance":10,"composure":8,"focus":4,"vigilance":2,"void_points":3},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[{"label":"Martial Arts [Ranged] +1 (0 -> 1)","type":"skill","skill":"ranged","ring":"void","at_rank":1,"xp":2,"in_curriculum":true},{"label":"Martial Arts [Melee] +1 (1 -> 2)","type":"skill","skill":"melee","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Martial Arts [Unarmed] +1 (0 -> 1)","type":"skill","skill":"unarmed","ring":"void","at_rank":1,"xp":2,"in_curriculum":true},{"label":"Martial Arts [Ranged] +1 (1 -> 2)","type":"skill","skill":"ranged","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Command +1 (1 -> 2)","type":"skill","skill":"command","ring":"void","at_rank":2,"xp":4,"in_curriculum":true},{"label":"Void +1 (2 -> 3)","type":"ring","ring":"void","at_rank":2,"xp":9,"in_curriculum":false},{"label":"Labor +1 (0 -> 1)","type":"skill","skill":"labor","ring":"void","at_rank":2,"xp":2,"in_curriculum":true},{"label":"Command +1 (2 -> 3)","type":"skill","skill":"command","ring":"void","at_rank":2,"xp":6,"in_curriculum":true},{"label":"Composition +1 (0 -> 1)","type":"skill","skill":"composition","ring":"void","at_rank":2,"xp":2,"in_curriculum":false}],"techniques":[{"name":"Striking as Earth","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"kata","rank":1,"description":"<p><span class=\"fontstyle0\"><em>After striking, the bushi roots themself to the ground, hunkering down to make sure their armor takes the brunt of a hit or raising a weapon in a warding position where it can deflect harm without being damaged.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee, Ranged, or Unarmed] (earth) check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth)(op)+: </span><span class=\"fontstyle3\">Treat your physical resistance as 1 higher per </span><span class=\"fontstyle4\">(op) </span><span class=\"fontstyle3\">spent this way until the beginning of your next turn.</span></p>","source":{"book":"core_rulebook","page":178},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.aKTfAZXbHo77kHOq"},{"name":"Lord Hida’s Grip (Crab)","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>The Kami Hida, patron of the Crab Clan, was a legendary slayer of monsters. He beheaded the massive demon that once menaced the rose-marble palace, and ripped out one skull of the two-headed Kabuto no Oni and crushed the other head with it. However, Hida was no mere brute: he was cunning, killing monsters by exploiting their weaknesses. Warriors of the Crab Clan train in similar techniques. They turn their foes' great weight against them by pinning or strategically damaging specific body parts.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As an Attack action, you may make a </span><span class=\"fontstyle2\">Fitness (void) check </span><span class=\"fontstyle3\">targeting one creature of silhouette 3 or larger at range 0–1. The TN of the check is equal to the silhouette of the target (to a minimum of 1).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, your target suffers the Immobilized condition. If you succeed, you count as granting assistance (see page 26) to all characters who perform Attack actions against your target. This effect persists until the beginning of your next turn.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(void)(op): </span><span class=\"fontstyle3\">Your target must resist with a </span><span class=\"fontstyle2\">Fitness check </span><span class=\"fontstyle3\">or suffer physical damage equal to its silhouette, ignoring its resistance, and the Prone condition. The TN of this check is equal to your school rank.</span></p>","source":{"book":"core_rulebook","page":176},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.ERExWdY04GNvu3p0","skill":"fitness"},{"name":"Way of the Crab","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p><span class=\"fontstyle0\">Ignore the Cumbersome quality of armor you wear.</span></p><p><span class=\"fontstyle0\">Once per round, before making a check to resist a critical strike, you may reduce the severity of that critical strike by the physical resistance of your armor plus your school rank (to a minimum of 0).</span></p>","source":{"book":"core_rulebook","page":57},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.7LHxYqmpqMUETLEq"},{"name":"Appreciate the Scenery","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<p><span class=\"fontstyle0\"><em>In many lands, including Rokugan, the beauty of the natural world inspires art, poetry, and other works of note, even (or perhaps especially) when it is stark and dangerous. When on a long and perilous journey into foreign lands where deadly intrigues surely await, finding beauty in the rougher parts of the world can be a much-needed source of solace.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Support action check targeting another character, if you and the character you are targeting are in Dangerous, Entangling, Hallowed, Imbalanced, or Obscuring terrain, you may spend (op) as follows:</span></p><p><span class=\"fontstyle2\">(earth) or</span><span class=\"fontstyle4\"> (water)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">You and your target each remove strife equal to your ranks in Composition.</span></p><p><span class=\"fontstyle2\">(air) or (fire)</span><span class=\"fontstyle4\">(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">You and your target gain the Emboldened condition (see page 133).</span></p><p><span class=\"fontstyle2\">(void)(op): </span><span class=\"fontstyle3\">Your and your target gain the Centered condition (see page 133).</span></p>","source":{"book":"children_of_the_five_winds","page":116},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.gbUpw4ife9RdWbK9"},{"name":"Honest Assessment","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<p><span class=\"fontstyle0\"><em>Honesty is a virtue of Bushidō, but direct honesty is often seen as rudeness among the samurai—instead, one is expected to find a polite way to imply one’s meaning to spare the feelings of the other involved. As a result, directness can be something of a rare and valuable commodity.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may make a </span><span class=\"fontstyle2\">TN 2 Courtesy (earth) check </span><span class=\"fontstyle3\">to appraise the weaknesses of a character.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, choose one of the target’s known disadvantages. The target does not apply that disadvantage to their checks until the end of the scene.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(earth)(op)+: </span><span class=\"fontstyle3\">Choose one additional disadvantage per (op) spent this way.</span></p><p><span class=\"fontstyle5\">(earth)(op)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">Reduce the TN of the target’s next skill check using the ring the disadvantage is attached to by 2.</span></p>","source":{"book":"core_rulebook","page":216},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.t427qRaOh42dfbVM","skill":"courtesy"},{"name":"Rushing Avalanche Style","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>When adopting this style, the bushi strikes with reckless abandon using a heavy armament. Thanks to the sheer weight of their weapon and the ferocity of their strikes, even a glancing blow can cause serious harm, and a telling blow usually ends the battle.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee] check using a blunt weapon, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(op): </span><span class=\"fontstyle3\">If you fail with a shortfall of two or less, your target suffers physical damage equal to your ranks in Fitness.</span></p><p><span class=\"fontstyle2\">(op): </span><span class=\"fontstyle3\">If you succeed and your target is Prone, increase the damage you deal by your ranks in Fitness.</span></p>","source":{"book":"core_rulebook","page":180},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.EZG0aAg9oxEUou5u"},{"name":"Staggering Shot","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>Putting an arrow at a foe’s feet can cause them to stumble or trip, and an experienced archer knows how to take full advantage of this, planting bolts to break an</em></span><em> </em><span class=\"fontstyle0\"><em>enemy’s stride or pinning their clothes to slow them down, making any approach extremely treacherous.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you perform a Martial Arts [Ranged] check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth) or (fire)(op)(op): </span><span class=\"fontstyle3\">Your target treats all terrain as having the Dangerous quality. This effect persists until the end of your next turn.</span></p><p><span class=\"fontstyle2\">(air) or (water)(op)(op): </span><span class=\"fontstyle3\">Your target treats all terrain as having the Entangling quality. This effect persists until the end of your next turn.</span></p>","source":{"book":"path_of_waves","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.6N5n9fweaz1CbLCu"},{"name":"Touchstone of Courage","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"shuji","rank":3,"description":"<p><span class=\"fontstyle0\"><em>Armies are rarely routed in the field; instead, most collapse when morale becomes impossible to maintain. As panic rises in the ranks, soldiers look to leaders to set an example. The character does just this, speaking to the importance of duty to bring their troops back from the edge of chaos.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may make a </span><span class=\"fontstyle2\">TN 4 Command (earth) check </span><span class=\"fontstyle3\">targeting any number of characters (or your cohort during a mass battle).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed during an intrigue, duel, or skirmish conflict, each target increases their composure by your Earth Ring. This effect persists until the end of the scene. If you succeed during a mass battle, increase your army’s discipline by your Earth Ring plus your bonus successes. This effect persists until the end of the scene.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(earth)(op)(op): </span><span class=\"fontstyle3\">During an intrigue, duel, or skirmish, each target removes strife equal to your Earth Ring.</span></p><p><span class=\"fontstyle2\">(earth)(op)(op): </span><span class=\"fontstyle3\">During a mass battle, your army removes panic equal to your Earth Ring.</span></p>","source":{"book":"core_rulebook","page":217},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.fFxQOBXLb9ol9owk","skill":"command"}],"peculiarities":[{"name":"Light Sleeper","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"water","types":"Physical","description":"<p><span class=\"fontstyle0\"><em>“You see these scars?” she asked. He nodded respectfully at the Hiruma. It looked like someone had run a rake down her face—then repeated the action several times.</em></span></p><p><span class=\"fontstyle0\"><em>“This is what you get when you dare slumber here. Everyone else died that night.” She closed her eyes for a moment, then opened them abruptly, startling him. “You rest your guard, you die.” She looked closely at him. “You learn to stay awake, even when you sleep. Or you join the rest of my old patrol.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Light Sleeper distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You rouse from sleep very easily, a trick considered essential in hostile territory. You are trained to awaken before danger arrives, sleep with your weapons ready, and pretend to be in a deep sleep to lure enemies closer. You can go from a deep sleep to fully alert and fighting in the blink of an eye.</span></p></li><li><p><span class=\"fontstyle0\">- When performing a check that calls on rapidly recovering from sleep (such as a Survival (water) check to detect a threatening sound while dozing or a Fitness (water) check to react even when someone else is standing watch), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"shadowlands","page":96},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.ZtoejR7hmjZ0aE8k"},{"name":"Encompassing Duty","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"earth","types":"Mental","description":"<p><em>“I will lay down my life for my family. Nothing will stand in the way of that.”</em></p><p><em>– Aina, Ashigaru of the Lion</em></p><p></p><p>The following apply to a character with the Encompassing Duty adversity:</p><ul><li><p>- You have a duty to something: your family, a friend, a cause, or some other person or ideal. This duty should manifest into at least one discernible goal, one you can work out with the GM. A goal may be to provide for your family, rescue a friend, or achieve a similar aim. You have a difficult time relaxing or focusing on tasks that do not somehow advance your goal, and this may manifest in several ways, including frustration, anger, worry, or nervousness. </p></li><li><p>- Whenever you make a check related to overcoming something that could hinder you in achieving your duty (such as a Meditation (earth) check to keep a cool head in an ambush or a Courtesy (earth) check to reason with a stubborn shopkeeper), you must choose and reroll two dice containing (su) or (ex) . After resolving the check, if you failed, you gain 1 Void point.</p></li></ul>","source":{"book":"path_of_waves","page":72},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.TP83fjX8gnxELunG"},{"name":"Travel","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"water","types":"Mental, Physical","description":"<p><span class=\"fontstyle0\"><em>The old man sat heavily on the stool outside the constabulary office. He removed his straw hat, wiped his brow with his sleeve, and returned the hat to his head. His eyes, shaded by the wide brim, looked out at Yūka. The young girl smiled.</em></span></p><p><span class=\"fontstyle0\"><em>“Young lady, I have been from one side of Rokugan to the other—from Khanbulak to the Islands of Silk and Spice—and I have seen amazing sights. I will tell you this: in all my travels, I have become convinced of three things.” He counted them off on gnarled fingers. “All crows are black, it always rains when you don’t want it to, and Rokugan’s greatest treasure—a prize without equal—is its people.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Travel passion:</span></p><ul><li><p><span class=\"fontstyle3\">- You are not unsettled by foreign customs, and you can comfortably fit in even in strange environments.</span></p></li><li><p><span class=\"fontstyle3\">- After performing a check to travel to a new location or interact with a novel thing (such as a Survival (water) check to try to identify a new plant, animal, or phenomenon, or a Seafaring (water) check to travel by boat), you remove 3 strife.</span></p></li></ul>","source":{"book":"core_rulebook","page":115},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.7keAIKn0N8wjEsGa"},{"name":"Battle Trauma","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"fire","types":"Mental, Physical","description":"<p><em>The thousand cuts I have borne<br>And the thousand I have delivered<br>Paint my dreams in red<br>Broad brushstrokes to draw pictures<br>I cannot put to paper.<br>Do my ears ring from old age<br>Or is that steel’s song and the warrior’s cry<br>Gone so long ago<br>But never gone?</em></p><p><strong>Effects:</strong> The following apply to a character with the Battle Trauma anxiety:</p><ul><li><p>-  At the start of a duel, skirmish, or mass battle, your hands shake, your body tenses up, or your mind might even lock down. You can act normally, but your unsettled state is obvious to everyone around you, and others may try to exploit it.</p></li><li><p>-  After performing a check related to battle (such as a Martial Arts [Melee] (fire) check to strike down a foe or a Tactics (fire) check to generate initiative), you receive 3 strife. (Your GM can choose not to inflict this strife after the you have taken a few turns and thematically overcome your trauma.) If this is the first time this has occurred this scene, gain 1 Void point.</p></li></ul>","source":{"book":"core_rulebook","page":131},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.jlSq86lbglLrHXp8"},{"name":"Paragon of Courage","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"fire","types":"Mental, Virtue","description":"<p><span class=\"fontstyle0\"><em>“The heroes of myth—even the ones who were not of divine blood—did not live as humans do. It is impossible to embody an ideal without surpassing some part of your own humanity.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Paragon of Courage distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You believe utterly in Courage, and others instinctively discern that your actions are genuine when you act in accordance with it.</span></p></li><li><p><span class=\"fontstyle3\">- When performing a check for which you need to convince others of, or leverage your faith in, Courage (such as a Performance check to recount a tale that impresses its importance upon others or a Martial Arts [Melee] check to take up arms for this cause), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"core_rulebook","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.trppadBbshGjbSP2"}],"titles":[],"bonds":[],"signature_scrolls":[],"gear":[{"name":"Club","quantity":1,"description":"<p><span class=\"fontstyle0\">The humble club is perhaps the oldest weapon in Rokugan—at least among humans. Often little more than a length of stout wood or shaped stone, a club can be fashioned with available materials by nearly anyone. While a club can certainly be used to kill, doing so takes some work on the part of the wielder</span>.</p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.ElFJfEcGvWe6A5yU","damage":5,"deadliness":2,"range":"0-1","grip_2":"Damage +1","skill":"melee","category":"Blunt Weapons","rarity":"1","zeni":"1 bu","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Katana","quantity":1,"description":"<p><span class=\"fontstyle0\">As much a work of art as it is a weapon, the katana is perhaps the most revered weapon in Rokugan. It has an elegant, slightly curved blade between three and four feet long, made of steel that is specially folded during its creation. This unique forging style ensures that the inner part of the blade remains springy and soft while the outside is as hard as tempered steel. Each sword likely has a history and legacy, and it is a constant reminder of the weight that destiny has placed upon its bearer’s shoulders as a samurai of Rokugan</span>.</p>","source":{"book":"core_rulebook","page":232},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.BhKwwnN5UHI5rZpp","damage":4,"deadliness":5,"range":"1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"20 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Knife","quantity":1,"description":"<p><span class=\"fontstyle0\">Knives come in a dizzying array of types and styles, from the familiar crudely constructed knife in a peasant’s kitchen to the deadly combat knives samurai take into battle. Those particularly designed for combat—like the aiguchi—are often equipped with small hand guards to make them more useful in the field.</span></p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.n8xA05Fb9WpXg3oo","damage":2,"deadliness":4,"range":"0","grip_2":"Deadliness +2","skill":"melee","category":"Hand Weapons","rarity":"1","zeni":"1 koku","properties":[{"id":"L5RCorePro000001","name":"Razor-Edged"},{"id":"L5RCorePro000005","name":"Concealable"},{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Tetsubō","quantity":1,"description":"<p><span class=\"fontstyle0\">Long and narrow, a tetsubō can be as tall as a human and normally is constructed of iron or hardwood. Above its grip, a tetsubō is covered in steel, iron, or even jade spikes or studs that add to the weapon’s lethality and crush armor or plated carapace with ease.</span></p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.CW6h0NSzTEhimQXw","damage":7,"deadliness":3,"range":"1-2","grip_1":"N/A","skill":"melee","category":"Blunt Weapons","rarity":"5","zeni":"20 koku","properties":[{"id":"L5RCorePro000006","name":"Cumbersome"},{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Wakizashi","quantity":1,"description":"<p><span class=\"fontstyle0\">Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</span></p>","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Kamayari","quantity":1,"description":"<p><span class=\"fontstyle0\">A </span><span class=\"fontstyle2\">kamayari </span><span class=\"fontstyle0\">is a spear with a hooked protrusion on one or both sides of the blade, similar to a ji. While the hook’s most obvious applications are blocking attacks and dragging foes off horseback, it also has practical noncombat applications. A shinobi might swing from a sturdy tree limb using the hook or might use it to climb a high fence. If the spear shaft has holes in it, the shinobi can use the shaft to measure distances or can slot bars into the holes to use it as a ladder. Finally, the hook is useful for carrying items on long walks.</span></p>","source":{"book":"court_of_stones","page":110},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.PsmRwhHYBz0daKi5","damage":4,"deadliness":3,"range":"2","grip_1":"N/A","skill":"melee","category":"Specialist Weapons","rarity":"7","zeni":"8 koku","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000007","name":"Snaring"}]},{"name":"Lacquered Armor","quantity":1,"description":"<p><span class=\"fontstyle0\">Heavier than ashigaru armor, lacquered armor is worn by samurai who desire a good mix of protection and grandeur, and is just at home at war as at a martial ceremony. These suits are made of thick leather or steel plates stitched or riveted to a leather backing. They protect the torso, head, upper arms, and groin, and the legs above the knee. They can also include a helmet and mask, though these are not considered integral.</span></p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.sPKkavq6O0SoxiPj","armor":{"physical":4,"supernatural":0},"rarity":"6","zeni":"25 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000006","name":"Cumbersome"},{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Traveling Clothes","quantity":1,"description":"<p><span class=\"fontstyle0\">Traveling clothes ordinarily consist of roughspun garments designed to resist wear and tear. They can be anything from robes to a kimono or jacket and leggings and are often accentuated with a hat or cloak</span>.</p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.zcsgspz4VluSMeI0","armor":{"physical":2,"supernatural":0},"rarity":"2","zeni":"2 bu","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000012","name":"Mundane"},{"id":"L5RCorePro000016","name":"Subtle"}]},{"name":"Traveling pack","quantity":1,"description":"<p><span class=\"fontstyle0\">Blanket, bowl, chopsticks, four days of travel rations, flint and tinder, and any three other items of the player’s choice that are rarity 4 or lower.</span></p>","source":{"book":"core_rulebook","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.Rex7fGo6R1KuUhQJ","rarity":"1","zeni":"10 koku","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Kubi Bukuro","quantity":1,"description":"<p>These are simple net bags used to carry the severed head of an enemy, which is considered both a trophy and a good omen. Lion Clan samurai use them to carry their trophies without touching dead flesh, but the Kuni family uses them for collecting samples of Shadowlands creatures for study.</p>","source":{"book":"core_rulebook","page":242},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.6J25vJx1tVirgXf1","rarity":"2","zeni":"2 zeni","properties":[{"id":"L5RCorePro000011","name":"Wargear"}]}]},{"xp":74,"label":"Gunsō, Rank 3","rank":3,"school":"Hida Defender School","foundry_id":"T8Lx3NypuCOqLcpc","rings":{"air":2,"earth":3,"fire":2,"water":1,"void":3},"skills":{"artisan":{"aesthetics":0,"composition":1,"design":0,"smithing":0},"martial":{"fitness":2,"melee":2,"ranged":2,"unarmed":1,"meditation":0,"tactics":2},"scholar":{"culture":0,"government":1,"medicine":0,"sentiment":0,"theology":0},"social":{"command":4,"courtesy":1,"games":0,"performance":0},"trade":{"commerce":0,"labor":1,"seafaring":0,"skulduggery":1,"survival":2}},"social":{"honor":45,"glory":44,"status":30,"ninjo":"Longs to travel Rokugan, or possibly even beyond.","giri":"Hiruma Nobuyasu is their lord. They insist that she command her unit, defending the Kaiu Wall.","bushido_tenets":{"paramount":"Courage","less_significant":"Sincerity"}},"derived":{"endurance":10,"composure":8,"focus":4,"vigilance":2,"void_points":3},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[{"label":"Martial Arts [Ranged] +1 (0 -> 1)","type":"skill","skill":"ranged","ring":"void","at_rank":1,"xp":2,"in_curriculum":true},{"label":"Martial Arts [Melee] +1 (1 -> 2)","type":"skill","skill":"melee","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Martial Arts [Unarmed] +1 (0 -> 1)","type":"skill","skill":"unarmed","ring":"void","at_rank":1,"xp":2,"in_curriculum":true},{"label":"Martial Arts [Ranged] +1 (1 -> 2)","type":"skill","skill":"ranged","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Command +1 (1 -> 2)","type":"skill","skill":"command","ring":"void","at_rank":2,"xp":4,"in_curriculum":true},{"label":"Void +1 (2 -> 3)","type":"ring","ring":"void","at_rank":2,"xp":9,"in_curriculum":false},{"label":"Labor +1 (0 -> 1)","type":"skill","skill":"labor","ring":"void","at_rank":2,"xp":2,"in_curriculum":true},{"label":"Command +1 (2 -> 3)","type":"skill","skill":"command","ring":"void","at_rank":2,"xp":6,"in_curriculum":true},{"label":"Composition +1 (0 -> 1)","type":"skill","skill":"composition","ring":"void","at_rank":2,"xp":2,"in_curriculum":false},{"label":"Command +1 (4 -> 5)","type":"skill","skill":"command","ring":"void","at_rank":1,"xp":10,"in_curriculum":true,"via":"Gunsō"},{"label":"Government +1 (0 -> 1)","type":"skill","skill":"government","ring":"void","at_rank":1,"xp":2,"in_curriculum":true,"via":"Gunsō"}],"techniques":[{"name":"Striking as Earth","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"kata","rank":1,"description":"<p><span class=\"fontstyle0\"><em>After striking, the bushi roots themself to the ground, hunkering down to make sure their armor takes the brunt of a hit or raising a weapon in a warding position where it can deflect harm without being damaged.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee, Ranged, or Unarmed] (earth) check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth)(op)+: </span><span class=\"fontstyle3\">Treat your physical resistance as 1 higher per </span><span class=\"fontstyle4\">(op) </span><span class=\"fontstyle3\">spent this way until the beginning of your next turn.</span></p>","source":{"book":"core_rulebook","page":178},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.aKTfAZXbHo77kHOq"},{"name":"Lord Hida’s Grip (Crab)","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>The Kami Hida, patron of the Crab Clan, was a legendary slayer of monsters. He beheaded the massive demon that once menaced the rose-marble palace, and ripped out one skull of the two-headed Kabuto no Oni and crushed the other head with it. However, Hida was no mere brute: he was cunning, killing monsters by exploiting their weaknesses. Warriors of the Crab Clan train in similar techniques. They turn their foes' great weight against them by pinning or strategically damaging specific body parts.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As an Attack action, you may make a </span><span class=\"fontstyle2\">Fitness (void) check </span><span class=\"fontstyle3\">targeting one creature of silhouette 3 or larger at range 0–1. The TN of the check is equal to the silhouette of the target (to a minimum of 1).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, your target suffers the Immobilized condition. If you succeed, you count as granting assistance (see page 26) to all characters who perform Attack actions against your target. This effect persists until the beginning of your next turn.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(void)(op): </span><span class=\"fontstyle3\">Your target must resist with a </span><span class=\"fontstyle2\">Fitness check </span><span class=\"fontstyle3\">or suffer physical damage equal to its silhouette, ignoring its resistance, and the Prone condition. The TN of this check is equal to your school rank.</span></p>","source":{"book":"core_rulebook","page":176},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.ERExWdY04GNvu3p0","skill":"fitness"},{"name":"Way of the Crab","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p><span class=\"fontstyle0\">Ignore the Cumbersome quality of armor you wear.</span></p><p><span class=\"fontstyle0\">Once per round, before making a check to resist a critical strike, you may reduce the severity of that critical strike by the physical resistance of your armor plus your school rank (to a minimum of 0).</span></p>","source":{"book":"core_rulebook","page":57},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.7LHxYqmpqMUETLEq"},{"name":"Appreciate the Scenery","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<p><span class=\"fontstyle0\"><em>In many lands, including Rokugan, the beauty of the natural world inspires art, poetry, and other works of note, even (or perhaps especially) when it is stark and dangerous. When on a long and perilous journey into foreign lands where deadly intrigues surely await, finding beauty in the rougher parts of the world can be a much-needed source of solace.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Support action check targeting another character, if you and the character you are targeting are in Dangerous, Entangling, Hallowed, Imbalanced, or Obscuring terrain, you may spend (op) as follows:</span></p><p><span class=\"fontstyle2\">(earth) or</span><span class=\"fontstyle4\"> (water)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">You and your target each remove strife equal to your ranks in Composition.</span></p><p><span class=\"fontstyle2\">(air) or (fire)</span><span class=\"fontstyle4\">(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">You and your target gain the Emboldened condition (see page 133).</span></p><p><span class=\"fontstyle2\">(void)(op): </span><span class=\"fontstyle3\">Your and your target gain the Centered condition (see page 133).</span></p>","source":{"book":"children_of_the_five_winds","page":116},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.gbUpw4ife9RdWbK9"},{"name":"Honest Assessment","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<p><span class=\"fontstyle0\"><em>Honesty is a virtue of Bushidō, but direct honesty is often seen as rudeness among the samurai—instead, one is expected to find a polite way to imply one’s meaning to spare the feelings of the other involved. As a result, directness can be something of a rare and valuable commodity.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may make a </span><span class=\"fontstyle2\">TN 2 Courtesy (earth) check </span><span class=\"fontstyle3\">to appraise the weaknesses of a character.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, choose one of the target’s known disadvantages. The target does not apply that disadvantage to their checks until the end of the scene.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(earth)(op)+: </span><span class=\"fontstyle3\">Choose one additional disadvantage per (op) spent this way.</span></p><p><span class=\"fontstyle5\">(earth)(op)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">Reduce the TN of the target’s next skill check using the ring the disadvantage is attached to by 2.</span></p>","source":{"book":"core_rulebook","page":216},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.t427qRaOh42dfbVM","skill":"courtesy"},{"name":"Rushing Avalanche Style","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>When adopting this style, the bushi strikes with reckless abandon using a heavy armament. Thanks to the sheer weight of their weapon and the ferocity of their strikes, even a glancing blow can cause serious harm, and a telling blow usually ends the battle.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee] check using a blunt weapon, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(op): </span><span class=\"fontstyle3\">If you fail with a shortfall of two or less, your target suffers physical damage equal to your ranks in Fitness.</span></p><p><span class=\"fontstyle2\">(op): </span><span class=\"fontstyle3\">If you succeed and your target is Prone, increase the damage you deal by your ranks in Fitness.</span></p>","source":{"book":"core_rulebook","page":180},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.EZG0aAg9oxEUou5u"},{"name":"Staggering Shot","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>Putting an arrow at a foe’s feet can cause them to stumble or trip, and an experienced archer knows how to take full advantage of this, planting bolts to break an</em></span><em> </em><span class=\"fontstyle0\"><em>enemy’s stride or pinning their clothes to slow them down, making any approach extremely treacherous.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you perform a Martial Arts [Ranged] check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth) or (fire)(op)(op): </span><span class=\"fontstyle3\">Your target treats all terrain as having the Dangerous quality. This effect persists until the end of your next turn.</span></p><p><span class=\"fontstyle2\">(air) or (water)(op)(op): </span><span class=\"fontstyle3\">Your target treats all terrain as having the Entangling quality. This effect persists until the end of your next turn.</span></p>","source":{"book":"path_of_waves","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.6N5n9fweaz1CbLCu"},{"name":"Touchstone of Courage","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"shuji","rank":3,"description":"<p><span class=\"fontstyle0\"><em>Armies are rarely routed in the field; instead, most collapse when morale becomes impossible to maintain. As panic rises in the ranks, soldiers look to leaders to set an example. The character does just this, speaking to the importance of duty to bring their troops back from the edge of chaos.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may make a </span><span class=\"fontstyle2\">TN 4 Command (earth) check </span><span class=\"fontstyle3\">targeting any number of characters (or your cohort during a mass battle).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed during an intrigue, duel, or skirmish conflict, each target increases their composure by your Earth Ring. This effect persists until the end of the scene. If you succeed during a mass battle, increase your army’s discipline by your Earth Ring plus your bonus successes. This effect persists until the end of the scene.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(earth)(op)(op): </span><span class=\"fontstyle3\">During an intrigue, duel, or skirmish, each target removes strife equal to your Earth Ring.</span></p><p><span class=\"fontstyle2\">(earth)(op)(op): </span><span class=\"fontstyle3\">During a mass battle, your army removes panic equal to your Earth Ring.</span></p>","source":{"book":"core_rulebook","page":217},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.fFxQOBXLb9ol9owk","skill":"command"},{"name":"Thunderbolt Style","via":"Gunsō","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":4,"description":"<p><span class=\"fontstyle0\"><em>Hitting a target with a thrown weapon is difficult; hitting more than one target with the same throw is even harder. However, a warrior of sufficient skill can potentially harm multiple targets with a properly placed spear or ax throw, the projectile striking one foe and caroming off at an unexpected angle or causing the primary target to collapse into another. Such an unexpected tactic can catch an entire unit off guard, forcing them to spread out when staying close together would be advantageous.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make an Attack action check in which you throw your weapon, you may spend (op) as follows:</span></p><p><span class=\"fontstyle4\">(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">Choose another character at range 0–1 of your target with vigilance lower than your ranks in Fitness plus (op) spent this way. That character suffers damage equal to your weapon’s base damage. You can activate this opportunity multiple times, choosing different characters to affect each time.</span></p>","source":{"book":"children_of_the_five_winds","page":110},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.rwDHm7Q3qmjDJZRg"},{"name":"Deflective Defense","via":"Gunsō","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":3,"description":"<p><span class=\"fontstyle0\"><em>Large-enough weapons can, in a pinch, serve as shields against missile attacks. If a warrior plants their weapon in the ground and takes cover behind it with a narrow profile, even a </em></span><span class=\"fontstyle2\"><em>bisentō </em></span><span class=\"fontstyle0\"><em>makes the likelihood of a lethal hit with an arrow or dart far lower.</em></span></p><p><span class=\"fontstyle3\"><strong>Activation:</strong> </span><span class=\"fontstyle0\">As a Movement and Support action using a readied Cumbersome weapon, you may make a </span><span class=\"fontstyle3\">TN 2 Martial Arts [Melee] (earth) check</span><span class=\"fontstyle0\">.</span></p><p><span class=\"fontstyle3\"><strong>Effects:</strong> </span><span class=\"fontstyle0\">If you succeed, treat your physical resistance against attacks made by characters at range 2–6 as increased by your ranks in Fitness.\\</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle3\">(earth)(op)(op): </span><span class=\"fontstyle0\">After you defend against physical damage from an attack made by a character at range 2–6, that character suffers 2 strife.</span></p>","source":{"book":"path_of_waves","page":88},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.eC8kPJscUbiEoE7c","skill":"melee"},{"name":"Tactical Assessment","via":"Gunsō","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>Akodo’s </em></span><span class=\"fontstyle2\"><em>Leadership </em></span><span class=\"fontstyle0\"><em>and Bayushi’s </em></span><span class=\"fontstyle2\"><em>Lies </em></span><span class=\"fontstyle0\"><em>agree on a few topics, for both leaders were practical to a certain degree, even if Akodo famously scorned many of Bayushi’s methods. As the scholar Hida Fuyuko noted in her revelatory commentary on </em></span><span class=\"fontstyle2\"><em>Leadership</em></span><span class=\"fontstyle0\"><em>’s lessons for commanders on the Kaiu Wall, the most famous meeting of these two minds comes on the matter of preparation: battles are not won in the field, but in the leadup to the conflict. Even in small clashes, the warrior who better understands the terrain, the strength of their own forces, and the composition of the enemy’s troops is usually victorious.</em></span></p><p><span class=\"fontstyle3\"><strong>Activation:</strong> </span><span class=\"fontstyle2\">When you make an Initiative check, you may spend</span><span class=\"fontstyle4\"> (op) </span><span class=\"fontstyle2\">in the following way:</span></p><p><span class=\"fontstyle3\">(air)(op): </span><span class=\"fontstyle2\">Choose an enemy in the conflict. Learn one of their advantages (of their choice) and their physical or supernatural resistance (your choice).</span></p><p><span class=\"fontstyle3\">(earth)(op): </span><span class=\"fontstyle2\">Choose a character in the conflict. They do not apply any of their disadvantages to their checks until the end of their first turn.</span></p><p><span class=\"fontstyle3\">(water)(op): </span><span class=\"fontstyle2\">Choose a piece of terrain in the scene (see </span><span class=\"fontstyle3\">Terrain </span><span class=\"fontstyle2\">on page 267). Until the start of your first turn, it counts as having the Obscuring quality for Attack action checks targeting you and your allies.</span></p><p><span class=\"fontstyle3\">(fire)(op): </span><span class=\"fontstyle2\">Choose a character in the conflict and one of their advantages you know. Until the end of their first turn, they apply that advantage to all of their checks.</span></p>","source":{"book":"core_rulebook","page":178},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.TcFVNDk57aKGpLR2"},{"name":"Rallying Cry","via":"Gunsō","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"shuji","rank":3,"description":"<p><span class=\"fontstyle0\"><em>The leader roars, calling their troops to battle, and the voice of an army echoes around them as the single cry is joined by many. As one, the troops surge forward to claim victory or perish in the attempt.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may make a </span><span class=\"fontstyle2\">TN 2 Command (fire) </span><span class=\"fontstyle3\">or </span><span class=\"fontstyle2\">Performance (fire) check </span><span class=\"fontstyle3\">targeting any number of characters in the scene (or one cohort in a mass battle).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, the targets are energized and excited by your rhetoric. After </span><span class=\"fontstyle2\">Step 5: Choose Kept Dice</span><span class=\"fontstyle3\">, each target adds a kept (ring) set to an (op)(st) result. This effect persists until the end of your next turn.</span></p><h4><span class=\"fontstyle5\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(fire)(op)+: </span><span class=\"fontstyle3\">In a skirmish, each enemy in the scene suffers 1 strife per (op) spent this way.</span></p><p><span class=\"fontstyle2\">(fire)(op)+: </span><span class=\"fontstyle3\">In a mass battle, the enemy army suffers 1 panic per (op) spent this way.</span> <br style=\" font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: 2; text-align: -webkit-auto; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px; \"></p>","source":{"book":"core_rulebook","page":219},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.4Z888LVUKQoDU4n8","skill":"command,performance"},{"name":"Lead from the Front","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":3,"kind":"title_ability","rank":1,"description":"<p><span class=\"fontstyle0\">When you defeat an opponent in a clash, your cohort removes panic equal to the opponent’s glory rank.</span></p><p><span class=\"fontstyle0\">Once per round when you succeed at an Attack action check during a mass battle, your cohort removes panic equal to half of the attrition you inflict.</span></p>","source":{"book":null,"page":0},"uuid":"Compendium.l5r5e-compendia-sortilege.title-abilities-l5r-sortilege.Item.YTRyf5NAEdnGa2K1"}],"peculiarities":[{"name":"Light Sleeper","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"water","types":"Physical","description":"<p><span class=\"fontstyle0\"><em>“You see these scars?” she asked. He nodded respectfully at the Hiruma. It looked like someone had run a rake down her face—then repeated the action several times.</em></span></p><p><span class=\"fontstyle0\"><em>“This is what you get when you dare slumber here. Everyone else died that night.” She closed her eyes for a moment, then opened them abruptly, startling him. “You rest your guard, you die.” She looked closely at him. “You learn to stay awake, even when you sleep. Or you join the rest of my old patrol.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Light Sleeper distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You rouse from sleep very easily, a trick considered essential in hostile territory. You are trained to awaken before danger arrives, sleep with your weapons ready, and pretend to be in a deep sleep to lure enemies closer. You can go from a deep sleep to fully alert and fighting in the blink of an eye.</span></p></li><li><p><span class=\"fontstyle0\">- When performing a check that calls on rapidly recovering from sleep (such as a Survival (water) check to detect a threatening sound while dozing or a Fitness (water) check to react even when someone else is standing watch), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"shadowlands","page":96},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.ZtoejR7hmjZ0aE8k"},{"name":"Encompassing Duty","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"earth","types":"Mental","description":"<p><em>“I will lay down my life for my family. Nothing will stand in the way of that.”</em></p><p><em>– Aina, Ashigaru of the Lion</em></p><p></p><p>The following apply to a character with the Encompassing Duty adversity:</p><ul><li><p>- You have a duty to something: your family, a friend, a cause, or some other person or ideal. This duty should manifest into at least one discernible goal, one you can work out with the GM. A goal may be to provide for your family, rescue a friend, or achieve a similar aim. You have a difficult time relaxing or focusing on tasks that do not somehow advance your goal, and this may manifest in several ways, including frustration, anger, worry, or nervousness. </p></li><li><p>- Whenever you make a check related to overcoming something that could hinder you in achieving your duty (such as a Meditation (earth) check to keep a cool head in an ambush or a Courtesy (earth) check to reason with a stubborn shopkeeper), you must choose and reroll two dice containing (su) or (ex) . After resolving the check, if you failed, you gain 1 Void point.</p></li></ul>","source":{"book":"path_of_waves","page":72},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.TP83fjX8gnxELunG"},{"name":"Travel","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"water","types":"Mental, Physical","description":"<p><span class=\"fontstyle0\"><em>The old man sat heavily on the stool outside the constabulary office. He removed his straw hat, wiped his brow with his sleeve, and returned the hat to his head. His eyes, shaded by the wide brim, looked out at Yūka. The young girl smiled.</em></span></p><p><span class=\"fontstyle0\"><em>“Young lady, I have been from one side of Rokugan to the other—from Khanbulak to the Islands of Silk and Spice—and I have seen amazing sights. I will tell you this: in all my travels, I have become convinced of three things.” He counted them off on gnarled fingers. “All crows are black, it always rains when you don’t want it to, and Rokugan’s greatest treasure—a prize without equal—is its people.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Travel passion:</span></p><ul><li><p><span class=\"fontstyle3\">- You are not unsettled by foreign customs, and you can comfortably fit in even in strange environments.</span></p></li><li><p><span class=\"fontstyle3\">- After performing a check to travel to a new location or interact with a novel thing (such as a Survival (water) check to try to identify a new plant, animal, or phenomenon, or a Seafaring (water) check to travel by boat), you remove 3 strife.</span></p></li></ul>","source":{"book":"core_rulebook","page":115},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.7keAIKn0N8wjEsGa"},{"name":"Battle Trauma","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"fire","types":"Mental, Physical","description":"<p><em>The thousand cuts I have borne<br>And the thousand I have delivered<br>Paint my dreams in red<br>Broad brushstrokes to draw pictures<br>I cannot put to paper.<br>Do my ears ring from old age<br>Or is that steel’s song and the warrior’s cry<br>Gone so long ago<br>But never gone?</em></p><p><strong>Effects:</strong> The following apply to a character with the Battle Trauma anxiety:</p><ul><li><p>-  At the start of a duel, skirmish, or mass battle, your hands shake, your body tenses up, or your mind might even lock down. You can act normally, but your unsettled state is obvious to everyone around you, and others may try to exploit it.</p></li><li><p>-  After performing a check related to battle (such as a Martial Arts [Melee] (fire) check to strike down a foe or a Tactics (fire) check to generate initiative), you receive 3 strife. (Your GM can choose not to inflict this strife after the you have taken a few turns and thematically overcome your trauma.) If this is the first time this has occurred this scene, gain 1 Void point.</p></li></ul>","source":{"book":"core_rulebook","page":131},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.jlSq86lbglLrHXp8"},{"name":"Paragon of Courage","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"fire","types":"Mental, Virtue","description":"<p><span class=\"fontstyle0\"><em>“The heroes of myth—even the ones who were not of divine blood—did not live as humans do. It is impossible to embody an ideal without surpassing some part of your own humanity.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Paragon of Courage distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You believe utterly in Courage, and others instinctively discern that your actions are genuine when you act in accordance with it.</span></p></li><li><p><span class=\"fontstyle3\">- When performing a check for which you need to convince others of, or leverage your faith in, Courage (such as a Performance check to recount a tale that impresses its importance upon others or a Martial Arts [Melee] check to take up arms for this cause), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"core_rulebook","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.trppadBbshGjbSP2"}],"titles":[{"name":"Gunsō","xp_used":24,"xp_cost":24,"in_curriculum":false,"bought_at_rank":3,"description":"<p><span class=\"fontstyle0\">While the vast majority of soldiers in a Rokugani army are ashigaru and conscripts, many samurai are called to military service, either in the armies of their own clan or in the Imperial Legions. When samurai do take to the field, they often these serve in leadership positions. While each lord's forces have their own structure and character, common titles are used throughout Rokugan to indicate similar levels of authority. When a lord gathers a large force for battle, they may nominate one or more gunsō to command the kashira who lead individual units.</span></p><p><span class=\"fontstyle0\">A gunsō is responsible for all aspects of battle readiness for the troops under their command, including the troops’ training, discipline, and equipment. When battle begins, gunsō direct their troops in accordance with commands from their superiors, meaning they have to maintain good awareness not only of their own unit but also of the broader battle unfolding around them. Perhaps most importantly, gunsō are expected to display conspicuous leadership during battle, leading their troops from the front and rallying their soldiers, keeping them in the fight even as losses mount and their morale begins to waver.</span></p><p><span class=\"fontstyle2\"><strong>Assigned By:</strong> </span><span class=\"fontstyle0\">A daimyō may assign a samurai a rank within their military forces, and samurai serving within the military rank structure may be promoted by a superior officer.</span></p><p><span class=\"fontstyle2\"><strong>Status Award:</strong> </span><span class=\"fontstyle0\">+5 (to a minimum of 20)</span></p><p><span class=\"fontstyle2\"><strong>Title Ability:</strong> Lead from the Front</span></p><h2>Curriculum</h2><table><tbody><tr><td><p>Martial Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Command</p></td><td><p>Skill</p></td></tr><tr><td><p>Government</p></td><td><p>Skill</p></td></tr><tr><td><p><a class=\"compendium-link\" data-pack=\"l5r5e.core-techniques-kata\">(kata) Rank 1-4 Kata</a></p></td><td><p>Tech. Grp.</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-shuji.Item.L5RCoreShu000020\" data-pack=\"l5r5e.core-techniques-shuji\" data-type=\"Item\" data-id=\"L5RCoreShu000020\">(shuji) Rallying Cry</a> (prereq)</p></td><td><p>Technique</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-shuji.Item.L5RCoreShu000026\" data-pack=\"l5r5e.core-techniques-shuji\" data-type=\"Item\" data-id=\"L5RCoreShu000026\">(shuji) Stirring the Embers</a> (prereq)</p></td><td><p>Technique</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-shuji.Item.L5RCoreShu000011\" data-pack=\"l5r5e.core-techniques-shuji\" data-type=\"Item\" data-id=\"L5RCoreShu000011\">(shuji) Touchstone of Courage</a> (prereq)</p></td><td><p>Technique</p></td></tr></tbody></table>","source":{"book":"emerald_empire","page":250},"uuid":"Compendium.l5r5e-compendia-sortilege.titles-l5r-sortilege.Item.2R7nNp7NWNLkVs5j"}],"bonds":[],"signature_scrolls":[],"gear":[{"name":"Club","quantity":1,"description":"<p><span class=\"fontstyle0\">The humble club is perhaps the oldest weapon in Rokugan—at least among humans. Often little more than a length of stout wood or shaped stone, a club can be fashioned with available materials by nearly anyone. While a club can certainly be used to kill, doing so takes some work on the part of the wielder</span>.</p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.ElFJfEcGvWe6A5yU","damage":5,"deadliness":2,"range":"0-1","grip_2":"Damage +1","skill":"melee","category":"Blunt Weapons","rarity":"1","zeni":"1 bu","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Katana","quantity":1,"description":"<p><span class=\"fontstyle0\">As much a work of art as it is a weapon, the katana is perhaps the most revered weapon in Rokugan. It has an elegant, slightly curved blade between three and four feet long, made of steel that is specially folded during its creation. This unique forging style ensures that the inner part of the blade remains springy and soft while the outside is as hard as tempered steel. Each sword likely has a history and legacy, and it is a constant reminder of the weight that destiny has placed upon its bearer’s shoulders as a samurai of Rokugan</span>.</p>","source":{"book":"core_rulebook","page":232},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.BhKwwnN5UHI5rZpp","damage":4,"deadliness":5,"range":"1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"20 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Knife","quantity":1,"description":"<p><span class=\"fontstyle0\">Knives come in a dizzying array of types and styles, from the familiar crudely constructed knife in a peasant’s kitchen to the deadly combat knives samurai take into battle. Those particularly designed for combat—like the aiguchi—are often equipped with small hand guards to make them more useful in the field.</span></p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.n8xA05Fb9WpXg3oo","damage":2,"deadliness":4,"range":"0","grip_2":"Deadliness +2","skill":"melee","category":"Hand Weapons","rarity":"1","zeni":"1 koku","properties":[{"id":"L5RCorePro000001","name":"Razor-Edged"},{"id":"L5RCorePro000005","name":"Concealable"},{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Tetsubō","quantity":1,"description":"<p><span class=\"fontstyle0\">Long and narrow, a tetsubō can be as tall as a human and normally is constructed of iron or hardwood. Above its grip, a tetsubō is covered in steel, iron, or even jade spikes or studs that add to the weapon’s lethality and crush armor or plated carapace with ease.</span></p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.CW6h0NSzTEhimQXw","damage":7,"deadliness":3,"range":"1-2","grip_1":"N/A","skill":"melee","category":"Blunt Weapons","rarity":"5","zeni":"20 koku","properties":[{"id":"L5RCorePro000006","name":"Cumbersome"},{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Wakizashi","quantity":1,"description":"<p><span class=\"fontstyle0\">Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</span></p>","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Kamayari","quantity":1,"description":"<p><span class=\"fontstyle0\">A </span><span class=\"fontstyle2\">kamayari </span><span class=\"fontstyle0\">is a spear with a hooked protrusion on one or both sides of the blade, similar to a ji. While the hook’s most obvious applications are blocking attacks and dragging foes off horseback, it also has practical noncombat applications. A shinobi might swing from a sturdy tree limb using the hook or might use it to climb a high fence. If the spear shaft has holes in it, the shinobi can use the shaft to measure distances or can slot bars into the holes to use it as a ladder. Finally, the hook is useful for carrying items on long walks.</span></p>","source":{"book":"court_of_stones","page":110},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.PsmRwhHYBz0daKi5","damage":4,"deadliness":3,"range":"2","grip_1":"N/A","skill":"melee","category":"Specialist Weapons","rarity":"7","zeni":"8 koku","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000007","name":"Snaring"}]},{"name":"Lacquered Armor","quantity":1,"description":"<p><span class=\"fontstyle0\">Heavier than ashigaru armor, lacquered armor is worn by samurai who desire a good mix of protection and grandeur, and is just at home at war as at a martial ceremony. These suits are made of thick leather or steel plates stitched or riveted to a leather backing. They protect the torso, head, upper arms, and groin, and the legs above the knee. They can also include a helmet and mask, though these are not considered integral.</span></p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.sPKkavq6O0SoxiPj","armor":{"physical":4,"supernatural":0},"rarity":"6","zeni":"25 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000006","name":"Cumbersome"},{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Traveling Clothes","quantity":1,"description":"<p><span class=\"fontstyle0\">Traveling clothes ordinarily consist of roughspun garments designed to resist wear and tear. They can be anything from robes to a kimono or jacket and leggings and are often accentuated with a hat or cloak</span>.</p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.zcsgspz4VluSMeI0","armor":{"physical":2,"supernatural":0},"rarity":"2","zeni":"2 bu","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000012","name":"Mundane"},{"id":"L5RCorePro000016","name":"Subtle"}]},{"name":"Traveling pack","quantity":1,"description":"<p><span class=\"fontstyle0\">Blanket, bowl, chopsticks, four days of travel rations, flint and tinder, and any three other items of the player’s choice that are rarity 4 or lower.</span></p>","source":{"book":"core_rulebook","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.Rex7fGo6R1KuUhQJ","rarity":"1","zeni":"10 koku","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Kubi Bukuro","quantity":1,"description":"<p>These are simple net bags used to carry the severed head of an enemy, which is considered both a trophy and a good omen. Lion Clan samurai use them to carry their trophies without touching dead flesh, but the Kuni family uses them for collecting samples of Shadowlands creatures for study.</p>","source":{"book":"core_rulebook","page":242},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.6J25vJx1tVirgXf1","rarity":"2","zeni":"2 zeni","properties":[{"id":"L5RCorePro000011","name":"Wargear"}]}]},{"xp":107,"label":"Gunsō, Rank 4","rank":4,"school":"Hida Defender School","foundry_id":"xRpcwXitGcOO6hQP","rings":{"air":2,"earth":3,"fire":2,"water":1,"void":3},"skills":{"artisan":{"aesthetics":0,"composition":1,"design":0,"smithing":0},"martial":{"fitness":3,"melee":3,"ranged":2,"unarmed":1,"meditation":0,"tactics":2},"scholar":{"culture":0,"government":1,"medicine":0,"sentiment":0,"theology":0},"social":{"command":4,"courtesy":1,"games":0,"performance":0},"trade":{"commerce":0,"labor":2,"seafaring":1,"skulduggery":1,"survival":2}},"social":{"honor":45,"glory":44,"status":30,"ninjo":"Longs to travel Rokugan, or possibly even beyond.","giri":"Hiruma Nobuyasu is their lord. They insist that she command her unit, defending the Kaiu Wall.","bushido_tenets":{"paramount":"Courage","less_significant":"Sincerity"}},"derived":{"endurance":10,"composure":8,"focus":4,"vigilance":2,"void_points":3},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[{"label":"Martial Arts [Ranged] +1 (0 -> 1)","type":"skill","skill":"ranged","ring":"void","at_rank":1,"xp":2,"in_curriculum":true},{"label":"Martial Arts [Melee] +1 (1 -> 2)","type":"skill","skill":"melee","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Martial Arts [Unarmed] +1 (0 -> 1)","type":"skill","skill":"unarmed","ring":"void","at_rank":1,"xp":2,"in_curriculum":true},{"label":"Martial Arts [Ranged] +1 (1 -> 2)","type":"skill","skill":"ranged","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Command +1 (1 -> 2)","type":"skill","skill":"command","ring":"void","at_rank":2,"xp":4,"in_curriculum":true},{"label":"Void +1 (2 -> 3)","type":"ring","ring":"void","at_rank":2,"xp":9,"in_curriculum":false},{"label":"Labor +1 (0 -> 1)","type":"skill","skill":"labor","ring":"void","at_rank":2,"xp":2,"in_curriculum":true},{"label":"Command +1 (2 -> 3)","type":"skill","skill":"command","ring":"void","at_rank":2,"xp":6,"in_curriculum":true},{"label":"Composition +1 (0 -> 1)","type":"skill","skill":"composition","ring":"void","at_rank":2,"xp":2,"in_curriculum":false},{"label":"Command +1 (4 -> 5)","type":"skill","skill":"command","ring":"void","at_rank":1,"xp":10,"in_curriculum":true,"via":"Gunsō"},{"label":"Government +1 (0 -> 1)","type":"skill","skill":"government","ring":"void","at_rank":1,"xp":2,"in_curriculum":true,"via":"Gunsō"},{"label":"Fitness +1 (2 -> 3)","type":"skill","skill":"fitness","ring":"void","at_rank":3,"xp":6,"in_curriculum":true},{"label":"Seafaring +1 (0 -> 1)","type":"skill","skill":"seafaring","ring":"void","at_rank":3,"xp":2,"in_curriculum":true},{"label":"Labor +1 (1 -> 2)","type":"skill","skill":"labor","ring":"void","at_rank":3,"xp":4,"in_curriculum":true},{"label":"Martial Arts [Melee] +1 (2 -> 3)","type":"skill","skill":"melee","ring":"void","at_rank":3,"xp":6,"in_curriculum":true}],"techniques":[{"name":"Striking as Earth","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"kata","rank":1,"description":"<p><span class=\"fontstyle0\"><em>After striking, the bushi roots themself to the ground, hunkering down to make sure their armor takes the brunt of a hit or raising a weapon in a warding position where it can deflect harm without being damaged.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee, Ranged, or Unarmed] (earth) check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth)(op)+: </span><span class=\"fontstyle3\">Treat your physical resistance as 1 higher per </span><span class=\"fontstyle4\">(op) </span><span class=\"fontstyle3\">spent this way until the beginning of your next turn.</span></p>","source":{"book":"core_rulebook","page":178},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.aKTfAZXbHo77kHOq"},{"name":"Lord Hida’s Grip (Crab)","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>The Kami Hida, patron of the Crab Clan, was a legendary slayer of monsters. He beheaded the massive demon that once menaced the rose-marble palace, and ripped out one skull of the two-headed Kabuto no Oni and crushed the other head with it. However, Hida was no mere brute: he was cunning, killing monsters by exploiting their weaknesses. Warriors of the Crab Clan train in similar techniques. They turn their foes' great weight against them by pinning or strategically damaging specific body parts.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As an Attack action, you may make a </span><span class=\"fontstyle2\">Fitness (void) check </span><span class=\"fontstyle3\">targeting one creature of silhouette 3 or larger at range 0–1. The TN of the check is equal to the silhouette of the target (to a minimum of 1).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, your target suffers the Immobilized condition. If you succeed, you count as granting assistance (see page 26) to all characters who perform Attack actions against your target. This effect persists until the beginning of your next turn.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(void)(op): </span><span class=\"fontstyle3\">Your target must resist with a </span><span class=\"fontstyle2\">Fitness check </span><span class=\"fontstyle3\">or suffer physical damage equal to its silhouette, ignoring its resistance, and the Prone condition. The TN of this check is equal to your school rank.</span></p>","source":{"book":"core_rulebook","page":176},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.ERExWdY04GNvu3p0","skill":"fitness"},{"name":"Way of the Crab","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p><span class=\"fontstyle0\">Ignore the Cumbersome quality of armor you wear.</span></p><p><span class=\"fontstyle0\">Once per round, before making a check to resist a critical strike, you may reduce the severity of that critical strike by the physical resistance of your armor plus your school rank (to a minimum of 0).</span></p>","source":{"book":"core_rulebook","page":57},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.7LHxYqmpqMUETLEq"},{"name":"Appreciate the Scenery","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<p><span class=\"fontstyle0\"><em>In many lands, including Rokugan, the beauty of the natural world inspires art, poetry, and other works of note, even (or perhaps especially) when it is stark and dangerous. When on a long and perilous journey into foreign lands where deadly intrigues surely await, finding beauty in the rougher parts of the world can be a much-needed source of solace.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Support action check targeting another character, if you and the character you are targeting are in Dangerous, Entangling, Hallowed, Imbalanced, or Obscuring terrain, you may spend (op) as follows:</span></p><p><span class=\"fontstyle2\">(earth) or</span><span class=\"fontstyle4\"> (water)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">You and your target each remove strife equal to your ranks in Composition.</span></p><p><span class=\"fontstyle2\">(air) or (fire)</span><span class=\"fontstyle4\">(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">You and your target gain the Emboldened condition (see page 133).</span></p><p><span class=\"fontstyle2\">(void)(op): </span><span class=\"fontstyle3\">Your and your target gain the Centered condition (see page 133).</span></p>","source":{"book":"children_of_the_five_winds","page":116},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.gbUpw4ife9RdWbK9"},{"name":"Honest Assessment","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<p><span class=\"fontstyle0\"><em>Honesty is a virtue of Bushidō, but direct honesty is often seen as rudeness among the samurai—instead, one is expected to find a polite way to imply one’s meaning to spare the feelings of the other involved. As a result, directness can be something of a rare and valuable commodity.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may make a </span><span class=\"fontstyle2\">TN 2 Courtesy (earth) check </span><span class=\"fontstyle3\">to appraise the weaknesses of a character.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, choose one of the target’s known disadvantages. The target does not apply that disadvantage to their checks until the end of the scene.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(earth)(op)+: </span><span class=\"fontstyle3\">Choose one additional disadvantage per (op) spent this way.</span></p><p><span class=\"fontstyle5\">(earth)(op)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">Reduce the TN of the target’s next skill check using the ring the disadvantage is attached to by 2.</span></p>","source":{"book":"core_rulebook","page":216},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.t427qRaOh42dfbVM","skill":"courtesy"},{"name":"Rushing Avalanche Style","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>When adopting this style, the bushi strikes with reckless abandon using a heavy armament. Thanks to the sheer weight of their weapon and the ferocity of their strikes, even a glancing blow can cause serious harm, and a telling blow usually ends the battle.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee] check using a blunt weapon, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(op): </span><span class=\"fontstyle3\">If you fail with a shortfall of two or less, your target suffers physical damage equal to your ranks in Fitness.</span></p><p><span class=\"fontstyle2\">(op): </span><span class=\"fontstyle3\">If you succeed and your target is Prone, increase the damage you deal by your ranks in Fitness.</span></p>","source":{"book":"core_rulebook","page":180},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.EZG0aAg9oxEUou5u"},{"name":"Staggering Shot","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>Putting an arrow at a foe’s feet can cause them to stumble or trip, and an experienced archer knows how to take full advantage of this, planting bolts to break an</em></span><em> </em><span class=\"fontstyle0\"><em>enemy’s stride or pinning their clothes to slow them down, making any approach extremely treacherous.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you perform a Martial Arts [Ranged] check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth) or (fire)(op)(op): </span><span class=\"fontstyle3\">Your target treats all terrain as having the Dangerous quality. This effect persists until the end of your next turn.</span></p><p><span class=\"fontstyle2\">(air) or (water)(op)(op): </span><span class=\"fontstyle3\">Your target treats all terrain as having the Entangling quality. This effect persists until the end of your next turn.</span></p>","source":{"book":"path_of_waves","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.6N5n9fweaz1CbLCu"},{"name":"Touchstone of Courage","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"shuji","rank":3,"description":"<p><span class=\"fontstyle0\"><em>Armies are rarely routed in the field; instead, most collapse when morale becomes impossible to maintain. As panic rises in the ranks, soldiers look to leaders to set an example. The character does just this, speaking to the importance of duty to bring their troops back from the edge of chaos.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may make a </span><span class=\"fontstyle2\">TN 4 Command (earth) check </span><span class=\"fontstyle3\">targeting any number of characters (or your cohort during a mass battle).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed during an intrigue, duel, or skirmish conflict, each target increases their composure by your Earth Ring. This effect persists until the end of the scene. If you succeed during a mass battle, increase your army’s discipline by your Earth Ring plus your bonus successes. This effect persists until the end of the scene.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(earth)(op)(op): </span><span class=\"fontstyle3\">During an intrigue, duel, or skirmish, each target removes strife equal to your Earth Ring.</span></p><p><span class=\"fontstyle2\">(earth)(op)(op): </span><span class=\"fontstyle3\">During a mass battle, your army removes panic equal to your Earth Ring.</span></p>","source":{"book":"core_rulebook","page":217},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.fFxQOBXLb9ol9owk","skill":"command"},{"name":"Thunderbolt Style","via":"Gunsō","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":4,"description":"<p><span class=\"fontstyle0\"><em>Hitting a target with a thrown weapon is difficult; hitting more than one target with the same throw is even harder. However, a warrior of sufficient skill can potentially harm multiple targets with a properly placed spear or ax throw, the projectile striking one foe and caroming off at an unexpected angle or causing the primary target to collapse into another. Such an unexpected tactic can catch an entire unit off guard, forcing them to spread out when staying close together would be advantageous.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make an Attack action check in which you throw your weapon, you may spend (op) as follows:</span></p><p><span class=\"fontstyle4\">(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">Choose another character at range 0–1 of your target with vigilance lower than your ranks in Fitness plus (op) spent this way. That character suffers damage equal to your weapon’s base damage. You can activate this opportunity multiple times, choosing different characters to affect each time.</span></p>","source":{"book":"children_of_the_five_winds","page":110},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.rwDHm7Q3qmjDJZRg"},{"name":"Deflective Defense","via":"Gunsō","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":3,"description":"<p><span class=\"fontstyle0\"><em>Large-enough weapons can, in a pinch, serve as shields against missile attacks. If a warrior plants their weapon in the ground and takes cover behind it with a narrow profile, even a </em></span><span class=\"fontstyle2\"><em>bisentō </em></span><span class=\"fontstyle0\"><em>makes the likelihood of a lethal hit with an arrow or dart far lower.</em></span></p><p><span class=\"fontstyle3\"><strong>Activation:</strong> </span><span class=\"fontstyle0\">As a Movement and Support action using a readied Cumbersome weapon, you may make a </span><span class=\"fontstyle3\">TN 2 Martial Arts [Melee] (earth) check</span><span class=\"fontstyle0\">.</span></p><p><span class=\"fontstyle3\"><strong>Effects:</strong> </span><span class=\"fontstyle0\">If you succeed, treat your physical resistance against attacks made by characters at range 2–6 as increased by your ranks in Fitness.\\</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle3\">(earth)(op)(op): </span><span class=\"fontstyle0\">After you defend against physical damage from an attack made by a character at range 2–6, that character suffers 2 strife.</span></p>","source":{"book":"path_of_waves","page":88},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.eC8kPJscUbiEoE7c","skill":"melee"},{"name":"Tactical Assessment","via":"Gunsō","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>Akodo’s </em></span><span class=\"fontstyle2\"><em>Leadership </em></span><span class=\"fontstyle0\"><em>and Bayushi’s </em></span><span class=\"fontstyle2\"><em>Lies </em></span><span class=\"fontstyle0\"><em>agree on a few topics, for both leaders were practical to a certain degree, even if Akodo famously scorned many of Bayushi’s methods. As the scholar Hida Fuyuko noted in her revelatory commentary on </em></span><span class=\"fontstyle2\"><em>Leadership</em></span><span class=\"fontstyle0\"><em>’s lessons for commanders on the Kaiu Wall, the most famous meeting of these two minds comes on the matter of preparation: battles are not won in the field, but in the leadup to the conflict. Even in small clashes, the warrior who better understands the terrain, the strength of their own forces, and the composition of the enemy’s troops is usually victorious.</em></span></p><p><span class=\"fontstyle3\"><strong>Activation:</strong> </span><span class=\"fontstyle2\">When you make an Initiative check, you may spend</span><span class=\"fontstyle4\"> (op) </span><span class=\"fontstyle2\">in the following way:</span></p><p><span class=\"fontstyle3\">(air)(op): </span><span class=\"fontstyle2\">Choose an enemy in the conflict. Learn one of their advantages (of their choice) and their physical or supernatural resistance (your choice).</span></p><p><span class=\"fontstyle3\">(earth)(op): </span><span class=\"fontstyle2\">Choose a character in the conflict. They do not apply any of their disadvantages to their checks until the end of their first turn.</span></p><p><span class=\"fontstyle3\">(water)(op): </span><span class=\"fontstyle2\">Choose a piece of terrain in the scene (see </span><span class=\"fontstyle3\">Terrain </span><span class=\"fontstyle2\">on page 267). Until the start of your first turn, it counts as having the Obscuring quality for Attack action checks targeting you and your allies.</span></p><p><span class=\"fontstyle3\">(fire)(op): </span><span class=\"fontstyle2\">Choose a character in the conflict and one of their advantages you know. Until the end of their first turn, they apply that advantage to all of their checks.</span></p>","source":{"book":"core_rulebook","page":178},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.TcFVNDk57aKGpLR2"},{"name":"Rallying Cry","via":"Gunsō","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"shuji","rank":3,"description":"<p><span class=\"fontstyle0\"><em>The leader roars, calling their troops to battle, and the voice of an army echoes around them as the single cry is joined by many. As one, the troops surge forward to claim victory or perish in the attempt.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may make a </span><span class=\"fontstyle2\">TN 2 Command (fire) </span><span class=\"fontstyle3\">or </span><span class=\"fontstyle2\">Performance (fire) check </span><span class=\"fontstyle3\">targeting any number of characters in the scene (or one cohort in a mass battle).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, the targets are energized and excited by your rhetoric. After </span><span class=\"fontstyle2\">Step 5: Choose Kept Dice</span><span class=\"fontstyle3\">, each target adds a kept (ring) set to an (op)(st) result. This effect persists until the end of your next turn.</span></p><h4><span class=\"fontstyle5\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(fire)(op)+: </span><span class=\"fontstyle3\">In a skirmish, each enemy in the scene suffers 1 strife per (op) spent this way.</span></p><p><span class=\"fontstyle2\">(fire)(op)+: </span><span class=\"fontstyle3\">In a mass battle, the enemy army suffers 1 panic per (op) spent this way.</span> <br style=\" font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: 2; text-align: -webkit-auto; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px; \"></p>","source":{"book":"core_rulebook","page":219},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.4Z888LVUKQoDU4n8","skill":"command,performance"},{"name":"Lead from the Front","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":3,"kind":"title_ability","rank":1,"description":"<p><span class=\"fontstyle0\">When you defeat an opponent in a clash, your cohort removes panic equal to the opponent’s glory rank.</span></p><p><span class=\"fontstyle0\">Once per round when you succeed at an Attack action check during a mass battle, your cohort removes panic equal to half of the attrition you inflict.</span></p>","source":{"book":null,"page":0},"uuid":"Compendium.l5r5e-compendia-sortilege.title-abilities-l5r-sortilege.Item.YTRyf5NAEdnGa2K1"},{"name":"Great Anvil's Measure","xp_used":3,"xp_cost":3,"in_curriculum":false,"bought_at_rank":3,"kind":"shuji","rank":2,"description":"<p><span class=\"fontstyle0\"><em>A proud leader often draws attention to themselves in battle, and a leader both proud and skilled does so to draw their enemy into attacking them—especially when the enemy would rather attack elsewhere. When the leader’s troops are properly readied, and especially when they are in a highly defensible location, such an attack against them is doomed to fail.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a check to perform a Guard action in a skirmish (see page 264 of the core rulebook) or a Reinforce action in a mass battle (see page 279 of the core rulebook), you may spend (op) as follows:</span></p><p><span class=\"fontstyle2\">(earth)(op)+ (Guard): </span><span class=\"fontstyle3\">Choose any number of characters in the scene with focus lower than or equal to your ranks in Performance plus 2 per (op) spent this way. Each chosen character must receive strife equal to your ranks in Performance to perform an Attack or Scheme action targeting any character other than you. This effect persists until the end of your next turn.</span></p><p><span class=\"fontstyle2\">(earth)(op)+ (Reinforce): </span><span class=\"fontstyle3\">Choose any number of leaders in the enemy army with focus lower than or equal to your ranks in Performance plus 2 per (op) spent this way. The enemy army receives panic equal to your ranks in Performance each time any of those leaders performs an Attack or Scheme action targeting any cohort other than yours. This effect persists until the end of your next turn.</span></p>","source":{"book":"fields_of_victory","page":100},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.F4ukKaPLuPJCCDKe"},{"name":"Improvised Assault","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":3,"kind":"kata","rank":3,"description":"<p><span class=\"fontstyle0\"><em>The character adapts something in their environment for use as an improvised weapon that suits their own fighting style. This might mean blocking hits with a chair like a shield, swinging a heavy branch like a club, or even wielding an umbrella with a swordmaster’s skill. Such improvised weapons rarely survive combat, but even if a broken sake bottle won’t hold an edge for long, a single good stab can often end a fight.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Movement and Support action, you may make a </span><span class=\"fontstyle2\">TN 2 Tactics (water) </span><span class=\"fontstyle3\">or </span><span class=\"fontstyle2\">Smithing (water) check </span><span class=\"fontstyle3\">using a readied improvised weapon.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, you may choose a Martial Arts [Melee] weapon profile for a weapon similar in shape to the improvised weapon (the GM has discretion over whether the substitution is appropriate). Treat the improvised weapon as having that profile, with its damage and deadliness reduced by 1. This effect persists until the end of the scene, at which point the improvised weapon gains the Destroyed quality.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(water)(op)(op): </span><span class=\"fontstyle3\">You may immediately perform a Strike action using the readied weapon.</span></p><p><span class=\"fontstyle2\">(water)(op)(op)(op): </span><span class=\"fontstyle3\">If you succeed, choose one of the following item qualities: Cumbersome, Razor-Edged, or Snaring. The weapon is treated as having that quality.</span></p>","source":{"book":"path_of_waves","page":87},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.pQPOCwe6xFiuPyu7","skill":"tactics,smithing"},{"name":"Iron in the Mountains Style","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":3,"kind":"kata","rank":4,"description":"<p><span class=\"fontstyle0\"><em>The bushi strikes with crushing force, breaking their enemy’s footing and knocking them to the ground with an overwhelming blow or sweeping their stance out from underneath them with a well-placed kick.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee, Ranged, or Unarmed] (Earth) check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth)(op)+: </span><span class=\"fontstyle3\">One target of your action must resist with a </span><span class=\"fontstyle2\">TN 3 Fitness check ((air) 1, (water) 4) </span><span class=\"fontstyle3\">or suffer the Prone condition and fatigue equal to their shortfall. Increase the TN of the check to resist by 1 per (op) spent this way.</span></p>","source":{"book":"core_rulebook","page":176},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.B60KpdAhSAXaNhSt"},{"name":"Iron Shell Style","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":3,"kind":"kata","rank":3,"description":"<p><span class=\"fontstyle0\"><em>To defend against a single, predictable blow, a warrior can dig in, rooting themself and dispersing the force as it comes. Such a complete defense is exhausting to maintain, but it can keep a fighter on their feet when they otherwise would surely have fallen.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you perform a Guard action, if you have not moved any range bands this turn, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth) or (void)(op)+: </span><span class=\"fontstyle3\">Choose one character you can perceive per (op) spent this way. The next time you defend against physical damage from that character, your fatigue cannot be increased to a value greater than your endurance. This effect persists until the end of your next turn.</span></p>","source":{"book":"path_of_waves","page":86},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.2gfStxWLxFx4GZO9"},{"name":"Wanderer's Resolve","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":3,"kind":"shuji","rank":1,"description":"<p><span class=\"fontstyle0\"><em>A samurai with a lord can find resolve in the loyalty they feel, but a samurai with no lord has no easy wellspring from which to draw resolve. This hardship and isolation, however, can lead a rōnin</em></span><em> to discover a certainty</em><span class=\"fontstyle0\"><em> all their own, for if they do not act, no one else will. The lives of their friends—of those who depend on them—rest solely in their hands.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">Once per scene as a Support action, if you are in a Void stance, you may focus on protecting what is important to you.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">You remove 3 fatigue and 3 strife, plus 3 fatigue and 3 strife for each Compromised or Incapacitated character in the scene with whom you share a bond (see </span><span class=\"fontstyle2\">Bonds</span><span class=\"fontstyle3\">, on page 187).</span></p>","source":{"book":"path_of_waves","page":95},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.FpyARQtMdf6V8HSY"}],"peculiarities":[{"name":"Light Sleeper","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"water","types":"Physical","description":"<p><span class=\"fontstyle0\"><em>“You see these scars?” she asked. He nodded respectfully at the Hiruma. It looked like someone had run a rake down her face—then repeated the action several times.</em></span></p><p><span class=\"fontstyle0\"><em>“This is what you get when you dare slumber here. Everyone else died that night.” She closed her eyes for a moment, then opened them abruptly, startling him. “You rest your guard, you die.” She looked closely at him. “You learn to stay awake, even when you sleep. Or you join the rest of my old patrol.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Light Sleeper distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You rouse from sleep very easily, a trick considered essential in hostile territory. You are trained to awaken before danger arrives, sleep with your weapons ready, and pretend to be in a deep sleep to lure enemies closer. You can go from a deep sleep to fully alert and fighting in the blink of an eye.</span></p></li><li><p><span class=\"fontstyle0\">- When performing a check that calls on rapidly recovering from sleep (such as a Survival (water) check to detect a threatening sound while dozing or a Fitness (water) check to react even when someone else is standing watch), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"shadowlands","page":96},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.ZtoejR7hmjZ0aE8k"},{"name":"Encompassing Duty","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"earth","types":"Mental","description":"<p><em>“I will lay down my life for my family. Nothing will stand in the way of that.”</em></p><p><em>– Aina, Ashigaru of the Lion</em></p><p></p><p>The following apply to a character with the Encompassing Duty adversity:</p><ul><li><p>- You have a duty to something: your family, a friend, a cause, or some other person or ideal. This duty should manifest into at least one discernible goal, one you can work out with the GM. A goal may be to provide for your family, rescue a friend, or achieve a similar aim. You have a difficult time relaxing or focusing on tasks that do not somehow advance your goal, and this may manifest in several ways, including frustration, anger, worry, or nervousness. </p></li><li><p>- Whenever you make a check related to overcoming something that could hinder you in achieving your duty (such as a Meditation (earth) check to keep a cool head in an ambush or a Courtesy (earth) check to reason with a stubborn shopkeeper), you must choose and reroll two dice containing (su) or (ex) . After resolving the check, if you failed, you gain 1 Void point.</p></li></ul>","source":{"book":"path_of_waves","page":72},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.TP83fjX8gnxELunG"},{"name":"Travel","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"water","types":"Mental, Physical","description":"<p><span class=\"fontstyle0\"><em>The old man sat heavily on the stool outside the constabulary office. He removed his straw hat, wiped his brow with his sleeve, and returned the hat to his head. His eyes, shaded by the wide brim, looked out at Yūka. The young girl smiled.</em></span></p><p><span class=\"fontstyle0\"><em>“Young lady, I have been from one side of Rokugan to the other—from Khanbulak to the Islands of Silk and Spice—and I have seen amazing sights. I will tell you this: in all my travels, I have become convinced of three things.” He counted them off on gnarled fingers. “All crows are black, it always rains when you don’t want it to, and Rokugan’s greatest treasure—a prize without equal—is its people.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Travel passion:</span></p><ul><li><p><span class=\"fontstyle3\">- You are not unsettled by foreign customs, and you can comfortably fit in even in strange environments.</span></p></li><li><p><span class=\"fontstyle3\">- After performing a check to travel to a new location or interact with a novel thing (such as a Survival (water) check to try to identify a new plant, animal, or phenomenon, or a Seafaring (water) check to travel by boat), you remove 3 strife.</span></p></li></ul>","source":{"book":"core_rulebook","page":115},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.7keAIKn0N8wjEsGa"},{"name":"Battle Trauma","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"fire","types":"Mental, Physical","description":"<p><em>The thousand cuts I have borne<br>And the thousand I have delivered<br>Paint my dreams in red<br>Broad brushstrokes to draw pictures<br>I cannot put to paper.<br>Do my ears ring from old age<br>Or is that steel’s song and the warrior’s cry<br>Gone so long ago<br>But never gone?</em></p><p><strong>Effects:</strong> The following apply to a character with the Battle Trauma anxiety:</p><ul><li><p>-  At the start of a duel, skirmish, or mass battle, your hands shake, your body tenses up, or your mind might even lock down. You can act normally, but your unsettled state is obvious to everyone around you, and others may try to exploit it.</p></li><li><p>-  After performing a check related to battle (such as a Martial Arts [Melee] (fire) check to strike down a foe or a Tactics (fire) check to generate initiative), you receive 3 strife. (Your GM can choose not to inflict this strife after the you have taken a few turns and thematically overcome your trauma.) If this is the first time this has occurred this scene, gain 1 Void point.</p></li></ul>","source":{"book":"core_rulebook","page":131},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.jlSq86lbglLrHXp8"},{"name":"Paragon of Courage","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"fire","types":"Mental, Virtue","description":"<p><span class=\"fontstyle0\"><em>“The heroes of myth—even the ones who were not of divine blood—did not live as humans do. It is impossible to embody an ideal without surpassing some part of your own humanity.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Paragon of Courage distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You believe utterly in Courage, and others instinctively discern that your actions are genuine when you act in accordance with it.</span></p></li><li><p><span class=\"fontstyle3\">- When performing a check for which you need to convince others of, or leverage your faith in, Courage (such as a Performance check to recount a tale that impresses its importance upon others or a Martial Arts [Melee] check to take up arms for this cause), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"core_rulebook","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.trppadBbshGjbSP2"}],"titles":[{"name":"Gunsō","xp_used":24,"xp_cost":24,"in_curriculum":false,"bought_at_rank":3,"description":"<p><span class=\"fontstyle0\">While the vast majority of soldiers in a Rokugani army are ashigaru and conscripts, many samurai are called to military service, either in the armies of their own clan or in the Imperial Legions. When samurai do take to the field, they often these serve in leadership positions. While each lord's forces have their own structure and character, common titles are used throughout Rokugan to indicate similar levels of authority. When a lord gathers a large force for battle, they may nominate one or more gunsō to command the kashira who lead individual units.</span></p><p><span class=\"fontstyle0\">A gunsō is responsible for all aspects of battle readiness for the troops under their command, including the troops’ training, discipline, and equipment. When battle begins, gunsō direct their troops in accordance with commands from their superiors, meaning they have to maintain good awareness not only of their own unit but also of the broader battle unfolding around them. Perhaps most importantly, gunsō are expected to display conspicuous leadership during battle, leading their troops from the front and rallying their soldiers, keeping them in the fight even as losses mount and their morale begins to waver.</span></p><p><span class=\"fontstyle2\"><strong>Assigned By:</strong> </span><span class=\"fontstyle0\">A daimyō may assign a samurai a rank within their military forces, and samurai serving within the military rank structure may be promoted by a superior officer.</span></p><p><span class=\"fontstyle2\"><strong>Status Award:</strong> </span><span class=\"fontstyle0\">+5 (to a minimum of 20)</span></p><p><span class=\"fontstyle2\"><strong>Title Ability:</strong> Lead from the Front</span></p><h2>Curriculum</h2><table><tbody><tr><td><p>Martial Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Command</p></td><td><p>Skill</p></td></tr><tr><td><p>Government</p></td><td><p>Skill</p></td></tr><tr><td><p><a class=\"compendium-link\" data-pack=\"l5r5e.core-techniques-kata\">(kata) Rank 1-4 Kata</a></p></td><td><p>Tech. Grp.</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-shuji.Item.L5RCoreShu000020\" data-pack=\"l5r5e.core-techniques-shuji\" data-type=\"Item\" data-id=\"L5RCoreShu000020\">(shuji) Rallying Cry</a> (prereq)</p></td><td><p>Technique</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-shuji.Item.L5RCoreShu000026\" data-pack=\"l5r5e.core-techniques-shuji\" data-type=\"Item\" data-id=\"L5RCoreShu000026\">(shuji) Stirring the Embers</a> (prereq)</p></td><td><p>Technique</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-shuji.Item.L5RCoreShu000011\" data-pack=\"l5r5e.core-techniques-shuji\" data-type=\"Item\" data-id=\"L5RCoreShu000011\">(shuji) Touchstone of Courage</a> (prereq)</p></td><td><p>Technique</p></td></tr></tbody></table>","source":{"book":"emerald_empire","page":250},"uuid":"Compendium.l5r5e-compendia-sortilege.titles-l5r-sortilege.Item.2R7nNp7NWNLkVs5j"}],"bonds":[],"signature_scrolls":[],"gear":[{"name":"Club","quantity":1,"description":"<p><span class=\"fontstyle0\">The humble club is perhaps the oldest weapon in Rokugan—at least among humans. Often little more than a length of stout wood or shaped stone, a club can be fashioned with available materials by nearly anyone. While a club can certainly be used to kill, doing so takes some work on the part of the wielder</span>.</p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.ElFJfEcGvWe6A5yU","damage":5,"deadliness":2,"range":"0-1","grip_2":"Damage +1","skill":"melee","category":"Blunt Weapons","rarity":"1","zeni":"1 bu","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Katana","quantity":1,"description":"<p><span class=\"fontstyle0\">As much a work of art as it is a weapon, the katana is perhaps the most revered weapon in Rokugan. It has an elegant, slightly curved blade between three and four feet long, made of steel that is specially folded during its creation. This unique forging style ensures that the inner part of the blade remains springy and soft while the outside is as hard as tempered steel. Each sword likely has a history and legacy, and it is a constant reminder of the weight that destiny has placed upon its bearer’s shoulders as a samurai of Rokugan</span>.</p>","source":{"book":"core_rulebook","page":232},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.BhKwwnN5UHI5rZpp","damage":4,"deadliness":5,"range":"1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"20 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Knife","quantity":1,"description":"<p><span class=\"fontstyle0\">Knives come in a dizzying array of types and styles, from the familiar crudely constructed knife in a peasant’s kitchen to the deadly combat knives samurai take into battle. Those particularly designed for combat—like the aiguchi—are often equipped with small hand guards to make them more useful in the field.</span></p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.n8xA05Fb9WpXg3oo","damage":2,"deadliness":4,"range":"0","grip_2":"Deadliness +2","skill":"melee","category":"Hand Weapons","rarity":"1","zeni":"1 koku","properties":[{"id":"L5RCorePro000001","name":"Razor-Edged"},{"id":"L5RCorePro000005","name":"Concealable"},{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Tetsubō","quantity":1,"description":"<p><span class=\"fontstyle0\">Long and narrow, a tetsubō can be as tall as a human and normally is constructed of iron or hardwood. Above its grip, a tetsubō is covered in steel, iron, or even jade spikes or studs that add to the weapon’s lethality and crush armor or plated carapace with ease.</span></p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.CW6h0NSzTEhimQXw","damage":7,"deadliness":3,"range":"1-2","grip_1":"N/A","skill":"melee","category":"Blunt Weapons","rarity":"5","zeni":"20 koku","properties":[{"id":"L5RCorePro000006","name":"Cumbersome"},{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Wakizashi","quantity":1,"description":"<p><span class=\"fontstyle0\">Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</span></p>","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Kamayari","quantity":1,"description":"<p><span class=\"fontstyle0\">A </span><span class=\"fontstyle2\">kamayari </span><span class=\"fontstyle0\">is a spear with a hooked protrusion on one or both sides of the blade, similar to a ji. While the hook’s most obvious applications are blocking attacks and dragging foes off horseback, it also has practical noncombat applications. A shinobi might swing from a sturdy tree limb using the hook or might use it to climb a high fence. If the spear shaft has holes in it, the shinobi can use the shaft to measure distances or can slot bars into the holes to use it as a ladder. Finally, the hook is useful for carrying items on long walks.</span></p>","source":{"book":"court_of_stones","page":110},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.PsmRwhHYBz0daKi5","damage":4,"deadliness":3,"range":"2","grip_1":"N/A","skill":"melee","category":"Specialist Weapons","rarity":"7","zeni":"8 koku","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000007","name":"Snaring"}]},{"name":"Lacquered Armor","quantity":1,"description":"<p><span class=\"fontstyle0\">Heavier than ashigaru armor, lacquered armor is worn by samurai who desire a good mix of protection and grandeur, and is just at home at war as at a martial ceremony. These suits are made of thick leather or steel plates stitched or riveted to a leather backing. They protect the torso, head, upper arms, and groin, and the legs above the knee. They can also include a helmet and mask, though these are not considered integral.</span></p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.sPKkavq6O0SoxiPj","armor":{"physical":4,"supernatural":0},"rarity":"6","zeni":"25 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000006","name":"Cumbersome"},{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Traveling Clothes","quantity":1,"description":"<p><span class=\"fontstyle0\">Traveling clothes ordinarily consist of roughspun garments designed to resist wear and tear. They can be anything from robes to a kimono or jacket and leggings and are often accentuated with a hat or cloak</span>.</p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.zcsgspz4VluSMeI0","armor":{"physical":2,"supernatural":0},"rarity":"2","zeni":"2 bu","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000012","name":"Mundane"},{"id":"L5RCorePro000016","name":"Subtle"}]},{"name":"Traveling pack","quantity":1,"description":"<p><span class=\"fontstyle0\">Blanket, bowl, chopsticks, four days of travel rations, flint and tinder, and any three other items of the player’s choice that are rarity 4 or lower.</span></p>","source":{"book":"core_rulebook","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.Rex7fGo6R1KuUhQJ","rarity":"1","zeni":"10 koku","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Kubi Bukuro","quantity":1,"description":"<p>These are simple net bags used to carry the severed head of an enemy, which is considered both a trophy and a good omen. Lion Clan samurai use them to carry their trophies without touching dead flesh, but the Kuni family uses them for collecting samples of Shadowlands creatures for study.</p>","source":{"book":"core_rulebook","page":242},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.6J25vJx1tVirgXf1","rarity":"2","zeni":"2 zeni","properties":[{"id":"L5RCorePro000011","name":"Wargear"}]}]},{"xp":165,"label":"Gunsō, Rank 5","rank":5,"school":"Hida Defender School","foundry_id":"1zj26dnVkxVx8cjc","rings":{"air":2,"earth":4,"fire":2,"water":3,"void":3},"skills":{"artisan":{"aesthetics":0,"composition":1,"design":0,"smithing":0},"martial":{"fitness":3,"melee":3,"ranged":2,"unarmed":1,"meditation":2,"tactics":2},"scholar":{"culture":0,"government":3,"medicine":0,"sentiment":0,"theology":0},"social":{"command":4,"courtesy":1,"games":0,"performance":0},"trade":{"commerce":0,"labor":2,"seafaring":1,"skulduggery":1,"survival":2}},"social":{"honor":45,"glory":44,"status":30,"ninjo":"Longs to travel Rokugan, or possibly even beyond.","giri":"Hiruma Nobuyasu is their lord. They insist that she command her unit, defending the Kaiu Wall.","bushido_tenets":{"paramount":"Courage","less_significant":"Sincerity"}},"derived":{"endurance":12,"composure":14,"focus":4,"vigilance":3,"void_points":3},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[{"label":"Martial Arts [Ranged] +1 (0 -> 1)","type":"skill","skill":"ranged","ring":"void","at_rank":1,"xp":2,"in_curriculum":true},{"label":"Martial Arts [Melee] +1 (1 -> 2)","type":"skill","skill":"melee","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Martial Arts [Unarmed] +1 (0 -> 1)","type":"skill","skill":"unarmed","ring":"void","at_rank":1,"xp":2,"in_curriculum":true},{"label":"Martial Arts [Ranged] +1 (1 -> 2)","type":"skill","skill":"ranged","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Command +1 (1 -> 2)","type":"skill","skill":"command","ring":"void","at_rank":2,"xp":4,"in_curriculum":true},{"label":"Void +1 (2 -> 3)","type":"ring","ring":"void","at_rank":2,"xp":9,"in_curriculum":false},{"label":"Labor +1 (0 -> 1)","type":"skill","skill":"labor","ring":"void","at_rank":2,"xp":2,"in_curriculum":true},{"label":"Command +1 (2 -> 3)","type":"skill","skill":"command","ring":"void","at_rank":2,"xp":6,"in_curriculum":true},{"label":"Composition +1 (0 -> 1)","type":"skill","skill":"composition","ring":"void","at_rank":2,"xp":2,"in_curriculum":false},{"label":"Command +1 (4 -> 5)","type":"skill","skill":"command","ring":"void","at_rank":1,"xp":10,"in_curriculum":true,"via":"Gunsō"},{"label":"Government +1 (0 -> 1)","type":"skill","skill":"government","ring":"void","at_rank":1,"xp":2,"in_curriculum":true,"via":"Gunsō"},{"label":"Fitness +1 (2 -> 3)","type":"skill","skill":"fitness","ring":"void","at_rank":3,"xp":6,"in_curriculum":true},{"label":"Seafaring +1 (0 -> 1)","type":"skill","skill":"seafaring","ring":"void","at_rank":3,"xp":2,"in_curriculum":true},{"label":"Labor +1 (1 -> 2)","type":"skill","skill":"labor","ring":"void","at_rank":3,"xp":4,"in_curriculum":true},{"label":"Martial Arts [Melee] +1 (2 -> 3)","type":"skill","skill":"melee","ring":"void","at_rank":3,"xp":6,"in_curriculum":true},{"label":"Earth +1 (3 -> 4)","type":"ring","ring":"earth","at_rank":4,"xp":12,"in_curriculum":false},{"label":"Water +1 (1 -> 2)","type":"ring","ring":"water","at_rank":4,"xp":6,"in_curriculum":false},{"label":"Water +1 (2 -> 3)","type":"ring","ring":"water","at_rank":4,"xp":9,"in_curriculum":false},{"label":"Government +1 (1 -> 2)","type":"skill","skill":"government","ring":"void","at_rank":4,"xp":4,"in_curriculum":true},{"label":"Meditation +1 (0 -> 1)","type":"skill","skill":"meditation","ring":"void","at_rank":4,"xp":2,"in_curriculum":true},{"label":"Meditation +1 (1 -> 2)","type":"skill","skill":"meditation","ring":"void","at_rank":4,"xp":4,"in_curriculum":true},{"label":"Government +1 (2 -> 3)","type":"skill","skill":"government","ring":"void","at_rank":4,"xp":6,"in_curriculum":true}],"techniques":[{"name":"Striking as Earth","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"kata","rank":1,"description":"<p><span class=\"fontstyle0\"><em>After striking, the bushi roots themself to the ground, hunkering down to make sure their armor takes the brunt of a hit or raising a weapon in a warding position where it can deflect harm without being damaged.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee, Ranged, or Unarmed] (earth) check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth)(op)+: </span><span class=\"fontstyle3\">Treat your physical resistance as 1 higher per </span><span class=\"fontstyle4\">(op) </span><span class=\"fontstyle3\">spent this way until the beginning of your next turn.</span></p>","source":{"book":"core_rulebook","page":178},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.aKTfAZXbHo77kHOq"},{"name":"Lord Hida’s Grip (Crab)","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>The Kami Hida, patron of the Crab Clan, was a legendary slayer of monsters. He beheaded the massive demon that once menaced the rose-marble palace, and ripped out one skull of the two-headed Kabuto no Oni and crushed the other head with it. However, Hida was no mere brute: he was cunning, killing monsters by exploiting their weaknesses. Warriors of the Crab Clan train in similar techniques. They turn their foes' great weight against them by pinning or strategically damaging specific body parts.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As an Attack action, you may make a </span><span class=\"fontstyle2\">Fitness (void) check </span><span class=\"fontstyle3\">targeting one creature of silhouette 3 or larger at range 0–1. The TN of the check is equal to the silhouette of the target (to a minimum of 1).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, your target suffers the Immobilized condition. If you succeed, you count as granting assistance (see page 26) to all characters who perform Attack actions against your target. This effect persists until the beginning of your next turn.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(void)(op): </span><span class=\"fontstyle3\">Your target must resist with a </span><span class=\"fontstyle2\">Fitness check </span><span class=\"fontstyle3\">or suffer physical damage equal to its silhouette, ignoring its resistance, and the Prone condition. The TN of this check is equal to your school rank.</span></p>","source":{"book":"core_rulebook","page":176},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.ERExWdY04GNvu3p0","skill":"fitness"},{"name":"Way of the Crab","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p><span class=\"fontstyle0\">Ignore the Cumbersome quality of armor you wear.</span></p><p><span class=\"fontstyle0\">Once per round, before making a check to resist a critical strike, you may reduce the severity of that critical strike by the physical resistance of your armor plus your school rank (to a minimum of 0).</span></p>","source":{"book":"core_rulebook","page":57},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.7LHxYqmpqMUETLEq"},{"name":"Appreciate the Scenery","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<p><span class=\"fontstyle0\"><em>In many lands, including Rokugan, the beauty of the natural world inspires art, poetry, and other works of note, even (or perhaps especially) when it is stark and dangerous. When on a long and perilous journey into foreign lands where deadly intrigues surely await, finding beauty in the rougher parts of the world can be a much-needed source of solace.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Support action check targeting another character, if you and the character you are targeting are in Dangerous, Entangling, Hallowed, Imbalanced, or Obscuring terrain, you may spend (op) as follows:</span></p><p><span class=\"fontstyle2\">(earth) or</span><span class=\"fontstyle4\"> (water)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">You and your target each remove strife equal to your ranks in Composition.</span></p><p><span class=\"fontstyle2\">(air) or (fire)</span><span class=\"fontstyle4\">(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">You and your target gain the Emboldened condition (see page 133).</span></p><p><span class=\"fontstyle2\">(void)(op): </span><span class=\"fontstyle3\">Your and your target gain the Centered condition (see page 133).</span></p>","source":{"book":"children_of_the_five_winds","page":116},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.gbUpw4ife9RdWbK9"},{"name":"Honest Assessment","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<p><span class=\"fontstyle0\"><em>Honesty is a virtue of Bushidō, but direct honesty is often seen as rudeness among the samurai—instead, one is expected to find a polite way to imply one’s meaning to spare the feelings of the other involved. As a result, directness can be something of a rare and valuable commodity.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may make a </span><span class=\"fontstyle2\">TN 2 Courtesy (earth) check </span><span class=\"fontstyle3\">to appraise the weaknesses of a character.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, choose one of the target’s known disadvantages. The target does not apply that disadvantage to their checks until the end of the scene.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(earth)(op)+: </span><span class=\"fontstyle3\">Choose one additional disadvantage per (op) spent this way.</span></p><p><span class=\"fontstyle5\">(earth)(op)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">Reduce the TN of the target’s next skill check using the ring the disadvantage is attached to by 2.</span></p>","source":{"book":"core_rulebook","page":216},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.t427qRaOh42dfbVM","skill":"courtesy"},{"name":"Rushing Avalanche Style","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>When adopting this style, the bushi strikes with reckless abandon using a heavy armament. Thanks to the sheer weight of their weapon and the ferocity of their strikes, even a glancing blow can cause serious harm, and a telling blow usually ends the battle.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee] check using a blunt weapon, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(op): </span><span class=\"fontstyle3\">If you fail with a shortfall of two or less, your target suffers physical damage equal to your ranks in Fitness.</span></p><p><span class=\"fontstyle2\">(op): </span><span class=\"fontstyle3\">If you succeed and your target is Prone, increase the damage you deal by your ranks in Fitness.</span></p>","source":{"book":"core_rulebook","page":180},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.EZG0aAg9oxEUou5u"},{"name":"Staggering Shot","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>Putting an arrow at a foe’s feet can cause them to stumble or trip, and an experienced archer knows how to take full advantage of this, planting bolts to break an</em></span><em> </em><span class=\"fontstyle0\"><em>enemy’s stride or pinning their clothes to slow them down, making any approach extremely treacherous.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you perform a Martial Arts [Ranged] check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth) or (fire)(op)(op): </span><span class=\"fontstyle3\">Your target treats all terrain as having the Dangerous quality. This effect persists until the end of your next turn.</span></p><p><span class=\"fontstyle2\">(air) or (water)(op)(op): </span><span class=\"fontstyle3\">Your target treats all terrain as having the Entangling quality. This effect persists until the end of your next turn.</span></p>","source":{"book":"path_of_waves","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.6N5n9fweaz1CbLCu"},{"name":"Touchstone of Courage","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"shuji","rank":3,"description":"<p><span class=\"fontstyle0\"><em>Armies are rarely routed in the field; instead, most collapse when morale becomes impossible to maintain. As panic rises in the ranks, soldiers look to leaders to set an example. The character does just this, speaking to the importance of duty to bring their troops back from the edge of chaos.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may make a </span><span class=\"fontstyle2\">TN 4 Command (earth) check </span><span class=\"fontstyle3\">targeting any number of characters (or your cohort during a mass battle).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed during an intrigue, duel, or skirmish conflict, each target increases their composure by your Earth Ring. This effect persists until the end of the scene. If you succeed during a mass battle, increase your army’s discipline by your Earth Ring plus your bonus successes. This effect persists until the end of the scene.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(earth)(op)(op): </span><span class=\"fontstyle3\">During an intrigue, duel, or skirmish, each target removes strife equal to your Earth Ring.</span></p><p><span class=\"fontstyle2\">(earth)(op)(op): </span><span class=\"fontstyle3\">During a mass battle, your army removes panic equal to your Earth Ring.</span></p>","source":{"book":"core_rulebook","page":217},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.fFxQOBXLb9ol9owk","skill":"command"},{"name":"Thunderbolt Style","via":"Gunsō","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":4,"description":"<p><span class=\"fontstyle0\"><em>Hitting a target with a thrown weapon is difficult; hitting more than one target with the same throw is even harder. However, a warrior of sufficient skill can potentially harm multiple targets with a properly placed spear or ax throw, the projectile striking one foe and caroming off at an unexpected angle or causing the primary target to collapse into another. Such an unexpected tactic can catch an entire unit off guard, forcing them to spread out when staying close together would be advantageous.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make an Attack action check in which you throw your weapon, you may spend (op) as follows:</span></p><p><span class=\"fontstyle4\">(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">Choose another character at range 0–1 of your target with vigilance lower than your ranks in Fitness plus (op) spent this way. That character suffers damage equal to your weapon’s base damage. You can activate this opportunity multiple times, choosing different characters to affect each time.</span></p>","source":{"book":"children_of_the_five_winds","page":110},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.rwDHm7Q3qmjDJZRg"},{"name":"Deflective Defense","via":"Gunsō","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":3,"description":"<p><span class=\"fontstyle0\"><em>Large-enough weapons can, in a pinch, serve as shields against missile attacks. If a warrior plants their weapon in the ground and takes cover behind it with a narrow profile, even a </em></span><span class=\"fontstyle2\"><em>bisentō </em></span><span class=\"fontstyle0\"><em>makes the likelihood of a lethal hit with an arrow or dart far lower.</em></span></p><p><span class=\"fontstyle3\"><strong>Activation:</strong> </span><span class=\"fontstyle0\">As a Movement and Support action using a readied Cumbersome weapon, you may make a </span><span class=\"fontstyle3\">TN 2 Martial Arts [Melee] (earth) check</span><span class=\"fontstyle0\">.</span></p><p><span class=\"fontstyle3\"><strong>Effects:</strong> </span><span class=\"fontstyle0\">If you succeed, treat your physical resistance against attacks made by characters at range 2–6 as increased by your ranks in Fitness.\\</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle3\">(earth)(op)(op): </span><span class=\"fontstyle0\">After you defend against physical damage from an attack made by a character at range 2–6, that character suffers 2 strife.</span></p>","source":{"book":"path_of_waves","page":88},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.eC8kPJscUbiEoE7c","skill":"melee"},{"name":"Tactical Assessment","via":"Gunsō","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>Akodo’s </em></span><span class=\"fontstyle2\"><em>Leadership </em></span><span class=\"fontstyle0\"><em>and Bayushi’s </em></span><span class=\"fontstyle2\"><em>Lies </em></span><span class=\"fontstyle0\"><em>agree on a few topics, for both leaders were practical to a certain degree, even if Akodo famously scorned many of Bayushi’s methods. As the scholar Hida Fuyuko noted in her revelatory commentary on </em></span><span class=\"fontstyle2\"><em>Leadership</em></span><span class=\"fontstyle0\"><em>’s lessons for commanders on the Kaiu Wall, the most famous meeting of these two minds comes on the matter of preparation: battles are not won in the field, but in the leadup to the conflict. Even in small clashes, the warrior who better understands the terrain, the strength of their own forces, and the composition of the enemy’s troops is usually victorious.</em></span></p><p><span class=\"fontstyle3\"><strong>Activation:</strong> </span><span class=\"fontstyle2\">When you make an Initiative check, you may spend</span><span class=\"fontstyle4\"> (op) </span><span class=\"fontstyle2\">in the following way:</span></p><p><span class=\"fontstyle3\">(air)(op): </span><span class=\"fontstyle2\">Choose an enemy in the conflict. Learn one of their advantages (of their choice) and their physical or supernatural resistance (your choice).</span></p><p><span class=\"fontstyle3\">(earth)(op): </span><span class=\"fontstyle2\">Choose a character in the conflict. They do not apply any of their disadvantages to their checks until the end of their first turn.</span></p><p><span class=\"fontstyle3\">(water)(op): </span><span class=\"fontstyle2\">Choose a piece of terrain in the scene (see </span><span class=\"fontstyle3\">Terrain </span><span class=\"fontstyle2\">on page 267). Until the start of your first turn, it counts as having the Obscuring quality for Attack action checks targeting you and your allies.</span></p><p><span class=\"fontstyle3\">(fire)(op): </span><span class=\"fontstyle2\">Choose a character in the conflict and one of their advantages you know. Until the end of their first turn, they apply that advantage to all of their checks.</span></p>","source":{"book":"core_rulebook","page":178},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.TcFVNDk57aKGpLR2"},{"name":"Rallying Cry","via":"Gunsō","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"shuji","rank":3,"description":"<p><span class=\"fontstyle0\"><em>The leader roars, calling their troops to battle, and the voice of an army echoes around them as the single cry is joined by many. As one, the troops surge forward to claim victory or perish in the attempt.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may make a </span><span class=\"fontstyle2\">TN 2 Command (fire) </span><span class=\"fontstyle3\">or </span><span class=\"fontstyle2\">Performance (fire) check </span><span class=\"fontstyle3\">targeting any number of characters in the scene (or one cohort in a mass battle).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, the targets are energized and excited by your rhetoric. After </span><span class=\"fontstyle2\">Step 5: Choose Kept Dice</span><span class=\"fontstyle3\">, each target adds a kept (ring) set to an (op)(st) result. This effect persists until the end of your next turn.</span></p><h4><span class=\"fontstyle5\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(fire)(op)+: </span><span class=\"fontstyle3\">In a skirmish, each enemy in the scene suffers 1 strife per (op) spent this way.</span></p><p><span class=\"fontstyle2\">(fire)(op)+: </span><span class=\"fontstyle3\">In a mass battle, the enemy army suffers 1 panic per (op) spent this way.</span> <br style=\" font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: 2; text-align: -webkit-auto; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px; \"></p>","source":{"book":"core_rulebook","page":219},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.4Z888LVUKQoDU4n8","skill":"command,performance"},{"name":"Lead from the Front","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":3,"kind":"title_ability","rank":1,"description":"<p><span class=\"fontstyle0\">When you defeat an opponent in a clash, your cohort removes panic equal to the opponent’s glory rank.</span></p><p><span class=\"fontstyle0\">Once per round when you succeed at an Attack action check during a mass battle, your cohort removes panic equal to half of the attrition you inflict.</span></p>","source":{"book":null,"page":0},"uuid":"Compendium.l5r5e-compendia-sortilege.title-abilities-l5r-sortilege.Item.YTRyf5NAEdnGa2K1"},{"name":"Great Anvil's Measure","xp_used":3,"xp_cost":3,"in_curriculum":false,"bought_at_rank":3,"kind":"shuji","rank":2,"description":"<p><span class=\"fontstyle0\"><em>A proud leader often draws attention to themselves in battle, and a leader both proud and skilled does so to draw their enemy into attacking them—especially when the enemy would rather attack elsewhere. When the leader’s troops are properly readied, and especially when they are in a highly defensible location, such an attack against them is doomed to fail.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a check to perform a Guard action in a skirmish (see page 264 of the core rulebook) or a Reinforce action in a mass battle (see page 279 of the core rulebook), you may spend (op) as follows:</span></p><p><span class=\"fontstyle2\">(earth)(op)+ (Guard): </span><span class=\"fontstyle3\">Choose any number of characters in the scene with focus lower than or equal to your ranks in Performance plus 2 per (op) spent this way. Each chosen character must receive strife equal to your ranks in Performance to perform an Attack or Scheme action targeting any character other than you. This effect persists until the end of your next turn.</span></p><p><span class=\"fontstyle2\">(earth)(op)+ (Reinforce): </span><span class=\"fontstyle3\">Choose any number of leaders in the enemy army with focus lower than or equal to your ranks in Performance plus 2 per (op) spent this way. The enemy army receives panic equal to your ranks in Performance each time any of those leaders performs an Attack or Scheme action targeting any cohort other than yours. This effect persists until the end of your next turn.</span></p>","source":{"book":"fields_of_victory","page":100},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.F4ukKaPLuPJCCDKe"},{"name":"Improvised Assault","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":3,"kind":"kata","rank":3,"description":"<p><span class=\"fontstyle0\"><em>The character adapts something in their environment for use as an improvised weapon that suits their own fighting style. This might mean blocking hits with a chair like a shield, swinging a heavy branch like a club, or even wielding an umbrella with a swordmaster’s skill. Such improvised weapons rarely survive combat, but even if a broken sake bottle won’t hold an edge for long, a single good stab can often end a fight.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Movement and Support action, you may make a </span><span class=\"fontstyle2\">TN 2 Tactics (water) </span><span class=\"fontstyle3\">or </span><span class=\"fontstyle2\">Smithing (water) check </span><span class=\"fontstyle3\">using a readied improvised weapon.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, you may choose a Martial Arts [Melee] weapon profile for a weapon similar in shape to the improvised weapon (the GM has discretion over whether the substitution is appropriate). Treat the improvised weapon as having that profile, with its damage and deadliness reduced by 1. This effect persists until the end of the scene, at which point the improvised weapon gains the Destroyed quality.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(water)(op)(op): </span><span class=\"fontstyle3\">You may immediately perform a Strike action using the readied weapon.</span></p><p><span class=\"fontstyle2\">(water)(op)(op)(op): </span><span class=\"fontstyle3\">If you succeed, choose one of the following item qualities: Cumbersome, Razor-Edged, or Snaring. The weapon is treated as having that quality.</span></p>","source":{"book":"path_of_waves","page":87},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.pQPOCwe6xFiuPyu7","skill":"tactics,smithing"},{"name":"Iron in the Mountains Style","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":3,"kind":"kata","rank":4,"description":"<p><span class=\"fontstyle0\"><em>The bushi strikes with crushing force, breaking their enemy’s footing and knocking them to the ground with an overwhelming blow or sweeping their stance out from underneath them with a well-placed kick.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee, Ranged, or Unarmed] (Earth) check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth)(op)+: </span><span class=\"fontstyle3\">One target of your action must resist with a </span><span class=\"fontstyle2\">TN 3 Fitness check ((air) 1, (water) 4) </span><span class=\"fontstyle3\">or suffer the Prone condition and fatigue equal to their shortfall. Increase the TN of the check to resist by 1 per (op) spent this way.</span></p>","source":{"book":"core_rulebook","page":176},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.B60KpdAhSAXaNhSt"},{"name":"Iron Shell Style","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":3,"kind":"kata","rank":3,"description":"<p><span class=\"fontstyle0\"><em>To defend against a single, predictable blow, a warrior can dig in, rooting themself and dispersing the force as it comes. Such a complete defense is exhausting to maintain, but it can keep a fighter on their feet when they otherwise would surely have fallen.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you perform a Guard action, if you have not moved any range bands this turn, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth) or (void)(op)+: </span><span class=\"fontstyle3\">Choose one character you can perceive per (op) spent this way. The next time you defend against physical damage from that character, your fatigue cannot be increased to a value greater than your endurance. This effect persists until the end of your next turn.</span></p>","source":{"book":"path_of_waves","page":86},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.2gfStxWLxFx4GZO9"},{"name":"Wanderer's Resolve","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":3,"kind":"shuji","rank":1,"description":"<p><span class=\"fontstyle0\"><em>A samurai with a lord can find resolve in the loyalty they feel, but a samurai with no lord has no easy wellspring from which to draw resolve. This hardship and isolation, however, can lead a rōnin</em></span><em> to discover a certainty</em><span class=\"fontstyle0\"><em> all their own, for if they do not act, no one else will. The lives of their friends—of those who depend on them—rest solely in their hands.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">Once per scene as a Support action, if you are in a Void stance, you may focus on protecting what is important to you.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">You remove 3 fatigue and 3 strife, plus 3 fatigue and 3 strife for each Compromised or Incapacitated character in the scene with whom you share a bond (see </span><span class=\"fontstyle2\">Bonds</span><span class=\"fontstyle3\">, on page 187).</span></p>","source":{"book":"path_of_waves","page":95},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.FpyARQtMdf6V8HSY"},{"name":"Striking as Void","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":4,"kind":"kata","rank":5,"description":"<p><span class=\"fontstyle0\"><em>The future is part of Void’s domain, infinite in possibility and unfathomable in depth. Because of its formlessness, one cannot scheme to undermine the uncertain future—but the instant it takes shape, an action is vulnerable to countermeasures. The bushi rests until the last possible second, allowing the potential energy of their strike to take shape only after it is too late for their enemy to respond.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee, Ranged, or Unarmed] (void) check, you may spend (op) in the following ways:</span></p><p><span class=\"fontstyle2\">(void)(op): </span><span class=\"fontstyle3\">Immediately switch to a different stance of your choice.</span></p><p><span class=\"fontstyle2\">(void)(op): </span><span class=\"fontstyle3\">If you fail, you may perform another action. This must be an action you have not yet performed this turn. You can only activate this opportunity once per round.</span></p>","source":{"book":"core_rulebook","page":178},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.0Yx0bHZSdayqSMeX"},{"name":"Eyeless Sight Shot","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":4,"kind":"kata","rank":4,"description":"<p><span class=\"fontstyle0\"><em>To hit a target without seeing it is a masterful feat for any warrior who specializes in projectile weapons. Whether by firing through dense underbrush to hit a deer by the sound of its steps or banking a slingstone off a wall to hit a foe when you feel their heavy footfalls shake the floorboards, there are many ways to use one’s other senses to place a shot.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As an Attack and Movement action using a readied ranged weapon, you may make a </span><span class=\"fontstyle2\">Martial Arts [Ranged] (void) check </span><span class=\"fontstyle3\">targeting one character within your weapon’s range to whom you do not have direct line of sight. The TN of the check is equal to the target’s vigilance.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, your target suffers physical damage equal to your weapon’s base damage and receives strife equal to your bonus successes.</span></p>","source":{"book":"path_of_waves","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.hrIV8L0Ta8YQ8SnO","skill":"ranged"},{"name":"Battle in the Mind","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":4,"kind":"kata","rank":3,"description":"<p><span class=\"fontstyle0\"><em>As two masters of any martial art square off before a duel, each seeks to predict the other’s angle of attack and strategy, and the ways their predictions might be foiled by the opponent’s.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make an Initiative check for a duel using your Void Ring, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(void)(op)(op): </span><span class=\"fontstyle3\">You name two rings, then your opponent must name one of those two rings. When your opponent selects their stance during their first turn of the duel, they cannot select the ring they named as their stance.</span></p><p><span class=\"fontstyle2\">(void)</span><span class=\"fontstyle4\">(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">Choose a technique category. Learn one of your opponent’s known techniques of that category (chosen by the opponent) per (op) spent this way</span>.</p>","source":{"book":"core_rulebook","page":174},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.RdCEGT9Oy4wXvAep"},{"name":"Foreseen Need","xp_used":3,"xp_cost":3,"in_curriculum":false,"bought_at_rank":4,"kind":"shuji","rank":4,"description":"<p><span class=\"fontstyle0\"><em>Artisans with an open mind and an eye to the future are always working on things they may need one day. A little preparation and anticipation can pay off greatly at the right moment.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may make a </span><span class=\"fontstyle2\">TN 1 Artisan (void) check</span><span class=\"fontstyle3\">.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, you recall that you had foreseen the need for an item with a rarity equal to 1 plus your bonus successes on the check. Spend one Void point to instantly reveal one item you could have crafted, as long as it is reasonable (e.g., you could be carrying it on your person or have it in your quarters, you had access to the resources to craft it over the past month).</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle5\">(void)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">Double the rarity of the target item, but the item must be of a perishable nature or one with only sentimental value.</span></p>","source":{"book":"court_of_stones","page":119},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.l5hl19YeCvDCjKEN","skill":"artisan"},{"name":"A Samurai’s Fate","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":4,"kind":"shuji","rank":4,"description":"<p><span class=\"fontstyle0\"><em>A leader asks their warriors for the final service all samurai must someday render to their lord: to lay down their lives that others might live. Even as they fall in battle, their shed blood waters the fields that will grow a thousand victories.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As an action, you make a </span><span class=\"fontstyle2\">TN 5 Command (void) check </span><span class=\"fontstyle3\">targeting any number of characters (or your cohort, during a mass battle).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed during a skirmish, each target ignores any critical strikes with severity lower than your Void Ring plus your bonus successes. This effect persists until the end of the scene (at which point the injuries take effect). If you succeed during a mass battle, your army counts as having the Fearless Army ability, below:</span></p><p><span class=\"fontstyle2\"><em>Fearless Army</em>: </span><span class=\"fontstyle3\">At the end of each round, your army removes panic equal to your glory rank. This effect persists until the end of the scene.</span></p>","source":{"book":"core_rulebook","page":222},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.8Uy8s9BRJL9PEAQJ","skill":"command"}],"peculiarities":[{"name":"Light Sleeper","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"water","types":"Physical","description":"<p><span class=\"fontstyle0\"><em>“You see these scars?” she asked. He nodded respectfully at the Hiruma. It looked like someone had run a rake down her face—then repeated the action several times.</em></span></p><p><span class=\"fontstyle0\"><em>“This is what you get when you dare slumber here. Everyone else died that night.” She closed her eyes for a moment, then opened them abruptly, startling him. “You rest your guard, you die.” She looked closely at him. “You learn to stay awake, even when you sleep. Or you join the rest of my old patrol.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Light Sleeper distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You rouse from sleep very easily, a trick considered essential in hostile territory. You are trained to awaken before danger arrives, sleep with your weapons ready, and pretend to be in a deep sleep to lure enemies closer. You can go from a deep sleep to fully alert and fighting in the blink of an eye.</span></p></li><li><p><span class=\"fontstyle0\">- When performing a check that calls on rapidly recovering from sleep (such as a Survival (water) check to detect a threatening sound while dozing or a Fitness (water) check to react even when someone else is standing watch), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"shadowlands","page":96},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.ZtoejR7hmjZ0aE8k"},{"name":"Encompassing Duty","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"earth","types":"Mental","description":"<p><em>“I will lay down my life for my family. Nothing will stand in the way of that.”</em></p><p><em>– Aina, Ashigaru of the Lion</em></p><p></p><p>The following apply to a character with the Encompassing Duty adversity:</p><ul><li><p>- You have a duty to something: your family, a friend, a cause, or some other person or ideal. This duty should manifest into at least one discernible goal, one you can work out with the GM. A goal may be to provide for your family, rescue a friend, or achieve a similar aim. You have a difficult time relaxing or focusing on tasks that do not somehow advance your goal, and this may manifest in several ways, including frustration, anger, worry, or nervousness. </p></li><li><p>- Whenever you make a check related to overcoming something that could hinder you in achieving your duty (such as a Meditation (earth) check to keep a cool head in an ambush or a Courtesy (earth) check to reason with a stubborn shopkeeper), you must choose and reroll two dice containing (su) or (ex) . After resolving the check, if you failed, you gain 1 Void point.</p></li></ul>","source":{"book":"path_of_waves","page":72},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.TP83fjX8gnxELunG"},{"name":"Travel","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"water","types":"Mental, Physical","description":"<p><span class=\"fontstyle0\"><em>The old man sat heavily on the stool outside the constabulary office. He removed his straw hat, wiped his brow with his sleeve, and returned the hat to his head. His eyes, shaded by the wide brim, looked out at Yūka. The young girl smiled.</em></span></p><p><span class=\"fontstyle0\"><em>“Young lady, I have been from one side of Rokugan to the other—from Khanbulak to the Islands of Silk and Spice—and I have seen amazing sights. I will tell you this: in all my travels, I have become convinced of three things.” He counted them off on gnarled fingers. “All crows are black, it always rains when you don’t want it to, and Rokugan’s greatest treasure—a prize without equal—is its people.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Travel passion:</span></p><ul><li><p><span class=\"fontstyle3\">- You are not unsettled by foreign customs, and you can comfortably fit in even in strange environments.</span></p></li><li><p><span class=\"fontstyle3\">- After performing a check to travel to a new location or interact with a novel thing (such as a Survival (water) check to try to identify a new plant, animal, or phenomenon, or a Seafaring (water) check to travel by boat), you remove 3 strife.</span></p></li></ul>","source":{"book":"core_rulebook","page":115},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.7keAIKn0N8wjEsGa"},{"name":"Battle Trauma","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"fire","types":"Mental, Physical","description":"<p><em>The thousand cuts I have borne<br>And the thousand I have delivered<br>Paint my dreams in red<br>Broad brushstrokes to draw pictures<br>I cannot put to paper.<br>Do my ears ring from old age<br>Or is that steel’s song and the warrior’s cry<br>Gone so long ago<br>But never gone?</em></p><p><strong>Effects:</strong> The following apply to a character with the Battle Trauma anxiety:</p><ul><li><p>-  At the start of a duel, skirmish, or mass battle, your hands shake, your body tenses up, or your mind might even lock down. You can act normally, but your unsettled state is obvious to everyone around you, and others may try to exploit it.</p></li><li><p>-  After performing a check related to battle (such as a Martial Arts [Melee] (fire) check to strike down a foe or a Tactics (fire) check to generate initiative), you receive 3 strife. (Your GM can choose not to inflict this strife after the you have taken a few turns and thematically overcome your trauma.) If this is the first time this has occurred this scene, gain 1 Void point.</p></li></ul>","source":{"book":"core_rulebook","page":131},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.jlSq86lbglLrHXp8"},{"name":"Paragon of Courage","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"fire","types":"Mental, Virtue","description":"<p><span class=\"fontstyle0\"><em>“The heroes of myth—even the ones who were not of divine blood—did not live as humans do. It is impossible to embody an ideal without surpassing some part of your own humanity.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Paragon of Courage distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You believe utterly in Courage, and others instinctively discern that your actions are genuine when you act in accordance with it.</span></p></li><li><p><span class=\"fontstyle3\">- When performing a check for which you need to convince others of, or leverage your faith in, Courage (such as a Performance check to recount a tale that impresses its importance upon others or a Martial Arts [Melee] check to take up arms for this cause), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"core_rulebook","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.trppadBbshGjbSP2"}],"titles":[{"name":"Gunsō","xp_used":24,"xp_cost":24,"in_curriculum":false,"bought_at_rank":3,"description":"<p><span class=\"fontstyle0\">While the vast majority of soldiers in a Rokugani army are ashigaru and conscripts, many samurai are called to military service, either in the armies of their own clan or in the Imperial Legions. When samurai do take to the field, they often these serve in leadership positions. While each lord's forces have their own structure and character, common titles are used throughout Rokugan to indicate similar levels of authority. When a lord gathers a large force for battle, they may nominate one or more gunsō to command the kashira who lead individual units.</span></p><p><span class=\"fontstyle0\">A gunsō is responsible for all aspects of battle readiness for the troops under their command, including the troops’ training, discipline, and equipment. When battle begins, gunsō direct their troops in accordance with commands from their superiors, meaning they have to maintain good awareness not only of their own unit but also of the broader battle unfolding around them. Perhaps most importantly, gunsō are expected to display conspicuous leadership during battle, leading their troops from the front and rallying their soldiers, keeping them in the fight even as losses mount and their morale begins to waver.</span></p><p><span class=\"fontstyle2\"><strong>Assigned By:</strong> </span><span class=\"fontstyle0\">A daimyō may assign a samurai a rank within their military forces, and samurai serving within the military rank structure may be promoted by a superior officer.</span></p><p><span class=\"fontstyle2\"><strong>Status Award:</strong> </span><span class=\"fontstyle0\">+5 (to a minimum of 20)</span></p><p><span class=\"fontstyle2\"><strong>Title Ability:</strong> Lead from the Front</span></p><h2>Curriculum</h2><table><tbody><tr><td><p>Martial Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Command</p></td><td><p>Skill</p></td></tr><tr><td><p>Government</p></td><td><p>Skill</p></td></tr><tr><td><p><a class=\"compendium-link\" data-pack=\"l5r5e.core-techniques-kata\">(kata) Rank 1-4 Kata</a></p></td><td><p>Tech. Grp.</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-shuji.Item.L5RCoreShu000020\" data-pack=\"l5r5e.core-techniques-shuji\" data-type=\"Item\" data-id=\"L5RCoreShu000020\">(shuji) Rallying Cry</a> (prereq)</p></td><td><p>Technique</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-shuji.Item.L5RCoreShu000026\" data-pack=\"l5r5e.core-techniques-shuji\" data-type=\"Item\" data-id=\"L5RCoreShu000026\">(shuji) Stirring the Embers</a> (prereq)</p></td><td><p>Technique</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-shuji.Item.L5RCoreShu000011\" data-pack=\"l5r5e.core-techniques-shuji\" data-type=\"Item\" data-id=\"L5RCoreShu000011\">(shuji) Touchstone of Courage</a> (prereq)</p></td><td><p>Technique</p></td></tr></tbody></table>","source":{"book":"emerald_empire","page":250},"uuid":"Compendium.l5r5e-compendia-sortilege.titles-l5r-sortilege.Item.2R7nNp7NWNLkVs5j"}],"bonds":[],"signature_scrolls":[],"gear":[{"name":"Club","quantity":1,"description":"<p><span class=\"fontstyle0\">The humble club is perhaps the oldest weapon in Rokugan—at least among humans. Often little more than a length of stout wood or shaped stone, a club can be fashioned with available materials by nearly anyone. While a club can certainly be used to kill, doing so takes some work on the part of the wielder</span>.</p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.ElFJfEcGvWe6A5yU","damage":5,"deadliness":2,"range":"0-1","grip_2":"Damage +1","skill":"melee","category":"Blunt Weapons","rarity":"1","zeni":"1 bu","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Katana","quantity":1,"description":"<p><span class=\"fontstyle0\">As much a work of art as it is a weapon, the katana is perhaps the most revered weapon in Rokugan. It has an elegant, slightly curved blade between three and four feet long, made of steel that is specially folded during its creation. This unique forging style ensures that the inner part of the blade remains springy and soft while the outside is as hard as tempered steel. Each sword likely has a history and legacy, and it is a constant reminder of the weight that destiny has placed upon its bearer’s shoulders as a samurai of Rokugan</span>.</p>","source":{"book":"core_rulebook","page":232},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.BhKwwnN5UHI5rZpp","damage":4,"deadliness":5,"range":"1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"20 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Knife","quantity":1,"description":"<p><span class=\"fontstyle0\">Knives come in a dizzying array of types and styles, from the familiar crudely constructed knife in a peasant’s kitchen to the deadly combat knives samurai take into battle. Those particularly designed for combat—like the aiguchi—are often equipped with small hand guards to make them more useful in the field.</span></p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.n8xA05Fb9WpXg3oo","damage":2,"deadliness":4,"range":"0","grip_2":"Deadliness +2","skill":"melee","category":"Hand Weapons","rarity":"1","zeni":"1 koku","properties":[{"id":"L5RCorePro000001","name":"Razor-Edged"},{"id":"L5RCorePro000005","name":"Concealable"},{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Tetsubō","quantity":1,"description":"<p><span class=\"fontstyle0\">Long and narrow, a tetsubō can be as tall as a human and normally is constructed of iron or hardwood. Above its grip, a tetsubō is covered in steel, iron, or even jade spikes or studs that add to the weapon’s lethality and crush armor or plated carapace with ease.</span></p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.CW6h0NSzTEhimQXw","damage":7,"deadliness":3,"range":"1-2","grip_1":"N/A","skill":"melee","category":"Blunt Weapons","rarity":"5","zeni":"20 koku","properties":[{"id":"L5RCorePro000006","name":"Cumbersome"},{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Wakizashi","quantity":1,"description":"<p><span class=\"fontstyle0\">Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</span></p>","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Kamayari","quantity":1,"description":"<p><span class=\"fontstyle0\">A </span><span class=\"fontstyle2\">kamayari </span><span class=\"fontstyle0\">is a spear with a hooked protrusion on one or both sides of the blade, similar to a ji. While the hook’s most obvious applications are blocking attacks and dragging foes off horseback, it also has practical noncombat applications. A shinobi might swing from a sturdy tree limb using the hook or might use it to climb a high fence. If the spear shaft has holes in it, the shinobi can use the shaft to measure distances or can slot bars into the holes to use it as a ladder. Finally, the hook is useful for carrying items on long walks.</span></p>","source":{"book":"court_of_stones","page":110},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.PsmRwhHYBz0daKi5","damage":4,"deadliness":3,"range":"2","grip_1":"N/A","skill":"melee","category":"Specialist Weapons","rarity":"7","zeni":"8 koku","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000007","name":"Snaring"}]},{"name":"Lacquered Armor","quantity":1,"description":"<p><span class=\"fontstyle0\">Heavier than ashigaru armor, lacquered armor is worn by samurai who desire a good mix of protection and grandeur, and is just at home at war as at a martial ceremony. These suits are made of thick leather or steel plates stitched or riveted to a leather backing. They protect the torso, head, upper arms, and groin, and the legs above the knee. They can also include a helmet and mask, though these are not considered integral.</span></p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.sPKkavq6O0SoxiPj","armor":{"physical":4,"supernatural":0},"rarity":"6","zeni":"25 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000006","name":"Cumbersome"},{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Traveling Clothes","quantity":1,"description":"<p><span class=\"fontstyle0\">Traveling clothes ordinarily consist of roughspun garments designed to resist wear and tear. They can be anything from robes to a kimono or jacket and leggings and are often accentuated with a hat or cloak</span>.</p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.zcsgspz4VluSMeI0","armor":{"physical":2,"supernatural":0},"rarity":"2","zeni":"2 bu","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000012","name":"Mundane"},{"id":"L5RCorePro000016","name":"Subtle"}]},{"name":"Traveling pack","quantity":1,"description":"<p><span class=\"fontstyle0\">Blanket, bowl, chopsticks, four days of travel rations, flint and tinder, and any three other items of the player’s choice that are rarity 4 or lower.</span></p>","source":{"book":"core_rulebook","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.Rex7fGo6R1KuUhQJ","rarity":"1","zeni":"10 koku","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Kubi Bukuro","quantity":1,"description":"<p>These are simple net bags used to carry the severed head of an enemy, which is considered both a trophy and a good omen. Lion Clan samurai use them to carry their trophies without touching dead flesh, but the Kuni family uses them for collecting samples of Shadowlands creatures for study.</p>","source":{"book":"core_rulebook","page":242},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.6J25vJx1tVirgXf1","rarity":"2","zeni":"2 zeni","properties":[{"id":"L5RCorePro000011","name":"Wargear"}]}]},{"xp":216,"label":"General, Rank 5","rank":5,"school":"Hida Defender School","foundry_id":"53TxZNvkvH299bkh","rings":{"air":2,"earth":4,"fire":2,"water":3,"void":3},"skills":{"artisan":{"aesthetics":0,"composition":1,"design":0,"smithing":0},"martial":{"fitness":3,"melee":3,"ranged":3,"unarmed":2,"meditation":3,"tactics":2},"scholar":{"culture":0,"government":4,"medicine":0,"sentiment":0,"theology":0},"social":{"command":4,"courtesy":1,"games":3,"performance":0},"trade":{"commerce":0,"labor":2,"seafaring":1,"skulduggery":1,"survival":2}},"social":{"honor":45,"glory":44,"status":30,"ninjo":"Longs to travel Rokugan, or possibly even beyond.","giri":"Hiruma Nobuyasu is their lord. They insist that she command her unit, defending the Kaiu Wall.","bushido_tenets":{"paramount":"Courage","less_significant":"Sincerity"}},"derived":{"endurance":12,"composure":14,"focus":4,"vigilance":3,"void_points":3},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[{"label":"Martial Arts [Ranged] +1 (0 -> 1)","type":"skill","skill":"ranged","ring":"void","at_rank":1,"xp":2,"in_curriculum":true},{"label":"Martial Arts [Melee] +1 (1 -> 2)","type":"skill","skill":"melee","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Martial Arts [Unarmed] +1 (0 -> 1)","type":"skill","skill":"unarmed","ring":"void","at_rank":1,"xp":2,"in_curriculum":true},{"label":"Martial Arts [Ranged] +1 (1 -> 2)","type":"skill","skill":"ranged","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Command +1 (1 -> 2)","type":"skill","skill":"command","ring":"void","at_rank":2,"xp":4,"in_curriculum":true},{"label":"Void +1 (2 -> 3)","type":"ring","ring":"void","at_rank":2,"xp":9,"in_curriculum":false},{"label":"Labor +1 (0 -> 1)","type":"skill","skill":"labor","ring":"void","at_rank":2,"xp":2,"in_curriculum":true},{"label":"Command +1 (2 -> 3)","type":"skill","skill":"command","ring":"void","at_rank":2,"xp":6,"in_curriculum":true},{"label":"Composition +1 (0 -> 1)","type":"skill","skill":"composition","ring":"void","at_rank":2,"xp":2,"in_curriculum":false},{"label":"Command +1 (4 -> 5)","type":"skill","skill":"command","ring":"void","at_rank":1,"xp":10,"in_curriculum":true,"via":"Gunsō"},{"label":"Government +1 (0 -> 1)","type":"skill","skill":"government","ring":"void","at_rank":1,"xp":2,"in_curriculum":true,"via":"Gunsō"},{"label":"Fitness +1 (2 -> 3)","type":"skill","skill":"fitness","ring":"void","at_rank":3,"xp":6,"in_curriculum":true},{"label":"Seafaring +1 (0 -> 1)","type":"skill","skill":"seafaring","ring":"void","at_rank":3,"xp":2,"in_curriculum":true},{"label":"Labor +1 (1 -> 2)","type":"skill","skill":"labor","ring":"void","at_rank":3,"xp":4,"in_curriculum":true},{"label":"Martial Arts [Melee] +1 (2 -> 3)","type":"skill","skill":"melee","ring":"void","at_rank":3,"xp":6,"in_curriculum":true},{"label":"Earth +1 (3 -> 4)","type":"ring","ring":"earth","at_rank":4,"xp":12,"in_curriculum":false},{"label":"Water +1 (1 -> 2)","type":"ring","ring":"water","at_rank":4,"xp":6,"in_curriculum":false},{"label":"Water +1 (2 -> 3)","type":"ring","ring":"water","at_rank":4,"xp":9,"in_curriculum":false},{"label":"Government +1 (1 -> 2)","type":"skill","skill":"government","ring":"void","at_rank":4,"xp":4,"in_curriculum":true},{"label":"Meditation +1 (0 -> 1)","type":"skill","skill":"meditation","ring":"void","at_rank":4,"xp":2,"in_curriculum":true},{"label":"Meditation +1 (1 -> 2)","type":"skill","skill":"meditation","ring":"void","at_rank":4,"xp":4,"in_curriculum":true},{"label":"Government +1 (2 -> 3)","type":"skill","skill":"government","ring":"void","at_rank":4,"xp":6,"in_curriculum":true},{"label":"Martial Arts [Ranged] +1 (2 -> 3)","type":"skill","skill":"ranged","ring":"void","at_rank":1,"xp":6,"in_curriculum":true,"via":"General"},{"label":"Government +1 (3 -> 4)","type":"skill","skill":"government","ring":"void","at_rank":1,"xp":8,"in_curriculum":true,"via":"General"},{"label":"Martial Arts [Unarmed] +1 (1 -> 2)","type":"skill","skill":"unarmed","ring":"void","at_rank":1,"xp":4,"in_curriculum":true,"via":"General"},{"label":"Games +1 (0 -> 1)","type":"skill","skill":"games","ring":"void","at_rank":1,"xp":2,"in_curriculum":true,"via":"General"},{"label":"Games +1 (1 -> 2)","type":"skill","skill":"games","ring":"void","at_rank":1,"xp":4,"in_curriculum":true,"via":"General"},{"label":"Games +1 (2 -> 3)","type":"skill","skill":"games","ring":"void","at_rank":1,"xp":6,"in_curriculum":true,"via":"General"},{"label":"Meditation +1 (2 -> 3)","type":"skill","skill":"meditation","ring":"void","at_rank":1,"xp":6,"in_curriculum":true,"via":"General"}],"techniques":[{"name":"Striking as Earth","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"kata","rank":1,"description":"<p><span class=\"fontstyle0\"><em>After striking, the bushi roots themself to the ground, hunkering down to make sure their armor takes the brunt of a hit or raising a weapon in a warding position where it can deflect harm without being damaged.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee, Ranged, or Unarmed] (earth) check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth)(op)+: </span><span class=\"fontstyle3\">Treat your physical resistance as 1 higher per </span><span class=\"fontstyle4\">(op) </span><span class=\"fontstyle3\">spent this way until the beginning of your next turn.</span></p>","source":{"book":"core_rulebook","page":178},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.aKTfAZXbHo77kHOq"},{"name":"Lord Hida’s Grip (Crab)","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>The Kami Hida, patron of the Crab Clan, was a legendary slayer of monsters. He beheaded the massive demon that once menaced the rose-marble palace, and ripped out one skull of the two-headed Kabuto no Oni and crushed the other head with it. However, Hida was no mere brute: he was cunning, killing monsters by exploiting their weaknesses. Warriors of the Crab Clan train in similar techniques. They turn their foes' great weight against them by pinning or strategically damaging specific body parts.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As an Attack action, you may make a </span><span class=\"fontstyle2\">Fitness (void) check </span><span class=\"fontstyle3\">targeting one creature of silhouette 3 or larger at range 0–1. The TN of the check is equal to the silhouette of the target (to a minimum of 1).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, your target suffers the Immobilized condition. If you succeed, you count as granting assistance (see page 26) to all characters who perform Attack actions against your target. This effect persists until the beginning of your next turn.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(void)(op): </span><span class=\"fontstyle3\">Your target must resist with a </span><span class=\"fontstyle2\">Fitness check </span><span class=\"fontstyle3\">or suffer physical damage equal to its silhouette, ignoring its resistance, and the Prone condition. The TN of this check is equal to your school rank.</span></p>","source":{"book":"core_rulebook","page":176},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.ERExWdY04GNvu3p0","skill":"fitness"},{"name":"Way of the Crab","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p><span class=\"fontstyle0\">Ignore the Cumbersome quality of armor you wear.</span></p><p><span class=\"fontstyle0\">Once per round, before making a check to resist a critical strike, you may reduce the severity of that critical strike by the physical resistance of your armor plus your school rank (to a minimum of 0).</span></p>","source":{"book":"core_rulebook","page":57},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.7LHxYqmpqMUETLEq"},{"name":"Appreciate the Scenery","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<p><span class=\"fontstyle0\"><em>In many lands, including Rokugan, the beauty of the natural world inspires art, poetry, and other works of note, even (or perhaps especially) when it is stark and dangerous. When on a long and perilous journey into foreign lands where deadly intrigues surely await, finding beauty in the rougher parts of the world can be a much-needed source of solace.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Support action check targeting another character, if you and the character you are targeting are in Dangerous, Entangling, Hallowed, Imbalanced, or Obscuring terrain, you may spend (op) as follows:</span></p><p><span class=\"fontstyle2\">(earth) or</span><span class=\"fontstyle4\"> (water)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">You and your target each remove strife equal to your ranks in Composition.</span></p><p><span class=\"fontstyle2\">(air) or (fire)</span><span class=\"fontstyle4\">(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">You and your target gain the Emboldened condition (see page 133).</span></p><p><span class=\"fontstyle2\">(void)(op): </span><span class=\"fontstyle3\">Your and your target gain the Centered condition (see page 133).</span></p>","source":{"book":"children_of_the_five_winds","page":116},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.gbUpw4ife9RdWbK9"},{"name":"Honest Assessment","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<p><span class=\"fontstyle0\"><em>Honesty is a virtue of Bushidō, but direct honesty is often seen as rudeness among the samurai—instead, one is expected to find a polite way to imply one’s meaning to spare the feelings of the other involved. As a result, directness can be something of a rare and valuable commodity.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may make a </span><span class=\"fontstyle2\">TN 2 Courtesy (earth) check </span><span class=\"fontstyle3\">to appraise the weaknesses of a character.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, choose one of the target’s known disadvantages. The target does not apply that disadvantage to their checks until the end of the scene.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(earth)(op)+: </span><span class=\"fontstyle3\">Choose one additional disadvantage per (op) spent this way.</span></p><p><span class=\"fontstyle5\">(earth)(op)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">Reduce the TN of the target’s next skill check using the ring the disadvantage is attached to by 2.</span></p>","source":{"book":"core_rulebook","page":216},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.t427qRaOh42dfbVM","skill":"courtesy"},{"name":"Rushing Avalanche Style","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>When adopting this style, the bushi strikes with reckless abandon using a heavy armament. Thanks to the sheer weight of their weapon and the ferocity of their strikes, even a glancing blow can cause serious harm, and a telling blow usually ends the battle.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee] check using a blunt weapon, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(op): </span><span class=\"fontstyle3\">If you fail with a shortfall of two or less, your target suffers physical damage equal to your ranks in Fitness.</span></p><p><span class=\"fontstyle2\">(op): </span><span class=\"fontstyle3\">If you succeed and your target is Prone, increase the damage you deal by your ranks in Fitness.</span></p>","source":{"book":"core_rulebook","page":180},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.EZG0aAg9oxEUou5u"},{"name":"Staggering Shot","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>Putting an arrow at a foe’s feet can cause them to stumble or trip, and an experienced archer knows how to take full advantage of this, planting bolts to break an</em></span><em> </em><span class=\"fontstyle0\"><em>enemy’s stride or pinning their clothes to slow them down, making any approach extremely treacherous.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you perform a Martial Arts [Ranged] check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth) or (fire)(op)(op): </span><span class=\"fontstyle3\">Your target treats all terrain as having the Dangerous quality. This effect persists until the end of your next turn.</span></p><p><span class=\"fontstyle2\">(air) or (water)(op)(op): </span><span class=\"fontstyle3\">Your target treats all terrain as having the Entangling quality. This effect persists until the end of your next turn.</span></p>","source":{"book":"path_of_waves","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.6N5n9fweaz1CbLCu"},{"name":"Touchstone of Courage","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"shuji","rank":3,"description":"<p><span class=\"fontstyle0\"><em>Armies are rarely routed in the field; instead, most collapse when morale becomes impossible to maintain. As panic rises in the ranks, soldiers look to leaders to set an example. The character does just this, speaking to the importance of duty to bring their troops back from the edge of chaos.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may make a </span><span class=\"fontstyle2\">TN 4 Command (earth) check </span><span class=\"fontstyle3\">targeting any number of characters (or your cohort during a mass battle).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed during an intrigue, duel, or skirmish conflict, each target increases their composure by your Earth Ring. This effect persists until the end of the scene. If you succeed during a mass battle, increase your army’s discipline by your Earth Ring plus your bonus successes. This effect persists until the end of the scene.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(earth)(op)(op): </span><span class=\"fontstyle3\">During an intrigue, duel, or skirmish, each target removes strife equal to your Earth Ring.</span></p><p><span class=\"fontstyle2\">(earth)(op)(op): </span><span class=\"fontstyle3\">During a mass battle, your army removes panic equal to your Earth Ring.</span></p>","source":{"book":"core_rulebook","page":217},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.fFxQOBXLb9ol9owk","skill":"command"},{"name":"Thunderbolt Style","via":"Gunsō","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":4,"description":"<p><span class=\"fontstyle0\"><em>Hitting a target with a thrown weapon is difficult; hitting more than one target with the same throw is even harder. However, a warrior of sufficient skill can potentially harm multiple targets with a properly placed spear or ax throw, the projectile striking one foe and caroming off at an unexpected angle or causing the primary target to collapse into another. Such an unexpected tactic can catch an entire unit off guard, forcing them to spread out when staying close together would be advantageous.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make an Attack action check in which you throw your weapon, you may spend (op) as follows:</span></p><p><span class=\"fontstyle4\">(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">Choose another character at range 0–1 of your target with vigilance lower than your ranks in Fitness plus (op) spent this way. That character suffers damage equal to your weapon’s base damage. You can activate this opportunity multiple times, choosing different characters to affect each time.</span></p>","source":{"book":"children_of_the_five_winds","page":110},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.rwDHm7Q3qmjDJZRg"},{"name":"Deflective Defense","via":"Gunsō","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":3,"description":"<p><span class=\"fontstyle0\"><em>Large-enough weapons can, in a pinch, serve as shields against missile attacks. If a warrior plants their weapon in the ground and takes cover behind it with a narrow profile, even a </em></span><span class=\"fontstyle2\"><em>bisentō </em></span><span class=\"fontstyle0\"><em>makes the likelihood of a lethal hit with an arrow or dart far lower.</em></span></p><p><span class=\"fontstyle3\"><strong>Activation:</strong> </span><span class=\"fontstyle0\">As a Movement and Support action using a readied Cumbersome weapon, you may make a </span><span class=\"fontstyle3\">TN 2 Martial Arts [Melee] (earth) check</span><span class=\"fontstyle0\">.</span></p><p><span class=\"fontstyle3\"><strong>Effects:</strong> </span><span class=\"fontstyle0\">If you succeed, treat your physical resistance against attacks made by characters at range 2–6 as increased by your ranks in Fitness.\\</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle3\">(earth)(op)(op): </span><span class=\"fontstyle0\">After you defend against physical damage from an attack made by a character at range 2–6, that character suffers 2 strife.</span></p>","source":{"book":"path_of_waves","page":88},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.eC8kPJscUbiEoE7c","skill":"melee"},{"name":"Tactical Assessment","via":"Gunsō","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>Akodo’s </em></span><span class=\"fontstyle2\"><em>Leadership </em></span><span class=\"fontstyle0\"><em>and Bayushi’s </em></span><span class=\"fontstyle2\"><em>Lies </em></span><span class=\"fontstyle0\"><em>agree on a few topics, for both leaders were practical to a certain degree, even if Akodo famously scorned many of Bayushi’s methods. As the scholar Hida Fuyuko noted in her revelatory commentary on </em></span><span class=\"fontstyle2\"><em>Leadership</em></span><span class=\"fontstyle0\"><em>’s lessons for commanders on the Kaiu Wall, the most famous meeting of these two minds comes on the matter of preparation: battles are not won in the field, but in the leadup to the conflict. Even in small clashes, the warrior who better understands the terrain, the strength of their own forces, and the composition of the enemy’s troops is usually victorious.</em></span></p><p><span class=\"fontstyle3\"><strong>Activation:</strong> </span><span class=\"fontstyle2\">When you make an Initiative check, you may spend</span><span class=\"fontstyle4\"> (op) </span><span class=\"fontstyle2\">in the following way:</span></p><p><span class=\"fontstyle3\">(air)(op): </span><span class=\"fontstyle2\">Choose an enemy in the conflict. Learn one of their advantages (of their choice) and their physical or supernatural resistance (your choice).</span></p><p><span class=\"fontstyle3\">(earth)(op): </span><span class=\"fontstyle2\">Choose a character in the conflict. They do not apply any of their disadvantages to their checks until the end of their first turn.</span></p><p><span class=\"fontstyle3\">(water)(op): </span><span class=\"fontstyle2\">Choose a piece of terrain in the scene (see </span><span class=\"fontstyle3\">Terrain </span><span class=\"fontstyle2\">on page 267). Until the start of your first turn, it counts as having the Obscuring quality for Attack action checks targeting you and your allies.</span></p><p><span class=\"fontstyle3\">(fire)(op): </span><span class=\"fontstyle2\">Choose a character in the conflict and one of their advantages you know. Until the end of their first turn, they apply that advantage to all of their checks.</span></p>","source":{"book":"core_rulebook","page":178},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.TcFVNDk57aKGpLR2"},{"name":"Rallying Cry","via":"Gunsō","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"shuji","rank":3,"description":"<p><span class=\"fontstyle0\"><em>The leader roars, calling their troops to battle, and the voice of an army echoes around them as the single cry is joined by many. As one, the troops surge forward to claim victory or perish in the attempt.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may make a </span><span class=\"fontstyle2\">TN 2 Command (fire) </span><span class=\"fontstyle3\">or </span><span class=\"fontstyle2\">Performance (fire) check </span><span class=\"fontstyle3\">targeting any number of characters in the scene (or one cohort in a mass battle).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, the targets are energized and excited by your rhetoric. After </span><span class=\"fontstyle2\">Step 5: Choose Kept Dice</span><span class=\"fontstyle3\">, each target adds a kept (ring) set to an (op)(st) result. This effect persists until the end of your next turn.</span></p><h4><span class=\"fontstyle5\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(fire)(op)+: </span><span class=\"fontstyle3\">In a skirmish, each enemy in the scene suffers 1 strife per (op) spent this way.</span></p><p><span class=\"fontstyle2\">(fire)(op)+: </span><span class=\"fontstyle3\">In a mass battle, the enemy army suffers 1 panic per (op) spent this way.</span> <br style=\" font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: 2; text-align: -webkit-auto; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px; \"></p>","source":{"book":"core_rulebook","page":219},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.4Z888LVUKQoDU4n8","skill":"command,performance"},{"name":"Lead from the Front","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":3,"kind":"title_ability","rank":1,"description":"<p><span class=\"fontstyle0\">When you defeat an opponent in a clash, your cohort removes panic equal to the opponent’s glory rank.</span></p><p><span class=\"fontstyle0\">Once per round when you succeed at an Attack action check during a mass battle, your cohort removes panic equal to half of the attrition you inflict.</span></p>","source":{"book":null,"page":0},"uuid":"Compendium.l5r5e-compendia-sortilege.title-abilities-l5r-sortilege.Item.YTRyf5NAEdnGa2K1"},{"name":"Great Anvil's Measure","xp_used":3,"xp_cost":3,"in_curriculum":false,"bought_at_rank":3,"kind":"shuji","rank":2,"description":"<p><span class=\"fontstyle0\"><em>A proud leader often draws attention to themselves in battle, and a leader both proud and skilled does so to draw their enemy into attacking them—especially when the enemy would rather attack elsewhere. When the leader’s troops are properly readied, and especially when they are in a highly defensible location, such an attack against them is doomed to fail.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a check to perform a Guard action in a skirmish (see page 264 of the core rulebook) or a Reinforce action in a mass battle (see page 279 of the core rulebook), you may spend (op) as follows:</span></p><p><span class=\"fontstyle2\">(earth)(op)+ (Guard): </span><span class=\"fontstyle3\">Choose any number of characters in the scene with focus lower than or equal to your ranks in Performance plus 2 per (op) spent this way. Each chosen character must receive strife equal to your ranks in Performance to perform an Attack or Scheme action targeting any character other than you. This effect persists until the end of your next turn.</span></p><p><span class=\"fontstyle2\">(earth)(op)+ (Reinforce): </span><span class=\"fontstyle3\">Choose any number of leaders in the enemy army with focus lower than or equal to your ranks in Performance plus 2 per (op) spent this way. The enemy army receives panic equal to your ranks in Performance each time any of those leaders performs an Attack or Scheme action targeting any cohort other than yours. This effect persists until the end of your next turn.</span></p>","source":{"book":"fields_of_victory","page":100},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.F4ukKaPLuPJCCDKe"},{"name":"Improvised Assault","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":3,"kind":"kata","rank":3,"description":"<p><span class=\"fontstyle0\"><em>The character adapts something in their environment for use as an improvised weapon that suits their own fighting style. This might mean blocking hits with a chair like a shield, swinging a heavy branch like a club, or even wielding an umbrella with a swordmaster’s skill. Such improvised weapons rarely survive combat, but even if a broken sake bottle won’t hold an edge for long, a single good stab can often end a fight.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Movement and Support action, you may make a </span><span class=\"fontstyle2\">TN 2 Tactics (water) </span><span class=\"fontstyle3\">or </span><span class=\"fontstyle2\">Smithing (water) check </span><span class=\"fontstyle3\">using a readied improvised weapon.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, you may choose a Martial Arts [Melee] weapon profile for a weapon similar in shape to the improvised weapon (the GM has discretion over whether the substitution is appropriate). Treat the improvised weapon as having that profile, with its damage and deadliness reduced by 1. This effect persists until the end of the scene, at which point the improvised weapon gains the Destroyed quality.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(water)(op)(op): </span><span class=\"fontstyle3\">You may immediately perform a Strike action using the readied weapon.</span></p><p><span class=\"fontstyle2\">(water)(op)(op)(op): </span><span class=\"fontstyle3\">If you succeed, choose one of the following item qualities: Cumbersome, Razor-Edged, or Snaring. The weapon is treated as having that quality.</span></p>","source":{"book":"path_of_waves","page":87},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.pQPOCwe6xFiuPyu7","skill":"tactics,smithing"},{"name":"Iron in the Mountains Style","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":3,"kind":"kata","rank":4,"description":"<p><span class=\"fontstyle0\"><em>The bushi strikes with crushing force, breaking their enemy’s footing and knocking them to the ground with an overwhelming blow or sweeping their stance out from underneath them with a well-placed kick.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee, Ranged, or Unarmed] (Earth) check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth)(op)+: </span><span class=\"fontstyle3\">One target of your action must resist with a </span><span class=\"fontstyle2\">TN 3 Fitness check ((air) 1, (water) 4) </span><span class=\"fontstyle3\">or suffer the Prone condition and fatigue equal to their shortfall. Increase the TN of the check to resist by 1 per (op) spent this way.</span></p>","source":{"book":"core_rulebook","page":176},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.B60KpdAhSAXaNhSt"},{"name":"Iron Shell Style","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":3,"kind":"kata","rank":3,"description":"<p><span class=\"fontstyle0\"><em>To defend against a single, predictable blow, a warrior can dig in, rooting themself and dispersing the force as it comes. Such a complete defense is exhausting to maintain, but it can keep a fighter on their feet when they otherwise would surely have fallen.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you perform a Guard action, if you have not moved any range bands this turn, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth) or (void)(op)+: </span><span class=\"fontstyle3\">Choose one character you can perceive per (op) spent this way. The next time you defend against physical damage from that character, your fatigue cannot be increased to a value greater than your endurance. This effect persists until the end of your next turn.</span></p>","source":{"book":"path_of_waves","page":86},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.2gfStxWLxFx4GZO9"},{"name":"Wanderer's Resolve","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":3,"kind":"shuji","rank":1,"description":"<p><span class=\"fontstyle0\"><em>A samurai with a lord can find resolve in the loyalty they feel, but a samurai with no lord has no easy wellspring from which to draw resolve. This hardship and isolation, however, can lead a rōnin</em></span><em> to discover a certainty</em><span class=\"fontstyle0\"><em> all their own, for if they do not act, no one else will. The lives of their friends—of those who depend on them—rest solely in their hands.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">Once per scene as a Support action, if you are in a Void stance, you may focus on protecting what is important to you.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">You remove 3 fatigue and 3 strife, plus 3 fatigue and 3 strife for each Compromised or Incapacitated character in the scene with whom you share a bond (see </span><span class=\"fontstyle2\">Bonds</span><span class=\"fontstyle3\">, on page 187).</span></p>","source":{"book":"path_of_waves","page":95},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.FpyARQtMdf6V8HSY"},{"name":"Striking as Void","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":4,"kind":"kata","rank":5,"description":"<p><span class=\"fontstyle0\"><em>The future is part of Void’s domain, infinite in possibility and unfathomable in depth. Because of its formlessness, one cannot scheme to undermine the uncertain future—but the instant it takes shape, an action is vulnerable to countermeasures. The bushi rests until the last possible second, allowing the potential energy of their strike to take shape only after it is too late for their enemy to respond.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee, Ranged, or Unarmed] (void) check, you may spend (op) in the following ways:</span></p><p><span class=\"fontstyle2\">(void)(op): </span><span class=\"fontstyle3\">Immediately switch to a different stance of your choice.</span></p><p><span class=\"fontstyle2\">(void)(op): </span><span class=\"fontstyle3\">If you fail, you may perform another action. This must be an action you have not yet performed this turn. You can only activate this opportunity once per round.</span></p>","source":{"book":"core_rulebook","page":178},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.0Yx0bHZSdayqSMeX"},{"name":"Eyeless Sight Shot","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":4,"kind":"kata","rank":4,"description":"<p><span class=\"fontstyle0\"><em>To hit a target without seeing it is a masterful feat for any warrior who specializes in projectile weapons. Whether by firing through dense underbrush to hit a deer by the sound of its steps or banking a slingstone off a wall to hit a foe when you feel their heavy footfalls shake the floorboards, there are many ways to use one’s other senses to place a shot.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As an Attack and Movement action using a readied ranged weapon, you may make a </span><span class=\"fontstyle2\">Martial Arts [Ranged] (void) check </span><span class=\"fontstyle3\">targeting one character within your weapon’s range to whom you do not have direct line of sight. The TN of the check is equal to the target’s vigilance.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, your target suffers physical damage equal to your weapon’s base damage and receives strife equal to your bonus successes.</span></p>","source":{"book":"path_of_waves","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.hrIV8L0Ta8YQ8SnO","skill":"ranged"},{"name":"Battle in the Mind","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":4,"kind":"kata","rank":3,"description":"<p><span class=\"fontstyle0\"><em>As two masters of any martial art square off before a duel, each seeks to predict the other’s angle of attack and strategy, and the ways their predictions might be foiled by the opponent’s.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make an Initiative check for a duel using your Void Ring, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(void)(op)(op): </span><span class=\"fontstyle3\">You name two rings, then your opponent must name one of those two rings. When your opponent selects their stance during their first turn of the duel, they cannot select the ring they named as their stance.</span></p><p><span class=\"fontstyle2\">(void)</span><span class=\"fontstyle4\">(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">Choose a technique category. Learn one of your opponent’s known techniques of that category (chosen by the opponent) per (op) spent this way</span>.</p>","source":{"book":"core_rulebook","page":174},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.RdCEGT9Oy4wXvAep"},{"name":"Foreseen Need","xp_used":3,"xp_cost":3,"in_curriculum":false,"bought_at_rank":4,"kind":"shuji","rank":4,"description":"<p><span class=\"fontstyle0\"><em>Artisans with an open mind and an eye to the future are always working on things they may need one day. A little preparation and anticipation can pay off greatly at the right moment.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may make a </span><span class=\"fontstyle2\">TN 1 Artisan (void) check</span><span class=\"fontstyle3\">.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, you recall that you had foreseen the need for an item with a rarity equal to 1 plus your bonus successes on the check. Spend one Void point to instantly reveal one item you could have crafted, as long as it is reasonable (e.g., you could be carrying it on your person or have it in your quarters, you had access to the resources to craft it over the past month).</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle5\">(void)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">Double the rarity of the target item, but the item must be of a perishable nature or one with only sentimental value.</span></p>","source":{"book":"court_of_stones","page":119},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.l5hl19YeCvDCjKEN","skill":"artisan"},{"name":"A Samurai’s Fate","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":4,"kind":"shuji","rank":4,"description":"<p><span class=\"fontstyle0\"><em>A leader asks their warriors for the final service all samurai must someday render to their lord: to lay down their lives that others might live. Even as they fall in battle, their shed blood waters the fields that will grow a thousand victories.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As an action, you make a </span><span class=\"fontstyle2\">TN 5 Command (void) check </span><span class=\"fontstyle3\">targeting any number of characters (or your cohort, during a mass battle).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed during a skirmish, each target ignores any critical strikes with severity lower than your Void Ring plus your bonus successes. This effect persists until the end of the scene (at which point the injuries take effect). If you succeed during a mass battle, your army counts as having the Fearless Army ability, below:</span></p><p><span class=\"fontstyle2\"><em>Fearless Army</em>: </span><span class=\"fontstyle3\">At the end of each round, your army removes panic equal to your glory rank. This effect persists until the end of the scene.</span></p>","source":{"book":"core_rulebook","page":222},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.8Uy8s9BRJL9PEAQJ","skill":"command"},{"name":"Pillar of Calm","via":"General","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"shuji","rank":4,"description":"<p><span class=\"fontstyle0\"><em>The character calls for reason to prevail and swords to be sheathed, appealing to a common ideal or greater threat that stands before the belligerent parties.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Scheme and Support action, you may make a </span><span class=\"fontstyle2\">Command (earth) check </span><span class=\"fontstyle3\">targeting a number of characters up to your Earth Ring times your school rank. The TN of this check is equal to the highest strife among the targets.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed while targeting all of the leaders involved in a conflict, you may de-escalate the conflict one level (from a mass battle to a skirmish, a skirmish to a duel, or a duel to an intrigue).</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(earth)(op)(op)+: </span><span class=\"fontstyle3\">You may de-escalate the conflict by one additional level per (op)(op) spent this way.</span></p>","source":{"book":"core_rulebook","page":216},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.ep7mRJxHHPHofW4X","skill":"command"},{"name":"Landslide Strike","via":"General","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>Lashing out at the foe’s legs, the warrior forces their enemy to either abandon their stance or be knocked from their feet. This tactic is especially effective on uneven ground, as the enemy must watch their footing or risk even further injury.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As an Attack and Scheme action, you may make a </span><span class=\"fontstyle2\">Martial Arts [Melee] ((earth) </span><span class=\"fontstyle3\">or </span><span class=\"fontstyle2\">(water)) check </span><span class=\"fontstyle3\">targeting one character in your weapon’s range. The TN is equal to the target’s vigilance. If your target is in Dangerous, Entangling, or Obscuring terrain, the TN is 1 instead.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, your target must choose one of the following:</span></p><ul><li><p><span class=\"fontstyle3\">- Receive fatigue equal to your ranks in Fitness and the Prone condition.</span></p></li><li><p><span class=\"fontstyle3\">- Switch to a different stance of their choice and suffer the Immobilized condition.</span></p></li></ul><h4><span class=\"fontstyle5\">New Opportunities</span></h4><p><span class=\"fontstyle5\">(op)(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">If your weapon has the Cumbersome quality, choose one additional target with vigilance lower than or equal to your original target’s vigilance per (op)(op) spent this way.</span></p>","source":{"book":"path_of_waves","page":89},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.zK3HcHrVGitDdyHt","skill":"melee"},{"name":"Pelting Hail Style","via":"General","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>A volley of arrows on the battlefield can be deadly, but most importantly from a strategic standpoint, it is terrifying to even the staunchest veterans. Even if only one in ten shots finds its mark, the salvo rattles opponents and forces caution.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Ranged] check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(op)+: </span><span class=\"fontstyle3\">Choose a number of other characters at range 0–2 of your target equal to </span><span class=\"fontstyle4\">(op) </span><span class=\"fontstyle3\">spent this way. Each chosen character receives strife equal to the base damage of your weapon.</span></p>","source":{"book":"core_rulebook","page":181},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.y1F9eIDSu6liIhSj"},{"name":"Beseech Hida's Might","via":"General","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"ritual","rank":2,"description":"<p><span class=\"fontstyle0\"><em>Contests of strength were a favorite of the Kami Hida, and even today, spiritualists in Rokugan call upon his blessing when sanctifying an area for ritualized battle. Whether the arena is a circle for sumai or a parting of the battle lines for a field duel, it is important that it be properly respected as a place for champions to take up arms.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">Once per game session as a downtime activity or Support action, you may make a </span><span class=\"fontstyle2\">TN 2 Meditation (Fire) check </span><span class=\"fontstyle3\">targeting an area encompassing 3 range bands around yourself.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, this area becomes an </span><span class=\"fontstyle2\">arena</span><span class=\"fontstyle3\">. When a character makes a Martial Arts check in the arena during the event and does not gain strife from the check, that character reduces the TN of their next check by 1 (to a minimum of 1). This effect persists until the end of the next scene.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle5\">(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">If you succeed, the arena gains the Hallowed (fire) terrain quality until the end of the scene.</span></p><p><span class=\"fontstyle2\">(op)+: </span><span class=\"fontstyle3\">If you succeed, increase the Endurance and Composure of each character fighting a duel in the arena by 1 per (op) spent this way.</span></p><p><span class=\"fontstyle5\">(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">Reduce the TN of checks to remove the Bleeding and Dying conditions from characters within the arena by 1 per (op) spent this way (to a minimum of 1).</span></p>","source":{"book":"fields_of_victory","page":97},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.xcnbZkf9be3uhL6a","skill":"meditation"},{"name":"Cleansing Rite","via":"General","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"ritual","rank":1,"description":"<p><span class=\"fontstyle0\"><em>The ritualist sanctifies a person or group, anointing them with sacred substances that drive out unholy presences and malign sorcery.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a downtime activity, you may make a </span><span class=\"fontstyle2\">TN 3 Theology (void) check </span><span class=\"fontstyle3\">targeting up to five characters to remove spiritual contaminants from the targets before they spread. Note that this cannot remove a Shadowlands Taint disadvantage once it has taken hold, but it can prevent this spiritual contamination from taking root after a character is exposed.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, remove the Afflicted condition from the target.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle5\">(void)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">If one or more targets is an Otherworldly being, you become aware of it after completing the ritual—but you do not know which target.</span></p><p><span class=\"fontstyle5\">(void)(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">Choose one additional target per (op) spent this way.</span></p><p><span class=\"fontstyle2\">(void)(op)+: </span><span class=\"fontstyle3\">Instead of targeting characters, you may target an area that encompasses a number of range bands around you equal to (op) spent this way. Remove the Defiled terrain quality from this area. If it is a deeply unhallowed place that has long been the domain of evil, the Defiled quality returns after one day, plus additional days equal to your bonus successes.</span></p>","source":{"book":"core_rulebook","page":212},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.1lVY0jhJAeEa4Byg","skill":"theology"},{"name":"Superior Command","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":5,"kind":"title_ability","rank":1,"description":"<p><span class=\"fontstyle0\">While you are the commander of an army during a mass battle, your army’s discipline value is increased by your ranks in Command. Additionally, when making an Initiative check during a mass battle, increase the result by your ranks in Tactics.</span></p>","source":{"book":null,"page":0},"uuid":"Compendium.l5r5e-compendia-sortilege.title-abilities-l5r-sortilege.Item.TjykywguNtGuVItC"}],"peculiarities":[{"name":"Light Sleeper","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"water","types":"Physical","description":"<p><span class=\"fontstyle0\"><em>“You see these scars?” she asked. He nodded respectfully at the Hiruma. It looked like someone had run a rake down her face—then repeated the action several times.</em></span></p><p><span class=\"fontstyle0\"><em>“This is what you get when you dare slumber here. Everyone else died that night.” She closed her eyes for a moment, then opened them abruptly, startling him. “You rest your guard, you die.” She looked closely at him. “You learn to stay awake, even when you sleep. Or you join the rest of my old patrol.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Light Sleeper distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You rouse from sleep very easily, a trick considered essential in hostile territory. You are trained to awaken before danger arrives, sleep with your weapons ready, and pretend to be in a deep sleep to lure enemies closer. You can go from a deep sleep to fully alert and fighting in the blink of an eye.</span></p></li><li><p><span class=\"fontstyle0\">- When performing a check that calls on rapidly recovering from sleep (such as a Survival (water) check to detect a threatening sound while dozing or a Fitness (water) check to react even when someone else is standing watch), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"shadowlands","page":96},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.ZtoejR7hmjZ0aE8k"},{"name":"Encompassing Duty","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"earth","types":"Mental","description":"<p><em>“I will lay down my life for my family. Nothing will stand in the way of that.”</em></p><p><em>– Aina, Ashigaru of the Lion</em></p><p></p><p>The following apply to a character with the Encompassing Duty adversity:</p><ul><li><p>- You have a duty to something: your family, a friend, a cause, or some other person or ideal. This duty should manifest into at least one discernible goal, one you can work out with the GM. A goal may be to provide for your family, rescue a friend, or achieve a similar aim. You have a difficult time relaxing or focusing on tasks that do not somehow advance your goal, and this may manifest in several ways, including frustration, anger, worry, or nervousness. </p></li><li><p>- Whenever you make a check related to overcoming something that could hinder you in achieving your duty (such as a Meditation (earth) check to keep a cool head in an ambush or a Courtesy (earth) check to reason with a stubborn shopkeeper), you must choose and reroll two dice containing (su) or (ex) . After resolving the check, if you failed, you gain 1 Void point.</p></li></ul>","source":{"book":"path_of_waves","page":72},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.TP83fjX8gnxELunG"},{"name":"Travel","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"water","types":"Mental, Physical","description":"<p><span class=\"fontstyle0\"><em>The old man sat heavily on the stool outside the constabulary office. He removed his straw hat, wiped his brow with his sleeve, and returned the hat to his head. His eyes, shaded by the wide brim, looked out at Yūka. The young girl smiled.</em></span></p><p><span class=\"fontstyle0\"><em>“Young lady, I have been from one side of Rokugan to the other—from Khanbulak to the Islands of Silk and Spice—and I have seen amazing sights. I will tell you this: in all my travels, I have become convinced of three things.” He counted them off on gnarled fingers. “All crows are black, it always rains when you don’t want it to, and Rokugan’s greatest treasure—a prize without equal—is its people.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Travel passion:</span></p><ul><li><p><span class=\"fontstyle3\">- You are not unsettled by foreign customs, and you can comfortably fit in even in strange environments.</span></p></li><li><p><span class=\"fontstyle3\">- After performing a check to travel to a new location or interact with a novel thing (such as a Survival (water) check to try to identify a new plant, animal, or phenomenon, or a Seafaring (water) check to travel by boat), you remove 3 strife.</span></p></li></ul>","source":{"book":"core_rulebook","page":115},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.7keAIKn0N8wjEsGa"},{"name":"Battle Trauma","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"fire","types":"Mental, Physical","description":"<p><em>The thousand cuts I have borne<br>And the thousand I have delivered<br>Paint my dreams in red<br>Broad brushstrokes to draw pictures<br>I cannot put to paper.<br>Do my ears ring from old age<br>Or is that steel’s song and the warrior’s cry<br>Gone so long ago<br>But never gone?</em></p><p><strong>Effects:</strong> The following apply to a character with the Battle Trauma anxiety:</p><ul><li><p>-  At the start of a duel, skirmish, or mass battle, your hands shake, your body tenses up, or your mind might even lock down. You can act normally, but your unsettled state is obvious to everyone around you, and others may try to exploit it.</p></li><li><p>-  After performing a check related to battle (such as a Martial Arts [Melee] (fire) check to strike down a foe or a Tactics (fire) check to generate initiative), you receive 3 strife. (Your GM can choose not to inflict this strife after the you have taken a few turns and thematically overcome your trauma.) If this is the first time this has occurred this scene, gain 1 Void point.</p></li></ul>","source":{"book":"core_rulebook","page":131},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.jlSq86lbglLrHXp8"},{"name":"Paragon of Courage","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"fire","types":"Mental, Virtue","description":"<p><span class=\"fontstyle0\"><em>“The heroes of myth—even the ones who were not of divine blood—did not live as humans do. It is impossible to embody an ideal without surpassing some part of your own humanity.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Paragon of Courage distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You believe utterly in Courage, and others instinctively discern that your actions are genuine when you act in accordance with it.</span></p></li><li><p><span class=\"fontstyle3\">- When performing a check for which you need to convince others of, or leverage your faith in, Courage (such as a Performance check to recount a tale that impresses its importance upon others or a Martial Arts [Melee] check to take up arms for this cause), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"core_rulebook","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.trppadBbshGjbSP2"}],"titles":[{"name":"Gunsō","xp_used":24,"xp_cost":24,"in_curriculum":false,"bought_at_rank":3,"description":"<p><span class=\"fontstyle0\">While the vast majority of soldiers in a Rokugani army are ashigaru and conscripts, many samurai are called to military service, either in the armies of their own clan or in the Imperial Legions. When samurai do take to the field, they often these serve in leadership positions. While each lord's forces have their own structure and character, common titles are used throughout Rokugan to indicate similar levels of authority. When a lord gathers a large force for battle, they may nominate one or more gunsō to command the kashira who lead individual units.</span></p><p><span class=\"fontstyle0\">A gunsō is responsible for all aspects of battle readiness for the troops under their command, including the troops’ training, discipline, and equipment. When battle begins, gunsō direct their troops in accordance with commands from their superiors, meaning they have to maintain good awareness not only of their own unit but also of the broader battle unfolding around them. Perhaps most importantly, gunsō are expected to display conspicuous leadership during battle, leading their troops from the front and rallying their soldiers, keeping them in the fight even as losses mount and their morale begins to waver.</span></p><p><span class=\"fontstyle2\"><strong>Assigned By:</strong> </span><span class=\"fontstyle0\">A daimyō may assign a samurai a rank within their military forces, and samurai serving within the military rank structure may be promoted by a superior officer.</span></p><p><span class=\"fontstyle2\"><strong>Status Award:</strong> </span><span class=\"fontstyle0\">+5 (to a minimum of 20)</span></p><p><span class=\"fontstyle2\"><strong>Title Ability:</strong> Lead from the Front</span></p><h2>Curriculum</h2><table><tbody><tr><td><p>Martial Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Command</p></td><td><p>Skill</p></td></tr><tr><td><p>Government</p></td><td><p>Skill</p></td></tr><tr><td><p><a class=\"compendium-link\" data-pack=\"l5r5e.core-techniques-kata\">(kata) Rank 1-4 Kata</a></p></td><td><p>Tech. Grp.</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-shuji.Item.L5RCoreShu000020\" data-pack=\"l5r5e.core-techniques-shuji\" data-type=\"Item\" data-id=\"L5RCoreShu000020\">(shuji) Rallying Cry</a> (prereq)</p></td><td><p>Technique</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-shuji.Item.L5RCoreShu000026\" data-pack=\"l5r5e.core-techniques-shuji\" data-type=\"Item\" data-id=\"L5RCoreShu000026\">(shuji) Stirring the Embers</a> (prereq)</p></td><td><p>Technique</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-shuji.Item.L5RCoreShu000011\" data-pack=\"l5r5e.core-techniques-shuji\" data-type=\"Item\" data-id=\"L5RCoreShu000011\">(shuji) Touchstone of Courage</a> (prereq)</p></td><td><p>Technique</p></td></tr></tbody></table>","source":{"book":"emerald_empire","page":250},"uuid":"Compendium.l5r5e-compendia-sortilege.titles-l5r-sortilege.Item.2R7nNp7NWNLkVs5j"},{"name":"General","xp_used":51,"xp_cost":50,"in_curriculum":false,"bought_at_rank":5,"description":"<p><span class=\"fontstyle0\">The pinnacle of military command, a general serves as the mastermind behind all aspects of their army, seeing the will of their daimyō done through intricate planning and masterful stratagems. But there is more to a general’s duties. A general must lead by example; the expectations they have of their troops must be mirrored in their own actions. Their voice must electrify the souls of those under their command, inspiring them to charge enthusiastically to what may be their deaths. Their combat mastery must be without flaw. Their decorum and personal honor must be beyond reproach.</span></p><p><span class=\"fontstyle0\">Though it is a high honor to be given command, it can also be burdensome. Leadership is often a weary, isolating task. On their shoulders rest the will of their lord and the security of their homeland.</span></p><p><span class=\"fontstyle2\"><strong>Assigned by:</strong> </span><span class=\"fontstyle0\">A clan or family daimyō with a status of 60 or higher, often following a great military achievement by the character.</span></p><p><span class=\"fontstyle2\"><strong>Glory Award:</strong> </span><span class=\"fontstyle0\">+10</span></p><p><span class=\"fontstyle2\"><strong>Status Award:</strong> </span><span class=\"fontstyle0\">+25 (to a maximum of 85)</span></p><p><span class=\"fontstyle2\"><strong>Title Ability:</strong> Superior Command</span></p><h2>Curriculum</h2><table><tbody><tr><td><p>Social Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Martial Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Government</p></td><td><p>Skill</p></td></tr><tr><td><p>Survival</p></td><td><p>Skill</p></td></tr><tr><td><p><a class=\"compendium-link\" data-pack=\"l5r5e.core-techniques-kata\">(kata) Rank 1-2 Kata</a> (prereq)</p></td><td><p>Tech. Grp.</p></td></tr><tr><td><p><a class=\"compendium-link\" data-pack=\"l5r5e.core-techniques-rituals\">(ritual) Rank 1-3 Rituals</a> (prereq)</p></td><td><p>Tech. Grp.</p></td></tr><tr><td><p><a class=\"compendium-link\" data-pack=\"l5r5e.core-techniques-shuji\">(shuji) Rank 1-4 Shuji</a> (prereq)</p></td><td><p>Tech. Grp.</p></td></tr></tbody></table>","source":{"book":"fields_of_victory","page":133},"uuid":"Compendium.l5r5e-compendia-sortilege.titles-l5r-sortilege.Item.mHaV3dj76eYzJyGb"}],"bonds":[],"signature_scrolls":[],"gear":[{"name":"Club","quantity":1,"description":"<p><span class=\"fontstyle0\">The humble club is perhaps the oldest weapon in Rokugan—at least among humans. Often little more than a length of stout wood or shaped stone, a club can be fashioned with available materials by nearly anyone. While a club can certainly be used to kill, doing so takes some work on the part of the wielder</span>.</p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.ElFJfEcGvWe6A5yU","damage":5,"deadliness":2,"range":"0-1","grip_2":"Damage +1","skill":"melee","category":"Blunt Weapons","rarity":"1","zeni":"1 bu","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Katana","quantity":1,"description":"<p><span class=\"fontstyle0\">As much a work of art as it is a weapon, the katana is perhaps the most revered weapon in Rokugan. It has an elegant, slightly curved blade between three and four feet long, made of steel that is specially folded during its creation. This unique forging style ensures that the inner part of the blade remains springy and soft while the outside is as hard as tempered steel. Each sword likely has a history and legacy, and it is a constant reminder of the weight that destiny has placed upon its bearer’s shoulders as a samurai of Rokugan</span>.</p>","source":{"book":"core_rulebook","page":232},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.BhKwwnN5UHI5rZpp","damage":4,"deadliness":5,"range":"1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"20 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Knife","quantity":1,"description":"<p><span class=\"fontstyle0\">Knives come in a dizzying array of types and styles, from the familiar crudely constructed knife in a peasant’s kitchen to the deadly combat knives samurai take into battle. Those particularly designed for combat—like the aiguchi—are often equipped with small hand guards to make them more useful in the field.</span></p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.n8xA05Fb9WpXg3oo","damage":2,"deadliness":4,"range":"0","grip_2":"Deadliness +2","skill":"melee","category":"Hand Weapons","rarity":"1","zeni":"1 koku","properties":[{"id":"L5RCorePro000001","name":"Razor-Edged"},{"id":"L5RCorePro000005","name":"Concealable"},{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Tetsubō","quantity":1,"description":"<p><span class=\"fontstyle0\">Long and narrow, a tetsubō can be as tall as a human and normally is constructed of iron or hardwood. Above its grip, a tetsubō is covered in steel, iron, or even jade spikes or studs that add to the weapon’s lethality and crush armor or plated carapace with ease.</span></p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.CW6h0NSzTEhimQXw","damage":7,"deadliness":3,"range":"1-2","grip_1":"N/A","skill":"melee","category":"Blunt Weapons","rarity":"5","zeni":"20 koku","properties":[{"id":"L5RCorePro000006","name":"Cumbersome"},{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Wakizashi","quantity":1,"description":"<p><span class=\"fontstyle0\">Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</span></p>","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Kamayari","quantity":1,"description":"<p><span class=\"fontstyle0\">A </span><span class=\"fontstyle2\">kamayari </span><span class=\"fontstyle0\">is a spear with a hooked protrusion on one or both sides of the blade, similar to a ji. While the hook’s most obvious applications are blocking attacks and dragging foes off horseback, it also has practical noncombat applications. A shinobi might swing from a sturdy tree limb using the hook or might use it to climb a high fence. If the spear shaft has holes in it, the shinobi can use the shaft to measure distances or can slot bars into the holes to use it as a ladder. Finally, the hook is useful for carrying items on long walks.</span></p>","source":{"book":"court_of_stones","page":110},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.PsmRwhHYBz0daKi5","damage":4,"deadliness":3,"range":"2","grip_1":"N/A","skill":"melee","category":"Specialist Weapons","rarity":"7","zeni":"8 koku","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000007","name":"Snaring"}]},{"name":"Lacquered Armor","quantity":1,"description":"<p><span class=\"fontstyle0\">Heavier than ashigaru armor, lacquered armor is worn by samurai who desire a good mix of protection and grandeur, and is just at home at war as at a martial ceremony. These suits are made of thick leather or steel plates stitched or riveted to a leather backing. They protect the torso, head, upper arms, and groin, and the legs above the knee. They can also include a helmet and mask, though these are not considered integral.</span></p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.sPKkavq6O0SoxiPj","armor":{"physical":4,"supernatural":0},"rarity":"6","zeni":"25 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000006","name":"Cumbersome"},{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Traveling Clothes","quantity":1,"description":"<p><span class=\"fontstyle0\">Traveling clothes ordinarily consist of roughspun garments designed to resist wear and tear. They can be anything from robes to a kimono or jacket and leggings and are often accentuated with a hat or cloak</span>.</p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.zcsgspz4VluSMeI0","armor":{"physical":2,"supernatural":0},"rarity":"2","zeni":"2 bu","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000012","name":"Mundane"},{"id":"L5RCorePro000016","name":"Subtle"}]},{"name":"Traveling pack","quantity":1,"description":"<p><span class=\"fontstyle0\">Blanket, bowl, chopsticks, four days of travel rations, flint and tinder, and any three other items of the player’s choice that are rarity 4 or lower.</span></p>","source":{"book":"core_rulebook","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.Rex7fGo6R1KuUhQJ","rarity":"1","zeni":"10 koku","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Kubi Bukuro","quantity":1,"description":"<p>These are simple net bags used to carry the severed head of an enemy, which is considered both a trophy and a good omen. Lion Clan samurai use them to carry their trophies without touching dead flesh, but the Kuni family uses them for collecting samples of Shadowlands creatures for study.</p>","source":{"book":"core_rulebook","page":242},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.6J25vJx1tVirgXf1","rarity":"2","zeni":"2 zeni","properties":[{"id":"L5RCorePro000011","name":"Wargear"}]}]},{"xp":279,"label":"General, Rank 6","rank":6,"school":"Hida Defender School","foundry_id":"l4VWZnBMThDd2yR6","rings":{"air":2,"earth":4,"fire":2,"water":3,"void":3},"skills":{"artisan":{"aesthetics":2,"composition":1,"design":0,"smithing":0},"martial":{"fitness":3,"melee":3,"ranged":3,"unarmed":2,"meditation":3,"tactics":5},"scholar":{"culture":0,"government":4,"medicine":0,"sentiment":0,"theology":3},"social":{"command":4,"courtesy":1,"games":3,"performance":0},"trade":{"commerce":0,"labor":2,"seafaring":1,"skulduggery":1,"survival":3}},"social":{"honor":45,"glory":44,"status":30,"ninjo":"Longs to travel Rokugan, or possibly even beyond.","giri":"Hiruma Nobuyasu is their lord. They insist that she command her unit, defending the Kaiu Wall.","bushido_tenets":{"paramount":"Courage","less_significant":"Sincerity"}},"derived":{"endurance":12,"composure":14,"focus":4,"vigilance":3,"void_points":3},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[{"label":"Martial Arts [Ranged] +1 (0 -> 1)","type":"skill","skill":"ranged","ring":"void","at_rank":1,"xp":2,"in_curriculum":true},{"label":"Martial Arts [Melee] +1 (1 -> 2)","type":"skill","skill":"melee","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Martial Arts [Unarmed] +1 (0 -> 1)","type":"skill","skill":"unarmed","ring":"void","at_rank":1,"xp":2,"in_curriculum":true},{"label":"Martial Arts [Ranged] +1 (1 -> 2)","type":"skill","skill":"ranged","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Command +1 (1 -> 2)","type":"skill","skill":"command","ring":"void","at_rank":2,"xp":4,"in_curriculum":true},{"label":"Void +1 (2 -> 3)","type":"ring","ring":"void","at_rank":2,"xp":9,"in_curriculum":false},{"label":"Labor +1 (0 -> 1)","type":"skill","skill":"labor","ring":"void","at_rank":2,"xp":2,"in_curriculum":true},{"label":"Command +1 (2 -> 3)","type":"skill","skill":"command","ring":"void","at_rank":2,"xp":6,"in_curriculum":true},{"label":"Composition +1 (0 -> 1)","type":"skill","skill":"composition","ring":"void","at_rank":2,"xp":2,"in_curriculum":false},{"label":"Command +1 (4 -> 5)","type":"skill","skill":"command","ring":"void","at_rank":1,"xp":10,"in_curriculum":true,"via":"Gunsō"},{"label":"Government +1 (0 -> 1)","type":"skill","skill":"government","ring":"void","at_rank":1,"xp":2,"in_curriculum":true,"via":"Gunsō"},{"label":"Fitness +1 (2 -> 3)","type":"skill","skill":"fitness","ring":"void","at_rank":3,"xp":6,"in_curriculum":true},{"label":"Seafaring +1 (0 -> 1)","type":"skill","skill":"seafaring","ring":"void","at_rank":3,"xp":2,"in_curriculum":true},{"label":"Labor +1 (1 -> 2)","type":"skill","skill":"labor","ring":"void","at_rank":3,"xp":4,"in_curriculum":true},{"label":"Martial Arts [Melee] +1 (2 -> 3)","type":"skill","skill":"melee","ring":"void","at_rank":3,"xp":6,"in_curriculum":true},{"label":"Earth +1 (3 -> 4)","type":"ring","ring":"earth","at_rank":4,"xp":12,"in_curriculum":false},{"label":"Water +1 (1 -> 2)","type":"ring","ring":"water","at_rank":4,"xp":6,"in_curriculum":false},{"label":"Water +1 (2 -> 3)","type":"ring","ring":"water","at_rank":4,"xp":9,"in_curriculum":false},{"label":"Government +1 (1 -> 2)","type":"skill","skill":"government","ring":"void","at_rank":4,"xp":4,"in_curriculum":true},{"label":"Meditation +1 (0 -> 1)","type":"skill","skill":"meditation","ring":"void","at_rank":4,"xp":2,"in_curriculum":true},{"label":"Meditation +1 (1 -> 2)","type":"skill","skill":"meditation","ring":"void","at_rank":4,"xp":4,"in_curriculum":true},{"label":"Government +1 (2 -> 3)","type":"skill","skill":"government","ring":"void","at_rank":4,"xp":6,"in_curriculum":true},{"label":"Martial Arts [Ranged] +1 (2 -> 3)","type":"skill","skill":"ranged","ring":"void","at_rank":1,"xp":6,"in_curriculum":true,"via":"General"},{"label":"Government +1 (3 -> 4)","type":"skill","skill":"government","ring":"void","at_rank":1,"xp":8,"in_curriculum":true,"via":"General"},{"label":"Martial Arts [Unarmed] +1 (1 -> 2)","type":"skill","skill":"unarmed","ring":"void","at_rank":1,"xp":4,"in_curriculum":true,"via":"General"},{"label":"Games +1 (0 -> 1)","type":"skill","skill":"games","ring":"void","at_rank":1,"xp":2,"in_curriculum":true,"via":"General"},{"label":"Games +1 (1 -> 2)","type":"skill","skill":"games","ring":"void","at_rank":1,"xp":4,"in_curriculum":true,"via":"General"},{"label":"Games +1 (2 -> 3)","type":"skill","skill":"games","ring":"void","at_rank":1,"xp":6,"in_curriculum":true,"via":"General"},{"label":"Meditation +1 (2 -> 3)","type":"skill","skill":"meditation","ring":"void","at_rank":1,"xp":6,"in_curriculum":true,"via":"General"},{"label":"Aesthetics +1 (0 -> 1)","type":"skill","skill":"aesthetics","ring":"void","at_rank":5,"xp":2,"in_curriculum":false},{"label":"Survival +1 (2 -> 3)","type":"skill","skill":"survival","ring":"void","at_rank":5,"xp":6,"in_curriculum":true},{"label":"Theology +1 (0 -> 1)","type":"skill","skill":"theology","ring":"void","at_rank":5,"xp":2,"in_curriculum":true},{"label":"Tactics +1 (2 -> 3)","type":"skill","skill":"tactics","ring":"void","at_rank":5,"xp":6,"in_curriculum":true},{"label":"Tactics +1 (3 -> 4)","type":"skill","skill":"tactics","ring":"void","at_rank":5,"xp":8,"in_curriculum":true},{"label":"Tactics +1 (4 -> 5)","type":"skill","skill":"tactics","ring":"void","at_rank":5,"xp":10,"in_curriculum":true},{"label":"Theology +1 (1 -> 2)","type":"skill","skill":"theology","ring":"void","at_rank":5,"xp":4,"in_curriculum":true},{"label":"Theology +1 (2 -> 3)","type":"skill","skill":"theology","ring":"void","at_rank":5,"xp":6,"in_curriculum":true},{"label":"Aesthetics +1 (1 -> 2)","type":"skill","skill":"aesthetics","ring":"void","at_rank":5,"xp":4,"in_curriculum":false}],"techniques":[{"name":"Striking as Earth","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"kata","rank":1,"description":"<p><span class=\"fontstyle0\"><em>After striking, the bushi roots themself to the ground, hunkering down to make sure their armor takes the brunt of a hit or raising a weapon in a warding position where it can deflect harm without being damaged.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee, Ranged, or Unarmed] (earth) check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth)(op)+: </span><span class=\"fontstyle3\">Treat your physical resistance as 1 higher per </span><span class=\"fontstyle4\">(op) </span><span class=\"fontstyle3\">spent this way until the beginning of your next turn.</span></p>","source":{"book":"core_rulebook","page":178},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.aKTfAZXbHo77kHOq"},{"name":"Lord Hida’s Grip (Crab)","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>The Kami Hida, patron of the Crab Clan, was a legendary slayer of monsters. He beheaded the massive demon that once menaced the rose-marble palace, and ripped out one skull of the two-headed Kabuto no Oni and crushed the other head with it. However, Hida was no mere brute: he was cunning, killing monsters by exploiting their weaknesses. Warriors of the Crab Clan train in similar techniques. They turn their foes' great weight against them by pinning or strategically damaging specific body parts.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As an Attack action, you may make a </span><span class=\"fontstyle2\">Fitness (void) check </span><span class=\"fontstyle3\">targeting one creature of silhouette 3 or larger at range 0–1. The TN of the check is equal to the silhouette of the target (to a minimum of 1).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, your target suffers the Immobilized condition. If you succeed, you count as granting assistance (see page 26) to all characters who perform Attack actions against your target. This effect persists until the beginning of your next turn.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(void)(op): </span><span class=\"fontstyle3\">Your target must resist with a </span><span class=\"fontstyle2\">Fitness check </span><span class=\"fontstyle3\">or suffer physical damage equal to its silhouette, ignoring its resistance, and the Prone condition. The TN of this check is equal to your school rank.</span></p>","source":{"book":"core_rulebook","page":176},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.ERExWdY04GNvu3p0","skill":"fitness"},{"name":"Way of the Crab","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p><span class=\"fontstyle0\">Ignore the Cumbersome quality of armor you wear.</span></p><p><span class=\"fontstyle0\">Once per round, before making a check to resist a critical strike, you may reduce the severity of that critical strike by the physical resistance of your armor plus your school rank (to a minimum of 0).</span></p>","source":{"book":"core_rulebook","page":57},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.7LHxYqmpqMUETLEq"},{"name":"Appreciate the Scenery","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<p><span class=\"fontstyle0\"><em>In many lands, including Rokugan, the beauty of the natural world inspires art, poetry, and other works of note, even (or perhaps especially) when it is stark and dangerous. When on a long and perilous journey into foreign lands where deadly intrigues surely await, finding beauty in the rougher parts of the world can be a much-needed source of solace.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Support action check targeting another character, if you and the character you are targeting are in Dangerous, Entangling, Hallowed, Imbalanced, or Obscuring terrain, you may spend (op) as follows:</span></p><p><span class=\"fontstyle2\">(earth) or</span><span class=\"fontstyle4\"> (water)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">You and your target each remove strife equal to your ranks in Composition.</span></p><p><span class=\"fontstyle2\">(air) or (fire)</span><span class=\"fontstyle4\">(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">You and your target gain the Emboldened condition (see page 133).</span></p><p><span class=\"fontstyle2\">(void)(op): </span><span class=\"fontstyle3\">Your and your target gain the Centered condition (see page 133).</span></p>","source":{"book":"children_of_the_five_winds","page":116},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.gbUpw4ife9RdWbK9"},{"name":"Honest Assessment","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<p><span class=\"fontstyle0\"><em>Honesty is a virtue of Bushidō, but direct honesty is often seen as rudeness among the samurai—instead, one is expected to find a polite way to imply one’s meaning to spare the feelings of the other involved. As a result, directness can be something of a rare and valuable commodity.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may make a </span><span class=\"fontstyle2\">TN 2 Courtesy (earth) check </span><span class=\"fontstyle3\">to appraise the weaknesses of a character.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, choose one of the target’s known disadvantages. The target does not apply that disadvantage to their checks until the end of the scene.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(earth)(op)+: </span><span class=\"fontstyle3\">Choose one additional disadvantage per (op) spent this way.</span></p><p><span class=\"fontstyle5\">(earth)(op)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">Reduce the TN of the target’s next skill check using the ring the disadvantage is attached to by 2.</span></p>","source":{"book":"core_rulebook","page":216},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.t427qRaOh42dfbVM","skill":"courtesy"},{"name":"Rushing Avalanche Style","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>When adopting this style, the bushi strikes with reckless abandon using a heavy armament. Thanks to the sheer weight of their weapon and the ferocity of their strikes, even a glancing blow can cause serious harm, and a telling blow usually ends the battle.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee] check using a blunt weapon, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(op): </span><span class=\"fontstyle3\">If you fail with a shortfall of two or less, your target suffers physical damage equal to your ranks in Fitness.</span></p><p><span class=\"fontstyle2\">(op): </span><span class=\"fontstyle3\">If you succeed and your target is Prone, increase the damage you deal by your ranks in Fitness.</span></p>","source":{"book":"core_rulebook","page":180},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.EZG0aAg9oxEUou5u"},{"name":"Staggering Shot","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>Putting an arrow at a foe’s feet can cause them to stumble or trip, and an experienced archer knows how to take full advantage of this, planting bolts to break an</em></span><em> </em><span class=\"fontstyle0\"><em>enemy’s stride or pinning their clothes to slow them down, making any approach extremely treacherous.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you perform a Martial Arts [Ranged] check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth) or (fire)(op)(op): </span><span class=\"fontstyle3\">Your target treats all terrain as having the Dangerous quality. This effect persists until the end of your next turn.</span></p><p><span class=\"fontstyle2\">(air) or (water)(op)(op): </span><span class=\"fontstyle3\">Your target treats all terrain as having the Entangling quality. This effect persists until the end of your next turn.</span></p>","source":{"book":"path_of_waves","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.6N5n9fweaz1CbLCu"},{"name":"Touchstone of Courage","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"shuji","rank":3,"description":"<p><span class=\"fontstyle0\"><em>Armies are rarely routed in the field; instead, most collapse when morale becomes impossible to maintain. As panic rises in the ranks, soldiers look to leaders to set an example. The character does just this, speaking to the importance of duty to bring their troops back from the edge of chaos.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may make a </span><span class=\"fontstyle2\">TN 4 Command (earth) check </span><span class=\"fontstyle3\">targeting any number of characters (or your cohort during a mass battle).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed during an intrigue, duel, or skirmish conflict, each target increases their composure by your Earth Ring. This effect persists until the end of the scene. If you succeed during a mass battle, increase your army’s discipline by your Earth Ring plus your bonus successes. This effect persists until the end of the scene.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(earth)(op)(op): </span><span class=\"fontstyle3\">During an intrigue, duel, or skirmish, each target removes strife equal to your Earth Ring.</span></p><p><span class=\"fontstyle2\">(earth)(op)(op): </span><span class=\"fontstyle3\">During a mass battle, your army removes panic equal to your Earth Ring.</span></p>","source":{"book":"core_rulebook","page":217},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.fFxQOBXLb9ol9owk","skill":"command"},{"name":"Thunderbolt Style","via":"Gunsō","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":4,"description":"<p><span class=\"fontstyle0\"><em>Hitting a target with a thrown weapon is difficult; hitting more than one target with the same throw is even harder. However, a warrior of sufficient skill can potentially harm multiple targets with a properly placed spear or ax throw, the projectile striking one foe and caroming off at an unexpected angle or causing the primary target to collapse into another. Such an unexpected tactic can catch an entire unit off guard, forcing them to spread out when staying close together would be advantageous.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make an Attack action check in which you throw your weapon, you may spend (op) as follows:</span></p><p><span class=\"fontstyle4\">(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">Choose another character at range 0–1 of your target with vigilance lower than your ranks in Fitness plus (op) spent this way. That character suffers damage equal to your weapon’s base damage. You can activate this opportunity multiple times, choosing different characters to affect each time.</span></p>","source":{"book":"children_of_the_five_winds","page":110},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.rwDHm7Q3qmjDJZRg"},{"name":"Deflective Defense","via":"Gunsō","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":3,"description":"<p><span class=\"fontstyle0\"><em>Large-enough weapons can, in a pinch, serve as shields against missile attacks. If a warrior plants their weapon in the ground and takes cover behind it with a narrow profile, even a </em></span><span class=\"fontstyle2\"><em>bisentō </em></span><span class=\"fontstyle0\"><em>makes the likelihood of a lethal hit with an arrow or dart far lower.</em></span></p><p><span class=\"fontstyle3\"><strong>Activation:</strong> </span><span class=\"fontstyle0\">As a Movement and Support action using a readied Cumbersome weapon, you may make a </span><span class=\"fontstyle3\">TN 2 Martial Arts [Melee] (earth) check</span><span class=\"fontstyle0\">.</span></p><p><span class=\"fontstyle3\"><strong>Effects:</strong> </span><span class=\"fontstyle0\">If you succeed, treat your physical resistance against attacks made by characters at range 2–6 as increased by your ranks in Fitness.\\</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle3\">(earth)(op)(op): </span><span class=\"fontstyle0\">After you defend against physical damage from an attack made by a character at range 2–6, that character suffers 2 strife.</span></p>","source":{"book":"path_of_waves","page":88},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.eC8kPJscUbiEoE7c","skill":"melee"},{"name":"Tactical Assessment","via":"Gunsō","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>Akodo’s </em></span><span class=\"fontstyle2\"><em>Leadership </em></span><span class=\"fontstyle0\"><em>and Bayushi’s </em></span><span class=\"fontstyle2\"><em>Lies </em></span><span class=\"fontstyle0\"><em>agree on a few topics, for both leaders were practical to a certain degree, even if Akodo famously scorned many of Bayushi’s methods. As the scholar Hida Fuyuko noted in her revelatory commentary on </em></span><span class=\"fontstyle2\"><em>Leadership</em></span><span class=\"fontstyle0\"><em>’s lessons for commanders on the Kaiu Wall, the most famous meeting of these two minds comes on the matter of preparation: battles are not won in the field, but in the leadup to the conflict. Even in small clashes, the warrior who better understands the terrain, the strength of their own forces, and the composition of the enemy’s troops is usually victorious.</em></span></p><p><span class=\"fontstyle3\"><strong>Activation:</strong> </span><span class=\"fontstyle2\">When you make an Initiative check, you may spend</span><span class=\"fontstyle4\"> (op) </span><span class=\"fontstyle2\">in the following way:</span></p><p><span class=\"fontstyle3\">(air)(op): </span><span class=\"fontstyle2\">Choose an enemy in the conflict. Learn one of their advantages (of their choice) and their physical or supernatural resistance (your choice).</span></p><p><span class=\"fontstyle3\">(earth)(op): </span><span class=\"fontstyle2\">Choose a character in the conflict. They do not apply any of their disadvantages to their checks until the end of their first turn.</span></p><p><span class=\"fontstyle3\">(water)(op): </span><span class=\"fontstyle2\">Choose a piece of terrain in the scene (see </span><span class=\"fontstyle3\">Terrain </span><span class=\"fontstyle2\">on page 267). Until the start of your first turn, it counts as having the Obscuring quality for Attack action checks targeting you and your allies.</span></p><p><span class=\"fontstyle3\">(fire)(op): </span><span class=\"fontstyle2\">Choose a character in the conflict and one of their advantages you know. Until the end of their first turn, they apply that advantage to all of their checks.</span></p>","source":{"book":"core_rulebook","page":178},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.TcFVNDk57aKGpLR2"},{"name":"Rallying Cry","via":"Gunsō","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"shuji","rank":3,"description":"<p><span class=\"fontstyle0\"><em>The leader roars, calling their troops to battle, and the voice of an army echoes around them as the single cry is joined by many. As one, the troops surge forward to claim victory or perish in the attempt.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may make a </span><span class=\"fontstyle2\">TN 2 Command (fire) </span><span class=\"fontstyle3\">or </span><span class=\"fontstyle2\">Performance (fire) check </span><span class=\"fontstyle3\">targeting any number of characters in the scene (or one cohort in a mass battle).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, the targets are energized and excited by your rhetoric. After </span><span class=\"fontstyle2\">Step 5: Choose Kept Dice</span><span class=\"fontstyle3\">, each target adds a kept (ring) set to an (op)(st) result. This effect persists until the end of your next turn.</span></p><h4><span class=\"fontstyle5\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(fire)(op)+: </span><span class=\"fontstyle3\">In a skirmish, each enemy in the scene suffers 1 strife per (op) spent this way.</span></p><p><span class=\"fontstyle2\">(fire)(op)+: </span><span class=\"fontstyle3\">In a mass battle, the enemy army suffers 1 panic per (op) spent this way.</span> <br style=\" font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: 2; text-align: -webkit-auto; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px; \"></p>","source":{"book":"core_rulebook","page":219},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.4Z888LVUKQoDU4n8","skill":"command,performance"},{"name":"Lead from the Front","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":3,"kind":"title_ability","rank":1,"description":"<p><span class=\"fontstyle0\">When you defeat an opponent in a clash, your cohort removes panic equal to the opponent’s glory rank.</span></p><p><span class=\"fontstyle0\">Once per round when you succeed at an Attack action check during a mass battle, your cohort removes panic equal to half of the attrition you inflict.</span></p>","source":{"book":null,"page":0},"uuid":"Compendium.l5r5e-compendia-sortilege.title-abilities-l5r-sortilege.Item.YTRyf5NAEdnGa2K1"},{"name":"Great Anvil's Measure","xp_used":3,"xp_cost":3,"in_curriculum":false,"bought_at_rank":3,"kind":"shuji","rank":2,"description":"<p><span class=\"fontstyle0\"><em>A proud leader often draws attention to themselves in battle, and a leader both proud and skilled does so to draw their enemy into attacking them—especially when the enemy would rather attack elsewhere. When the leader’s troops are properly readied, and especially when they are in a highly defensible location, such an attack against them is doomed to fail.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a check to perform a Guard action in a skirmish (see page 264 of the core rulebook) or a Reinforce action in a mass battle (see page 279 of the core rulebook), you may spend (op) as follows:</span></p><p><span class=\"fontstyle2\">(earth)(op)+ (Guard): </span><span class=\"fontstyle3\">Choose any number of characters in the scene with focus lower than or equal to your ranks in Performance plus 2 per (op) spent this way. Each chosen character must receive strife equal to your ranks in Performance to perform an Attack or Scheme action targeting any character other than you. This effect persists until the end of your next turn.</span></p><p><span class=\"fontstyle2\">(earth)(op)+ (Reinforce): </span><span class=\"fontstyle3\">Choose any number of leaders in the enemy army with focus lower than or equal to your ranks in Performance plus 2 per (op) spent this way. The enemy army receives panic equal to your ranks in Performance each time any of those leaders performs an Attack or Scheme action targeting any cohort other than yours. This effect persists until the end of your next turn.</span></p>","source":{"book":"fields_of_victory","page":100},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.F4ukKaPLuPJCCDKe"},{"name":"Improvised Assault","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":3,"kind":"kata","rank":3,"description":"<p><span class=\"fontstyle0\"><em>The character adapts something in their environment for use as an improvised weapon that suits their own fighting style. This might mean blocking hits with a chair like a shield, swinging a heavy branch like a club, or even wielding an umbrella with a swordmaster’s skill. Such improvised weapons rarely survive combat, but even if a broken sake bottle won’t hold an edge for long, a single good stab can often end a fight.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Movement and Support action, you may make a </span><span class=\"fontstyle2\">TN 2 Tactics (water) </span><span class=\"fontstyle3\">or </span><span class=\"fontstyle2\">Smithing (water) check </span><span class=\"fontstyle3\">using a readied improvised weapon.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, you may choose a Martial Arts [Melee] weapon profile for a weapon similar in shape to the improvised weapon (the GM has discretion over whether the substitution is appropriate). Treat the improvised weapon as having that profile, with its damage and deadliness reduced by 1. This effect persists until the end of the scene, at which point the improvised weapon gains the Destroyed quality.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(water)(op)(op): </span><span class=\"fontstyle3\">You may immediately perform a Strike action using the readied weapon.</span></p><p><span class=\"fontstyle2\">(water)(op)(op)(op): </span><span class=\"fontstyle3\">If you succeed, choose one of the following item qualities: Cumbersome, Razor-Edged, or Snaring. The weapon is treated as having that quality.</span></p>","source":{"book":"path_of_waves","page":87},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.pQPOCwe6xFiuPyu7","skill":"tactics,smithing"},{"name":"Iron in the Mountains Style","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":3,"kind":"kata","rank":4,"description":"<p><span class=\"fontstyle0\"><em>The bushi strikes with crushing force, breaking their enemy’s footing and knocking them to the ground with an overwhelming blow or sweeping their stance out from underneath them with a well-placed kick.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee, Ranged, or Unarmed] (Earth) check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth)(op)+: </span><span class=\"fontstyle3\">One target of your action must resist with a </span><span class=\"fontstyle2\">TN 3 Fitness check ((air) 1, (water) 4) </span><span class=\"fontstyle3\">or suffer the Prone condition and fatigue equal to their shortfall. Increase the TN of the check to resist by 1 per (op) spent this way.</span></p>","source":{"book":"core_rulebook","page":176},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.B60KpdAhSAXaNhSt"},{"name":"Iron Shell Style","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":3,"kind":"kata","rank":3,"description":"<p><span class=\"fontstyle0\"><em>To defend against a single, predictable blow, a warrior can dig in, rooting themself and dispersing the force as it comes. Such a complete defense is exhausting to maintain, but it can keep a fighter on their feet when they otherwise would surely have fallen.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you perform a Guard action, if you have not moved any range bands this turn, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(earth) or (void)(op)+: </span><span class=\"fontstyle3\">Choose one character you can perceive per (op) spent this way. The next time you defend against physical damage from that character, your fatigue cannot be increased to a value greater than your endurance. This effect persists until the end of your next turn.</span></p>","source":{"book":"path_of_waves","page":86},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.2gfStxWLxFx4GZO9"},{"name":"Wanderer's Resolve","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":3,"kind":"shuji","rank":1,"description":"<p><span class=\"fontstyle0\"><em>A samurai with a lord can find resolve in the loyalty they feel, but a samurai with no lord has no easy wellspring from which to draw resolve. This hardship and isolation, however, can lead a rōnin</em></span><em> to discover a certainty</em><span class=\"fontstyle0\"><em> all their own, for if they do not act, no one else will. The lives of their friends—of those who depend on them—rest solely in their hands.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">Once per scene as a Support action, if you are in a Void stance, you may focus on protecting what is important to you.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">You remove 3 fatigue and 3 strife, plus 3 fatigue and 3 strife for each Compromised or Incapacitated character in the scene with whom you share a bond (see </span><span class=\"fontstyle2\">Bonds</span><span class=\"fontstyle3\">, on page 187).</span></p>","source":{"book":"path_of_waves","page":95},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.FpyARQtMdf6V8HSY"},{"name":"Striking as Void","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":4,"kind":"kata","rank":5,"description":"<p><span class=\"fontstyle0\"><em>The future is part of Void’s domain, infinite in possibility and unfathomable in depth. Because of its formlessness, one cannot scheme to undermine the uncertain future—but the instant it takes shape, an action is vulnerable to countermeasures. The bushi rests until the last possible second, allowing the potential energy of their strike to take shape only after it is too late for their enemy to respond.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Melee, Ranged, or Unarmed] (void) check, you may spend (op) in the following ways:</span></p><p><span class=\"fontstyle2\">(void)(op): </span><span class=\"fontstyle3\">Immediately switch to a different stance of your choice.</span></p><p><span class=\"fontstyle2\">(void)(op): </span><span class=\"fontstyle3\">If you fail, you may perform another action. This must be an action you have not yet performed this turn. You can only activate this opportunity once per round.</span></p>","source":{"book":"core_rulebook","page":178},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.0Yx0bHZSdayqSMeX"},{"name":"Eyeless Sight Shot","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":4,"kind":"kata","rank":4,"description":"<p><span class=\"fontstyle0\"><em>To hit a target without seeing it is a masterful feat for any warrior who specializes in projectile weapons. Whether by firing through dense underbrush to hit a deer by the sound of its steps or banking a slingstone off a wall to hit a foe when you feel their heavy footfalls shake the floorboards, there are many ways to use one’s other senses to place a shot.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As an Attack and Movement action using a readied ranged weapon, you may make a </span><span class=\"fontstyle2\">Martial Arts [Ranged] (void) check </span><span class=\"fontstyle3\">targeting one character within your weapon’s range to whom you do not have direct line of sight. The TN of the check is equal to the target’s vigilance.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, your target suffers physical damage equal to your weapon’s base damage and receives strife equal to your bonus successes.</span></p>","source":{"book":"path_of_waves","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.hrIV8L0Ta8YQ8SnO","skill":"ranged"},{"name":"Battle in the Mind","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":4,"kind":"kata","rank":3,"description":"<p><span class=\"fontstyle0\"><em>As two masters of any martial art square off before a duel, each seeks to predict the other’s angle of attack and strategy, and the ways their predictions might be foiled by the opponent’s.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make an Initiative check for a duel using your Void Ring, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(void)(op)(op): </span><span class=\"fontstyle3\">You name two rings, then your opponent must name one of those two rings. When your opponent selects their stance during their first turn of the duel, they cannot select the ring they named as their stance.</span></p><p><span class=\"fontstyle2\">(void)</span><span class=\"fontstyle4\">(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">Choose a technique category. Learn one of your opponent’s known techniques of that category (chosen by the opponent) per (op) spent this way</span>.</p>","source":{"book":"core_rulebook","page":174},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.RdCEGT9Oy4wXvAep"},{"name":"Foreseen Need","xp_used":3,"xp_cost":3,"in_curriculum":false,"bought_at_rank":4,"kind":"shuji","rank":4,"description":"<p><span class=\"fontstyle0\"><em>Artisans with an open mind and an eye to the future are always working on things they may need one day. A little preparation and anticipation can pay off greatly at the right moment.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may make a </span><span class=\"fontstyle2\">TN 1 Artisan (void) check</span><span class=\"fontstyle3\">.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, you recall that you had foreseen the need for an item with a rarity equal to 1 plus your bonus successes on the check. Spend one Void point to instantly reveal one item you could have crafted, as long as it is reasonable (e.g., you could be carrying it on your person or have it in your quarters, you had access to the resources to craft it over the past month).</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle5\">(void)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">Double the rarity of the target item, but the item must be of a perishable nature or one with only sentimental value.</span></p>","source":{"book":"court_of_stones","page":119},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.l5hl19YeCvDCjKEN","skill":"artisan"},{"name":"A Samurai’s Fate","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":4,"kind":"shuji","rank":4,"description":"<p><span class=\"fontstyle0\"><em>A leader asks their warriors for the final service all samurai must someday render to their lord: to lay down their lives that others might live. Even as they fall in battle, their shed blood waters the fields that will grow a thousand victories.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As an action, you make a </span><span class=\"fontstyle2\">TN 5 Command (void) check </span><span class=\"fontstyle3\">targeting any number of characters (or your cohort, during a mass battle).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed during a skirmish, each target ignores any critical strikes with severity lower than your Void Ring plus your bonus successes. This effect persists until the end of the scene (at which point the injuries take effect). If you succeed during a mass battle, your army counts as having the Fearless Army ability, below:</span></p><p><span class=\"fontstyle2\"><em>Fearless Army</em>: </span><span class=\"fontstyle3\">At the end of each round, your army removes panic equal to your glory rank. This effect persists until the end of the scene.</span></p>","source":{"book":"core_rulebook","page":222},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.8Uy8s9BRJL9PEAQJ","skill":"command"},{"name":"Pillar of Calm","via":"General","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"shuji","rank":4,"description":"<p><span class=\"fontstyle0\"><em>The character calls for reason to prevail and swords to be sheathed, appealing to a common ideal or greater threat that stands before the belligerent parties.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Scheme and Support action, you may make a </span><span class=\"fontstyle2\">Command (earth) check </span><span class=\"fontstyle3\">targeting a number of characters up to your Earth Ring times your school rank. The TN of this check is equal to the highest strife among the targets.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed while targeting all of the leaders involved in a conflict, you may de-escalate the conflict one level (from a mass battle to a skirmish, a skirmish to a duel, or a duel to an intrigue).</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(earth)(op)(op)+: </span><span class=\"fontstyle3\">You may de-escalate the conflict by one additional level per (op)(op) spent this way.</span></p>","source":{"book":"core_rulebook","page":216},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.ep7mRJxHHPHofW4X","skill":"command"},{"name":"Landslide Strike","via":"General","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>Lashing out at the foe’s legs, the warrior forces their enemy to either abandon their stance or be knocked from their feet. This tactic is especially effective on uneven ground, as the enemy must watch their footing or risk even further injury.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As an Attack and Scheme action, you may make a </span><span class=\"fontstyle2\">Martial Arts [Melee] ((earth) </span><span class=\"fontstyle3\">or </span><span class=\"fontstyle2\">(water)) check </span><span class=\"fontstyle3\">targeting one character in your weapon’s range. The TN is equal to the target’s vigilance. If your target is in Dangerous, Entangling, or Obscuring terrain, the TN is 1 instead.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, your target must choose one of the following:</span></p><ul><li><p><span class=\"fontstyle3\">- Receive fatigue equal to your ranks in Fitness and the Prone condition.</span></p></li><li><p><span class=\"fontstyle3\">- Switch to a different stance of their choice and suffer the Immobilized condition.</span></p></li></ul><h4><span class=\"fontstyle5\">New Opportunities</span></h4><p><span class=\"fontstyle5\">(op)(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">If your weapon has the Cumbersome quality, choose one additional target with vigilance lower than or equal to your original target’s vigilance per (op)(op) spent this way.</span></p>","source":{"book":"path_of_waves","page":89},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.zK3HcHrVGitDdyHt","skill":"melee"},{"name":"Pelting Hail Style","via":"General","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<p><span class=\"fontstyle0\"><em>A volley of arrows on the battlefield can be deadly, but most importantly from a strategic standpoint, it is terrifying to even the staunchest veterans. Even if only one in ten shots finds its mark, the salvo rattles opponents and forces caution.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Martial Arts [Ranged] check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(op)+: </span><span class=\"fontstyle3\">Choose a number of other characters at range 0–2 of your target equal to </span><span class=\"fontstyle4\">(op) </span><span class=\"fontstyle3\">spent this way. Each chosen character receives strife equal to the base damage of your weapon.</span></p>","source":{"book":"core_rulebook","page":181},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.y1F9eIDSu6liIhSj"},{"name":"Beseech Hida's Might","via":"General","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"ritual","rank":2,"description":"<p><span class=\"fontstyle0\"><em>Contests of strength were a favorite of the Kami Hida, and even today, spiritualists in Rokugan call upon his blessing when sanctifying an area for ritualized battle. Whether the arena is a circle for sumai or a parting of the battle lines for a field duel, it is important that it be properly respected as a place for champions to take up arms.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">Once per game session as a downtime activity or Support action, you may make a </span><span class=\"fontstyle2\">TN 2 Meditation (Fire) check </span><span class=\"fontstyle3\">targeting an area encompassing 3 range bands around yourself.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, this area becomes an </span><span class=\"fontstyle2\">arena</span><span class=\"fontstyle3\">. When a character makes a Martial Arts check in the arena during the event and does not gain strife from the check, that character reduces the TN of their next check by 1 (to a minimum of 1). This effect persists until the end of the next scene.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle5\">(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">If you succeed, the arena gains the Hallowed (fire) terrain quality until the end of the scene.</span></p><p><span class=\"fontstyle2\">(op)+: </span><span class=\"fontstyle3\">If you succeed, increase the Endurance and Composure of each character fighting a duel in the arena by 1 per (op) spent this way.</span></p><p><span class=\"fontstyle5\">(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">Reduce the TN of checks to remove the Bleeding and Dying conditions from characters within the arena by 1 per (op) spent this way (to a minimum of 1).</span></p>","source":{"book":"fields_of_victory","page":97},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.xcnbZkf9be3uhL6a","skill":"meditation"},{"name":"Cleansing Rite","via":"General","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"ritual","rank":1,"description":"<p><span class=\"fontstyle0\"><em>The ritualist sanctifies a person or group, anointing them with sacred substances that drive out unholy presences and malign sorcery.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a downtime activity, you may make a </span><span class=\"fontstyle2\">TN 3 Theology (void) check </span><span class=\"fontstyle3\">targeting up to five characters to remove spiritual contaminants from the targets before they spread. Note that this cannot remove a Shadowlands Taint disadvantage once it has taken hold, but it can prevent this spiritual contamination from taking root after a character is exposed.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, remove the Afflicted condition from the target.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle5\">(void)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">If one or more targets is an Otherworldly being, you become aware of it after completing the ritual—but you do not know which target.</span></p><p><span class=\"fontstyle5\">(void)(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">Choose one additional target per (op) spent this way.</span></p><p><span class=\"fontstyle2\">(void)(op)+: </span><span class=\"fontstyle3\">Instead of targeting characters, you may target an area that encompasses a number of range bands around you equal to (op) spent this way. Remove the Defiled terrain quality from this area. If it is a deeply unhallowed place that has long been the domain of evil, the Defiled quality returns after one day, plus additional days equal to your bonus successes.</span></p>","source":{"book":"core_rulebook","page":212},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.1lVY0jhJAeEa4Byg","skill":"theology"},{"name":"Superior Command","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":5,"kind":"title_ability","rank":1,"description":"<p><span class=\"fontstyle0\">While you are the commander of an army during a mass battle, your army’s discipline value is increased by your ranks in Command. Additionally, when making an Initiative check during a mass battle, increase the result by your ranks in Tactics.</span></p>","source":{"book":null,"page":0},"uuid":"Compendium.l5r5e-compendia-sortilege.title-abilities-l5r-sortilege.Item.TjykywguNtGuVItC"},{"name":"Falling Heavens Shot","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":5,"kind":"kata","rank":5,"description":"<p><span class=\"fontstyle0\"><em>Arrows, stones, and darts have an arc when fired, traveling not in a straight line to a target but in a curve. The better an archer understands this curve intuitively or intellectually, the better their aim. Rumors and heroic tales recount the exploits of archers with such skill that they can fire bolts straight up, predicting their landing position perfectly and using this to catch foes totally unaware.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">Once per scene as an Attack and Movement action using a readied ranged weapon, you may make a </span><span class=\"fontstyle2\">Martial Arts [Ranged] (void) check </span><span class=\"fontstyle3\">targeting one character within your weapon’s range. The TN of this check is equal to your target’s vigilance.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, at the start of your target’s next turn, they suffer a critical strike with severity equal to your weapon’s deadliness.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle5\">(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">You may delay this effect for one additional round per</span><span class=\"fontstyle5\"> (op) </span><span class=\"fontstyle3\">spent this way. For each round you delay this way, you increase the deadliness of the critical strike by 2.</span></p>","source":{"book":"path_of_waves","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.imFYWU5waLlV2aoY","skill":"ranged"},{"name":"Pin the Fan","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":5,"kind":"kata","rank":5,"description":"<p><span class=\"fontstyle0\"><em>While it is difficult to kill at range with a single arrow, it can certainly be done, and master archers have been performing legendary feats of precision since the early days of Rokugan. From Hantei Genji’s famous shots to the arrow loosed by Doji Hotaru that slew Akodo Arasou, killing shots have often changed the course of the Emerald Empire’s history.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As an Attack and Movement action using a readied ranged weapon, you may make a </span><span class=\"fontstyle2\">Martial Arts [Ranged] check </span><span class=\"fontstyle3\">targeting one character within your weapon’s range. The TN of the check is equal to the target’s vigilance plus the range of the attack.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, the target suffers damage equal to two times the weapon’s base damage plus your bonus successes.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle5\">(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">If the target becomes Incapacitated as a result of damage from this action, they suffer a critical strike with severity equal to two times the weapon’s deadliness damage plus your bonus successes.</span></p>","source":{"book":"core_rulebook","page":181},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.KQHedTdTMnZ7JyKc","skill":"ranged"},{"name":"Void Embrace Style","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":5,"kind":"kata","rank":5,"description":"<p><span class=\"fontstyle0\"><em>It is said that some martial artists of surpassing skill can give themselves over wholly to the Void for an instant, foreseeing the exact arc of an attack and completely negating it with little more than a gentle brush of the hand. Tales abound of masters who matched steel with only a flimsy reed or caught an opponent’s sword midswing, but few warriors can say they have personally seen such mastery on display.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a </span><span class=\"fontstyle2\">Meditation (void) check </span><span class=\"fontstyle3\">during a duel or skirmish, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle3\">(op)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">Choose one character you can perceive, then secretly select a number. The next time you are dealt damage by that character or suffer a critical strike inflicted by that character, reveal the number you chose. If the number is higher than the damage or the severity of the critical strike (before any reductions), you suffer it as normal and this effect ends. If the number is lower than or equal to the damage or the severity of the critical strike, reduce it by that amount, to a minimum of 0. If you reduce it to 0, the character you chose suffers 5 strife. If you reduce the severity of a critical strike to 0 this way, you do not suffer it. This effect persists until the end of your next turn.</span></p>","source":{"book":"path_of_waves","page":87},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.0XEXNrJJfykBCw0L"},{"name":"Rouse the Soul","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":5,"kind":"shuji","rank":5,"description":"<p><span class=\"fontstyle0\"><em>Many things can cloud the soul, but words can awaken it. The courtier speaks honestly and without pretension, calling upon their allies to overcome earthly circumstances and reach a mutual goal.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When making a Social skill (void) or Theology (void) check targeting one or more characters, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle4\">(void)(op)</span><span class=\"fontstyle2\">+: </span><span class=\"fontstyle3\">Remove one of the following conditions from one target per (op) spent this way: Afflicted, Enraged, Exhausted, Intoxicated, or Unconscious.</span></p>","source":{"book":"core_rulebook","page":223},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.BRfP8Lxue695uCky"},{"name":"The Immovable Hand of Peace","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":5,"kind":"shuji","rank":5,"description":"<p><span class=\"fontstyle0\"><em>The courtier calls for the warriors in the field to lay down their arms and withdraw with such unquestionable conviction that even the fires of hate are temporarily smothered.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">Once per game session as a Scheme action, during a duel or skirmish, you may make a </span><span class=\"fontstyle2\">TN 5 Command (earth) check </span><span class=\"fontstyle3\">targeting every character in the scene.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, the scene becomes an intrigue between you and the other principal characters. This effect persists for one round, plus additional rounds equal to your bonus successes. If you have not achieved a peaceful resolution by the time this effect ends, the scene returns to its previous state.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle5\">(earth)(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">You may also perform this action during a mass battle or other form of conflict (other than an intrigue).</span></p>","source":{"book":"core_rulebook","page":217},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.GihRYW4DLlFfP5pI","skill":"command"},{"name":"The Mountain Does Not Fall","xp_used":0,"xp_cost":0,"in_curriculum":true,"bought_at_rank":6,"kind":"mastery_ability","rank":6,"description":"<p><span class=\"fontstyle0\">At the beginning of your turn, you may spend 1 Void point. If you do, ignore all of your conditions, terrain, and negative persistent effects of techniques and abilities. Do not apply your disadvantages to checks. If you would die, you cling to life for a few moments longer instead (but still die when the effect ends). This effect persists until the end of your next turn.</span></p>","source":{"book":"core_rulebook","page":57},"uuid":"Compendium.l5r5e-compendia-sortilege.mastery-abilities-l5r-sortilege.Item.vmlw8mJ2texEEQ39"}],"peculiarities":[{"name":"Light Sleeper","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"water","types":"Physical","description":"<p><span class=\"fontstyle0\"><em>“You see these scars?” she asked. He nodded respectfully at the Hiruma. It looked like someone had run a rake down her face—then repeated the action several times.</em></span></p><p><span class=\"fontstyle0\"><em>“This is what you get when you dare slumber here. Everyone else died that night.” She closed her eyes for a moment, then opened them abruptly, startling him. “You rest your guard, you die.” She looked closely at him. “You learn to stay awake, even when you sleep. Or you join the rest of my old patrol.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Light Sleeper distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You rouse from sleep very easily, a trick considered essential in hostile territory. You are trained to awaken before danger arrives, sleep with your weapons ready, and pretend to be in a deep sleep to lure enemies closer. You can go from a deep sleep to fully alert and fighting in the blink of an eye.</span></p></li><li><p><span class=\"fontstyle0\">- When performing a check that calls on rapidly recovering from sleep (such as a Survival (water) check to detect a threatening sound while dozing or a Fitness (water) check to react even when someone else is standing watch), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"shadowlands","page":96},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.ZtoejR7hmjZ0aE8k"},{"name":"Encompassing Duty","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"earth","types":"Mental","description":"<p><em>“I will lay down my life for my family. Nothing will stand in the way of that.”</em></p><p><em>– Aina, Ashigaru of the Lion</em></p><p></p><p>The following apply to a character with the Encompassing Duty adversity:</p><ul><li><p>- You have a duty to something: your family, a friend, a cause, or some other person or ideal. This duty should manifest into at least one discernible goal, one you can work out with the GM. A goal may be to provide for your family, rescue a friend, or achieve a similar aim. You have a difficult time relaxing or focusing on tasks that do not somehow advance your goal, and this may manifest in several ways, including frustration, anger, worry, or nervousness. </p></li><li><p>- Whenever you make a check related to overcoming something that could hinder you in achieving your duty (such as a Meditation (earth) check to keep a cool head in an ambush or a Courtesy (earth) check to reason with a stubborn shopkeeper), you must choose and reroll two dice containing (su) or (ex) . After resolving the check, if you failed, you gain 1 Void point.</p></li></ul>","source":{"book":"path_of_waves","page":72},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.TP83fjX8gnxELunG"},{"name":"Travel","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"water","types":"Mental, Physical","description":"<p><span class=\"fontstyle0\"><em>The old man sat heavily on the stool outside the constabulary office. He removed his straw hat, wiped his brow with his sleeve, and returned the hat to his head. His eyes, shaded by the wide brim, looked out at Yūka. The young girl smiled.</em></span></p><p><span class=\"fontstyle0\"><em>“Young lady, I have been from one side of Rokugan to the other—from Khanbulak to the Islands of Silk and Spice—and I have seen amazing sights. I will tell you this: in all my travels, I have become convinced of three things.” He counted them off on gnarled fingers. “All crows are black, it always rains when you don’t want it to, and Rokugan’s greatest treasure—a prize without equal—is its people.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Travel passion:</span></p><ul><li><p><span class=\"fontstyle3\">- You are not unsettled by foreign customs, and you can comfortably fit in even in strange environments.</span></p></li><li><p><span class=\"fontstyle3\">- After performing a check to travel to a new location or interact with a novel thing (such as a Survival (water) check to try to identify a new plant, animal, or phenomenon, or a Seafaring (water) check to travel by boat), you remove 3 strife.</span></p></li></ul>","source":{"book":"core_rulebook","page":115},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.7keAIKn0N8wjEsGa"},{"name":"Battle Trauma","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"fire","types":"Mental, Physical","description":"<p><em>The thousand cuts I have borne<br>And the thousand I have delivered<br>Paint my dreams in red<br>Broad brushstrokes to draw pictures<br>I cannot put to paper.<br>Do my ears ring from old age<br>Or is that steel’s song and the warrior’s cry<br>Gone so long ago<br>But never gone?</em></p><p><strong>Effects:</strong> The following apply to a character with the Battle Trauma anxiety:</p><ul><li><p>-  At the start of a duel, skirmish, or mass battle, your hands shake, your body tenses up, or your mind might even lock down. You can act normally, but your unsettled state is obvious to everyone around you, and others may try to exploit it.</p></li><li><p>-  After performing a check related to battle (such as a Martial Arts [Melee] (fire) check to strike down a foe or a Tactics (fire) check to generate initiative), you receive 3 strife. (Your GM can choose not to inflict this strife after the you have taken a few turns and thematically overcome your trauma.) If this is the first time this has occurred this scene, gain 1 Void point.</p></li></ul>","source":{"book":"core_rulebook","page":131},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.jlSq86lbglLrHXp8"},{"name":"Paragon of Courage","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"fire","types":"Mental, Virtue","description":"<p><span class=\"fontstyle0\"><em>“The heroes of myth—even the ones who were not of divine blood—did not live as humans do. It is impossible to embody an ideal without surpassing some part of your own humanity.”</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Paragon of Courage distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You believe utterly in Courage, and others instinctively discern that your actions are genuine when you act in accordance with it.</span></p></li><li><p><span class=\"fontstyle3\">- When performing a check for which you need to convince others of, or leverage your faith in, Courage (such as a Performance check to recount a tale that impresses its importance upon others or a Martial Arts [Melee] check to take up arms for this cause), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"core_rulebook","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.trppadBbshGjbSP2"}],"titles":[{"name":"Gunsō","xp_used":24,"xp_cost":24,"in_curriculum":false,"bought_at_rank":3,"description":"<p><span class=\"fontstyle0\">While the vast majority of soldiers in a Rokugani army are ashigaru and conscripts, many samurai are called to military service, either in the armies of their own clan or in the Imperial Legions. When samurai do take to the field, they often these serve in leadership positions. While each lord's forces have their own structure and character, common titles are used throughout Rokugan to indicate similar levels of authority. When a lord gathers a large force for battle, they may nominate one or more gunsō to command the kashira who lead individual units.</span></p><p><span class=\"fontstyle0\">A gunsō is responsible for all aspects of battle readiness for the troops under their command, including the troops’ training, discipline, and equipment. When battle begins, gunsō direct their troops in accordance with commands from their superiors, meaning they have to maintain good awareness not only of their own unit but also of the broader battle unfolding around them. Perhaps most importantly, gunsō are expected to display conspicuous leadership during battle, leading their troops from the front and rallying their soldiers, keeping them in the fight even as losses mount and their morale begins to waver.</span></p><p><span class=\"fontstyle2\"><strong>Assigned By:</strong> </span><span class=\"fontstyle0\">A daimyō may assign a samurai a rank within their military forces, and samurai serving within the military rank structure may be promoted by a superior officer.</span></p><p><span class=\"fontstyle2\"><strong>Status Award:</strong> </span><span class=\"fontstyle0\">+5 (to a minimum of 20)</span></p><p><span class=\"fontstyle2\"><strong>Title Ability:</strong> Lead from the Front</span></p><h2>Curriculum</h2><table><tbody><tr><td><p>Martial Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Command</p></td><td><p>Skill</p></td></tr><tr><td><p>Government</p></td><td><p>Skill</p></td></tr><tr><td><p><a class=\"compendium-link\" data-pack=\"l5r5e.core-techniques-kata\">(kata) Rank 1-4 Kata</a></p></td><td><p>Tech. Grp.</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-shuji.Item.L5RCoreShu000020\" data-pack=\"l5r5e.core-techniques-shuji\" data-type=\"Item\" data-id=\"L5RCoreShu000020\">(shuji) Rallying Cry</a> (prereq)</p></td><td><p>Technique</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-shuji.Item.L5RCoreShu000026\" data-pack=\"l5r5e.core-techniques-shuji\" data-type=\"Item\" data-id=\"L5RCoreShu000026\">(shuji) Stirring the Embers</a> (prereq)</p></td><td><p>Technique</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-shuji.Item.L5RCoreShu000011\" data-pack=\"l5r5e.core-techniques-shuji\" data-type=\"Item\" data-id=\"L5RCoreShu000011\">(shuji) Touchstone of Courage</a> (prereq)</p></td><td><p>Technique</p></td></tr></tbody></table>","source":{"book":"emerald_empire","page":250},"uuid":"Compendium.l5r5e-compendia-sortilege.titles-l5r-sortilege.Item.2R7nNp7NWNLkVs5j"},{"name":"General","xp_used":51,"xp_cost":50,"in_curriculum":false,"bought_at_rank":5,"description":"<p><span class=\"fontstyle0\">The pinnacle of military command, a general serves as the mastermind behind all aspects of their army, seeing the will of their daimyō done through intricate planning and masterful stratagems. But there is more to a general’s duties. A general must lead by example; the expectations they have of their troops must be mirrored in their own actions. Their voice must electrify the souls of those under their command, inspiring them to charge enthusiastically to what may be their deaths. Their combat mastery must be without flaw. Their decorum and personal honor must be beyond reproach.</span></p><p><span class=\"fontstyle0\">Though it is a high honor to be given command, it can also be burdensome. Leadership is often a weary, isolating task. On their shoulders rest the will of their lord and the security of their homeland.</span></p><p><span class=\"fontstyle2\"><strong>Assigned by:</strong> </span><span class=\"fontstyle0\">A clan or family daimyō with a status of 60 or higher, often following a great military achievement by the character.</span></p><p><span class=\"fontstyle2\"><strong>Glory Award:</strong> </span><span class=\"fontstyle0\">+10</span></p><p><span class=\"fontstyle2\"><strong>Status Award:</strong> </span><span class=\"fontstyle0\">+25 (to a maximum of 85)</span></p><p><span class=\"fontstyle2\"><strong>Title Ability:</strong> Superior Command</span></p><h2>Curriculum</h2><table><tbody><tr><td><p>Social Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Martial Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Government</p></td><td><p>Skill</p></td></tr><tr><td><p>Survival</p></td><td><p>Skill</p></td></tr><tr><td><p><a class=\"compendium-link\" data-pack=\"l5r5e.core-techniques-kata\">(kata) Rank 1-2 Kata</a> (prereq)</p></td><td><p>Tech. Grp.</p></td></tr><tr><td><p><a class=\"compendium-link\" data-pack=\"l5r5e.core-techniques-rituals\">(ritual) Rank 1-3 Rituals</a> (prereq)</p></td><td><p>Tech. Grp.</p></td></tr><tr><td><p><a class=\"compendium-link\" data-pack=\"l5r5e.core-techniques-shuji\">(shuji) Rank 1-4 Shuji</a> (prereq)</p></td><td><p>Tech. Grp.</p></td></tr></tbody></table>","source":{"book":"fields_of_victory","page":133},"uuid":"Compendium.l5r5e-compendia-sortilege.titles-l5r-sortilege.Item.mHaV3dj76eYzJyGb"}],"bonds":[],"signature_scrolls":[],"gear":[{"name":"Club","quantity":1,"description":"<p><span class=\"fontstyle0\">The humble club is perhaps the oldest weapon in Rokugan—at least among humans. Often little more than a length of stout wood or shaped stone, a club can be fashioned with available materials by nearly anyone. While a club can certainly be used to kill, doing so takes some work on the part of the wielder</span>.</p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.ElFJfEcGvWe6A5yU","damage":5,"deadliness":2,"range":"0-1","grip_2":"Damage +1","skill":"melee","category":"Blunt Weapons","rarity":"1","zeni":"1 bu","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Katana","quantity":1,"description":"<p><span class=\"fontstyle0\">As much a work of art as it is a weapon, the katana is perhaps the most revered weapon in Rokugan. It has an elegant, slightly curved blade between three and four feet long, made of steel that is specially folded during its creation. This unique forging style ensures that the inner part of the blade remains springy and soft while the outside is as hard as tempered steel. Each sword likely has a history and legacy, and it is a constant reminder of the weight that destiny has placed upon its bearer’s shoulders as a samurai of Rokugan</span>.</p>","source":{"book":"core_rulebook","page":232},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.BhKwwnN5UHI5rZpp","damage":4,"deadliness":5,"range":"1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"20 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Knife","quantity":1,"description":"<p><span class=\"fontstyle0\">Knives come in a dizzying array of types and styles, from the familiar crudely constructed knife in a peasant’s kitchen to the deadly combat knives samurai take into battle. Those particularly designed for combat—like the aiguchi—are often equipped with small hand guards to make them more useful in the field.</span></p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.n8xA05Fb9WpXg3oo","damage":2,"deadliness":4,"range":"0","grip_2":"Deadliness +2","skill":"melee","category":"Hand Weapons","rarity":"1","zeni":"1 koku","properties":[{"id":"L5RCorePro000001","name":"Razor-Edged"},{"id":"L5RCorePro000005","name":"Concealable"},{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Tetsubō","quantity":1,"description":"<p><span class=\"fontstyle0\">Long and narrow, a tetsubō can be as tall as a human and normally is constructed of iron or hardwood. Above its grip, a tetsubō is covered in steel, iron, or even jade spikes or studs that add to the weapon’s lethality and crush armor or plated carapace with ease.</span></p>","source":{"book":"core_rulebook","page":234},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.CW6h0NSzTEhimQXw","damage":7,"deadliness":3,"range":"1-2","grip_1":"N/A","skill":"melee","category":"Blunt Weapons","rarity":"5","zeni":"20 koku","properties":[{"id":"L5RCorePro000006","name":"Cumbersome"},{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Wakizashi","quantity":1,"description":"<p><span class=\"fontstyle0\">Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</span></p>","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Kamayari","quantity":1,"description":"<p><span class=\"fontstyle0\">A </span><span class=\"fontstyle2\">kamayari </span><span class=\"fontstyle0\">is a spear with a hooked protrusion on one or both sides of the blade, similar to a ji. While the hook’s most obvious applications are blocking attacks and dragging foes off horseback, it also has practical noncombat applications. A shinobi might swing from a sturdy tree limb using the hook or might use it to climb a high fence. If the spear shaft has holes in it, the shinobi can use the shaft to measure distances or can slot bars into the holes to use it as a ladder. Finally, the hook is useful for carrying items on long walks.</span></p>","source":{"book":"court_of_stones","page":110},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.PsmRwhHYBz0daKi5","damage":4,"deadliness":3,"range":"2","grip_1":"N/A","skill":"melee","category":"Specialist Weapons","rarity":"7","zeni":"8 koku","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000007","name":"Snaring"}]},{"name":"Lacquered Armor","quantity":1,"description":"<p><span class=\"fontstyle0\">Heavier than ashigaru armor, lacquered armor is worn by samurai who desire a good mix of protection and grandeur, and is just at home at war as at a martial ceremony. These suits are made of thick leather or steel plates stitched or riveted to a leather backing. They protect the torso, head, upper arms, and groin, and the legs above the knee. They can also include a helmet and mask, though these are not considered integral.</span></p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.sPKkavq6O0SoxiPj","armor":{"physical":4,"supernatural":0},"rarity":"6","zeni":"25 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000006","name":"Cumbersome"},{"id":"L5RCorePro000011","name":"Wargear"}]},{"name":"Traveling Clothes","quantity":1,"description":"<p><span class=\"fontstyle0\">Traveling clothes ordinarily consist of roughspun garments designed to resist wear and tear. They can be anything from robes to a kimono or jacket and leggings and are often accentuated with a hat or cloak</span>.</p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.zcsgspz4VluSMeI0","armor":{"physical":2,"supernatural":0},"rarity":"2","zeni":"2 bu","properties":[{"id":"L5RCorePro000015","name":"Durable"},{"id":"L5RCorePro000012","name":"Mundane"},{"id":"L5RCorePro000016","name":"Subtle"}]},{"name":"Traveling pack","quantity":1,"description":"<p><span class=\"fontstyle0\">Blanket, bowl, chopsticks, four days of travel rations, flint and tinder, and any three other items of the player’s choice that are rarity 4 or lower.</span></p>","source":{"book":"core_rulebook","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.Rex7fGo6R1KuUhQJ","rarity":"1","zeni":"10 koku","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Kubi Bukuro","quantity":1,"description":"<p>These are simple net bags used to carry the severed head of an enemy, which is considered both a trophy and a good omen. Lion Clan samurai use them to carry their trophies without touching dead flesh, but the Kuni family uses them for collecting samples of Shadowlands creatures for study.</p>","source":{"book":"core_rulebook","page":242},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.6J25vJx1tVirgXf1","rarity":"2","zeni":"2 zeni","properties":[{"id":"L5RCorePro000011","name":"Wargear"}]}]}]};
